const SUBJECTS = [
{id:'curriculum',name:'교육과정',units:[
{id:'u1',name:'교육과정의 유형(타일러·파이나 등)',items:[
{t:'교육과정 결정에 영향을 미치는 세 가지 요소는 [교과], [사회], [학습자]이다. 가나다 순으로 작성하시오.',m:null},
{t:'청소년의 관심을 끄는 사회의 문제와 쟁점을 중심으로 여러 교과의 내용을 통합적으로 구성한 교육과정을 [중핵] 교육과정이라 한다.',m:null},
{t:'잠재적 교육과정의 기본적 개념은 [계획]하거나 [의도]하지 않았지만 학생들이 [학교교육]을 통해 은연중에 겪게 되는 [경험]을 말한다.',m:null},
{t:'확장된 개념의 잠재적 교육과정은 [숨겨져 있는] 교육과정이며, [고의적]으로 의도된 것으로, [부정적] 측면을 강조하고 있다.',m:null},
{t:'잭슨이 제시한 잠재적 교육과정의 구성 요소 3가지는 [군중], [상찬], [권력]이다.',m:null},
{t:'잠재적 교육과정은 주로 [정의적] 영역과 관련되어 있다.',m:null},
{t:'잠재적 교육과정은 주로 학교의 [문화풍토]와 관련되어 있다.',m:null},
{t:'잠재적 교육과정은 교육과정 의미의 [확장]에 기여하였고, 학교교육의 [사실적 진술]에 관심을 갖게 하고, 학교교육과 교육과정의 [효율성] 향상에 기여하였다.',m:null},
{t:'영 교육과정의 기본적 개념은 공식적 교육과정에서 [제외]되어 학습자들이 아직 경험하지 못한 교육과정을 의미한다.',m:null},
{t:'교육과정 구성 과정에서 영 교육과정이 발생하는 원인은 [의욕부족], [무지], [타성]이 있다.',m:null},
{t:'교육과정 운영 측면에서 영 교육과정이 발생하는 원인은 [의도적 배제], [실수], [수업 환경 부적합], [수업 시간 부족]이 있다.',m:null},
{t:'영 교육과정을 새롭게 조명하면 공식적 교육과정이 더 [풍성]해질 수 있다.',m:null},
{t:'타일러의 논리의 절차는 [교육목표 설정], 학습경험의 [선정], [학습경험의 조직], [평가] 순이다.',m:null},
{t:'블룸은 인지적 영역을 [복잡성]을 기준으로 [여섯] 영역으로 세분화 하였다.',m:null},
{t:'블룸은 인지적 영역을 [지식]-[이해]-적용-[분석]-[종합]-[평가]로 세분화 하였다.',m:null},
{t:'블룸은 정의적 영역을 [내면화]를 기준으로 [다섯] 영역으로 세분화 하였다.',m:null},
{t:'블룸은 정의적 영역을 감수-[반응]-[가치화]-[조직화]-[가치] 또는 [가치복합]에 의한 인격화로 세분화 하였다.',m:null},
{t:'메이거의 교육목표 진술 구체화 원칙 3가지는 [종착행동], [조건], [수락기준]이다.',m:null},
{t:'메이거의 교육목표 진술 구체화 중 학습자가 목표에 도달한 증거는 [종착행동]이다.',m:null},
{t:'메이거의 교육목표 진술 구체화에서 학생의 종착행동의 성취가 어느 정도로 정확할 때 목표가 달성되었다고 판정할 수 있는가의 기준인 [수락기준]을 제시해야한다.',m:null},
{t:'브루너가 제안한 인간의 인지적 발달 3단계의 순서는 [감각운동적] 단계, [영상적] 단계, [상징]적 단계 순이다.',m:null},
{t:'브루너와 관련되는 교육과정 사조의 명칭은 [학문중심] 교육과정이다.',m:null},
{t:'브루너가 강조한 교육과정 내용의 명칭은 [지식의 구조]이다.',m:null},
{t:'교육과정의 재개념화에서 개인의 내부로부터 그 현상과 원인을 찾으려고 한 접근 방식은 [실존적] 접근이다.',m:null},
{t:'교육과정의 재개념화에서 개인에 영향을 주는 외부 세계의 조건에 초점을 맞춘 접근 방식은 [구조적] 접근이다.',m:null},
{t:'파이나의 쿠레레 방법론의 절차는 [회귀]-[전진]-[분석]-[종합]이다.',m:null},
{t:'파이나의 쿠레레 방법론의 절차 중 현재 상태를 자각하는 과정은 [분석]이다.',m:null},
{t:'파이나의 쿠레레 방법론의 절차 중 나의 현재를 이해하는 과정은 [종합]이다.',m:null},
]},
{id:'u2',name:'재개념화(애플·아이즈너)',items:[
{t:'구조적 재개념화의 기본적 주제는 인간의 [정치적] 해방이다.',m:null},
{t:'애플은 [학교교육]과 [교육과정]에 대해 비판하면서 오늘날의 학교는 기성세대가 갖는 사회체제와 권력 관계를 다음 세대에 그대로 전달하는 [문화재생산]의 기능을 한다고 비판하였다.',m:null},
{t:'애플은 [컴퓨터] 교육에 대해 비판하면서 교사들의 전문성이 녹슬고, 아동들의 계층 간, 성별 간 차별이 심화될 위험이 높아진다고 비판하였다.',m:null},
{t:'애플은 [잠재적] 교육과정의 부정적 측면을 강조하였다.',m:null},
{t:'미학적(예술적) 재개념화는 타일러의 [행동목표]를 비판하면서 [질적] 평가의 중요성을 강조하였다.',m:null},
{t:'아이즈너는 수업을 시작하기 전에 미리 [행동목표]의 형태로 [구체화]하여 진술하는 것은 불가능하다고 주장했다.',m:null},
{t:'아이즈너는 행동목표는 [과목]의 특성을 전혀 고려하지 않는다고 주장했다.',m:null},
{t:'아이즈너는 전통적인 행동목표 외에도 [문제해결 목표]와 [표현적 결과]로 두 가지 형태가 더 존재할 수 있다고 주장했다.',m:null},
{t:'아이즈너의 교육목표에서 [문제해결 목표]는 일정한 조건 내에서 문제의 해결책을 발견하는 것을 특징으로 갖는다.',m:null},
{t:'아이즈너의 교육목표에서 [표현적 결과]는 조건과 정답이 존재하지 않는다.',m:null},
{t:'아이즈너의 교육목표에서 [표현적 결과]는 활동의 목표가 사전에 정해지지 않고 활동하는 도중에 형성이 가능하다.',m:null},
{t:'문제해결 목표와 표현적 결과는 평가방식으로 [질적] 평가와 [교육적 감식안]을 사용한다.',m:null},
{t:'아이즈너가 제시한 질적 평가의 종류는 [참평가], [교육적 감식안], [교육비평]이다.',m:null},
{t:'[교육적 감식안]은 학생들의 수행 사이의 미묘한 차이를 구별할 수 있는 전문적 능력이다.',m:null},
{t:'[교육비평]은 수행 결과와 과정의 미묘한 차이를 비전문가도 이해할 수 있도록 언어로 표현하는 능력이다.',m:null},
{t:'아이즈너는 [영 교육과정]을 강조하였다.',m:null},
{t:'중앙집중적 교육과정 개발은 전국의 모든 학교에 공통적인 교육과정을 제공함으로써 학교교육의 [수준]과 [질]을 조절할 수 있다.',m:null},
{t:'중앙집중적 교육과정 개발은 [지속성]이 보장되며, 학생이 학교를 옮긴다 할지라도 교육의 [계속성]이 보장되고, [전문성]이 높다.',m:null},
{t:'중앙집중적 교육과정 개발 과정에서 [교사]가 배제되고, 학교수준에서의 시행 전락이 부족하다.',m:null},
{t:'중앙집중적 교육과정 개발은 전국적으로 표준화된 하나의 교육과정을 제시하기 때문에 학교교육의 [획일화]를 가져오기 쉽다.',m:null},
{t:'학교중심 교육과정 개발은 교육의 [효율성] 및 [적합성] 향상과 교원의 [자율성]과 [전문성] 신장을 위해 필요하다. 또한 교육의 [다양성]을 추구하여 획일성을 극복할 수 있고, [학습자] 중심의 교육을 구현하기 위해 필요하다.',m:null},
{t:'학교중심 교육과정 편성&운영의 기본 원리에는 [타당성]의 원리, [적법성]의 원리, [전체성]의 원리, [민주성]의 원리, [전문성]의 원리, [현실성]의 원리가 있다.',m:null},
{t:'학교중심 교육과정 편성&운영의 기본 원리에는 [타당성]의 원리, [적법성]의 원리, 전체성의 원리, 민주성의 원리, 전문성의 원리, [현실성]의 원리가 있다.',m:null},
{t:'학교중심 교육과정 편성&운영의 기본 원리에는 타당성의 원리, [적법성]의 원리, 전체성의 원리, [민주성]의 원리, [전문성]의 원리, 현실성의 원리가 있다.',m:null},
{t:'학교 수준 교육과정 개발의 구체적인 형태는 교육과정의 [재구성], 교과목의 탄력적인 편성, 교과목의 [신설], 수업시간의 탄력적인 편성 및 운영이 있다.',m:null},
{t:'학교 수준 교육과정 개발의 구체적인 형태 중 교과목의 탄력적인 편성의 대표적인 예시는 [집중이수제]이다.',m:null},
{t:'학교 수준 교육과정 개발의 구체적인 형태 중 수업 시간의 탄력적인 편성 및 운영의 대표적인 예시는 [블록타임제]이다.',m:null},
{t:'교육과정 개발의 일반적 절차는 [목표설정] - [교육내용 선정] - [교육내용 조직] - 평가 순이다.',m:null},
{t:'교육목표 설정 자원은 [교과], [사회], [학습자]이다. 가나다 순으로 작성하시오.',m:null},
{t:'교육목표 설정의 원칙은 [포괄성]의 원칙, [적절성]의 원칙, [균형성]의 원칙, [체계성]의 원칙, [달성가능성]의 원칙이 존재한다.',m:null},
{t:'타일러의 행동목표(명세목표)는 [교육내용]과 [학습행동]의 요소가 모두 포함되어야 한다. 지도해야 할 [내용영역]과 [행동영역]이 동시에 진술되어야한다.',m:null},
{t:'메이거의 행동목표(명세목표)는 학습자가 수행할 [종착행동]과 행동이 일어나는 [조건], 목표의 달성 여부를 판단할 수 있는 [수락기준]을 제시한다.',m:null},
{t:'Gronlund의 행동목표(명세목표)는 일반적인 수업목표와 세부적인 수업목표를 구분하여 진술하되 [명사화]된 동사를 사용하여 진술을 간소화하여 제시한다.',m:null},
{t:'행동목표는 무엇을 가르쳐야 하는지, 어떤 수업 방법과 평가가 사용되어야 하는지에 대한 분명한 [방향]을 제시하고, 학부모와 학생들과의 분명한 [의사소통]을 가능하게 한다.',m:null},
{t:'수업을 통해 기대되는 결과와 의도하지 않은 결과는 사전에 [구체화]된 행동목표로 진술될 수 없다.',m:null},
{t:'행동목표는 교과의 [특성]에 따라 다르게 적용될 수 있다.',m:null},
{t:'행동목표를 세밀하고 구체적으로 명세화하면 할수록 [타당성]은 줄어들게 된다.',m:null},
{t:'교육과정 선정의 원리는 타일러의 원리에 근거하여 [기회]의 원리, [만족]의 원리, [가능성]의 원리, [다경험]의 원리, [다성과]의 원리가 있다.',m:null},
{t:'교육과정 선정의 원리 중 단일의 교육목표 달성을 위해 복수의 다양한 기회가 제공되는 것은 [다경험]의 원리이다.',m:null},
{t:'교육과정 선정의 원리 중 하나의 학습경험이라도 다양한 교육목표를 달성하는 것은 [다성과]의 원리이다.',m:null},
{t:'교육과정 선정의 원리 중 학습경험은 현재 수준에서 성공적으로 할 수 있어야 하는 것은 [가능성]의 원리이다.',m:null},
{t:'교육내용의 조직은 동일 학년 내 내용의 배열 문제를 가리키는 [수평적] 측면과 내용의 학년 간 배열 문제를 가리키는 [수직적] 측면으로 나뉜다.',m:null},
{t:'교육내용 조직의 수평적 측면에는 [균형], [범위], [통합], 수평적 [연계]가 있다. 가나다 순으로 작성하시오.',m:null},
{t:'교육내용 조직의 수직적 측면에는 [계속성], [계열], 수직적 [연계]가 있다. 가나다 순으로 작성하시오.',m:null},
{t:'교육내용의 조직에서 [범위]는 교육과정에서 다룰 내용의 폭과 깊이를 말한다. [폭]은 어떤 교과나 활동을, [깊이]는 어느 정도의 시간을 뜻한다.',m:null},
{t:'교육내용의 조직에서 [통합]은 교육과정의 내용으로 포함될 수 있는 모든 유형의 지식과 경험을 서로 연결 짓는 것이다.',m:null},
{t:'교육내용의 조직에서 [계속성]은 동일한 개념이나 기능을 계속해서 반복적으로 다루어야 한다는 것을 의미한다.',m:null},
{t:'교육내용의 조직에서 [계열]은 학생들이 학습내용이나 경험을 접하게 되는 순서를 의미한다.',m:null},
{t:'교육내용의 조직에서 [수직적] 연계는 학교급 간이나 학년 간의 접합점에서의 특정 내용 요소간의 가연스러운 관계 맺음을 강조한다.',m:null},
{t:'교육내용의 조직에서 [수평적] 연계는 동일 학년 내 교과 간에 내용 요소들이 동일한 수준으로 다루어질 수 있도록 조직해야 한다는 것을 강조한다.',m:null},
{t:'교육내용의 조직에서 [균형]은 교육과정의 여러 측면을 조화롭게 담아내야 한다는 것을 의미한다.',m:null},
{t:'교육과정 [통합]은 교과 간의 구분을 고려하지 않고, 교사와 학생들이 협동적으로 결정한 의미 있는 문제와 쟁점 중심으로 교육과정을 조직하는 것이다.',m:null},
{t:'교육과정 통합의 유형은 다학문적 통합, [간학문적] 통합, [초학문적] 통합이 있다.',m:null},
{t:'[간학문적] 통합은 교과 간 엄격한 경계가 무너진다.',m:null},
{t:'[초학문적] 통합은 개별 교과의 [정체성]을 인정하지 않으며, 교과 간의 경계가 사라진다.',m:null},
{t:'교육과정 통합 유형 중 학생참여형에 가까운 유형은 [초학문적] 통합니다.',m:null},
{t:'추출된 개념 교과의 내용을 선정된 주제의 학습에 적합하도록 수정을 거치는 것은 [간학문적] 통합이다.',m:null},
{t:'초학문적 통합에서 교사의 역할은 [촉진자]이고, 학생의 역할은 [탐구자]이다.',m:null},
{t:'타일러의 전통적(합리적) 교육과정 개발모형은 개발자들이 주로 [의존]해 온 대표적인 모형이다.',m:null},
{t:'타일러의 전통적(합리적) 교육과정 개발모형의 절차는 [목표설정] - [학습경험의 선정] - [학습경험의 조직] - [평가]이다.',m:null},
{t:'타일러의 전통적(합리적) 교육과정 개발모형의 목표설정 단계에서 [교과], [사회], [학습자] 등의 자원을 활용하여 [잠정적] 교육목표를 도출하고, [교육철학](제1의 체)과 [학습심리학](제2의 체)이라는 체에 걸러 [구체적] 교육목표를 도출한다.',m:null},
{t:'타일러의 전통적(합리적) 교육과정 개발모형 중 교육목표에는 학습자의 [행동]과 [내용]이 진술되어야하고, 명확히 [세분], [행동적]으로 진술되어야 한다.',m:null},
{t:'타일러의 전통적(합리적) 교육과정 개발모형에서 학습경험의 선정원리는 [기회]의 원리, [만족]의 원리, [가능성]의 원리, [다경험]의 원리, [다성과]의 원리이다.',m:null},
{t:'타일러의 전통적(합리적) 교육과정 개발모형에서 학습경험의 조직 기준은 수직적 원리로 [계속성], [계열성]이 있고, 수평적 원리로 [통합성]이 있다.',m:null},
{t:'타일러의 전통적(합리적) 교육과정 개발모형에서 학습경험의 조직 구조는 [상층]구조, [중층]구조, [하층]구조로 나뉜다.',m:null},
{t:'[상층]구조는 교육과정의 전체적인 테두리를 결정하고, 교과구조, [광역]구조, [중핵]구조, 활동구조 등으로 구분된다.',m:null},
{t:'[중층]구조는 교육과정의 큰 테두리가 정해딘 뒤 각 하위 영역의 조직을 결정하는 문제로서 [계열]구조와 [비계열]구조로 나눌 수 있다.',m:null},
{t:'타일러의 전통적(합리적) 교육과정 개발모형은 교육과정 개발 시 직면하게 되는 문제에 대해 합리적으로 해결해주는 [처방적] 모형이다.',m:null},
{t:'타일러의 전통적(합리적) 교육과정 개발모형은 [교사배제] 교육과정의 성격을 가져 교육과정 [사소화] 현상이 발생할 수 있다.',m:null},
{t:'타일러의 전통적(합리적) 교육과정 개발모형은 폭넓은 [유용성]이 있어 따라 하기가 비교적 쉽고, 평가에 매우 광범한 지침을 제공하나 직접적인 답을 제공하지는 못한다. 또한 목표를 내용보다 우위에 두고 내용을 목표 달성을 위한 [수단]으로 전략시킨 측면이 존재한다.',m:null},
{t:'타바의 확장모형은 교육과정 개발 주체를 [교사]로 설정하고, 실험적 단원을 생성하고 이를 검증-확산-정착시키는 [상향]식 교육과정 개발 절차를 제안하였다.',m:null},
{t:'타바의 확장모형은 학생들의 필요를 파악하는 [요구 진단] 절차를 거친다.',m:null},
{t:'타바의 확장모형은 현장 [교사]가 교육과정 개발에 참여하여 현장지향적이고, 교육과정과 수업을 함께 고려하여 [이론]과 [실제]를 결합하고자 하였다.',m:null},
{t:'타바의 확장모형 교육과정 개발은 [귀납적]으로 이루어진다.',m:null},
{t:'타바의 확장모형은 교육과정 전체를 관통하는 시각을 형성하지 못하고 [개별 교과] 수준에서 교육과정 개발이 한정될 수 있다.',m:null},
{t:'[숙의]는 실제적 문제를 해결하기 위한 과정으로 문제를 이해하고, 문제에 대한 알맞은 대안책을 창출하여 비교 검토하고, 대안의 결과를 고려하여 가장 최고의 행동 방향을 선택하거나 밝혀 가는 과정을 의미한다.',m:null},
{t:'워커의 [자연주의적] 모형은 실제 상황에서 교육과정이 어떻게 개발되는가를 기술하며, 발견한 것을 토대로 교육과정 개발 과정을 설명하는 틀이다.',m:null},
{t:'워커의 숙의모형 절차는 [토대다지기]-[숙의]-[설계] 순서이다.',m:null},
{t:'워커의 숙의모형 절차 중 참여자들의 다양한 견해를 표방하는 단계는 [토대다지기]이다.',m:null},
{t:'워커의 숙의모형 절차 중 다양한 대안들에 대한 논쟁을 거쳐 합의 과정에 이르는 단계는 [숙의]이다.',m:null},
{t:'워커의 숙의모형 절차 중 선택한 대안을 실천 가능한 것으로 구체화하는 단계는 [설계]이다.',m:null},
{t:'워커의 자연주의적 모형은 결과보다는 의사결정 과정이나 절차에 초점을 두어 [과정지향적]이고, 교육과정 개발자들이 실제로 따르고 있는 절차를 보여주어 [기술적]이며, 타일러의 처방적 모형과 차이가 있다.',m:null},
{t:'워커의 자연주의적 모형은 자양한 의견을 [수용]하고 [조율]한다는 숙의 단계를 거친다는 장점을 가진다.',m:null},
{t:'워커의 자연주의적 모형은 전적으로 교육과정 [계획]에만 초점을 맞추고 있어 교육내용에 대한 직접적인 답을 제공하지 못한다.',m:null},
{t:'위긴스와 맥타이는 전통적 교육과정 설계모형에 대한 비판으로 학생의 [이해력]을 신장하는 [백워드] 설계모형을 추구하였다.',m:null},
{t:'위긴스와 맥타이의 백워드 설계모형은 타일러 모형의 절차를 변형시켜 [목표 달성]을 위해 [평가]를 강조한 모형이다.',m:null},
{t:'위긴스와 맥타이의 백워드 설계모형의 절차는 [바라던 결과의 확인] - [수락할 만한 증거의 결정] - [학습경험과 수업의 계획] 순서이다.',m:null},
{t:'위긴스와 맥타이의 백워드 설계모형은 목표설정 과정에서 교과의 내용 기준을 반영하여 [국가교육과정] 기준과 [현장]의 수업을 일치시킬 수 있다.',m:null},
{t:'위긴스와 맥타이의 백워드 설계모형은 [이해중심] 교육과정이라고도 한다.',m:null},
{t:'이해중심 교육과정에서 목표를 설정하는 단계는 [바라던 결과의 확인]이다.',m:null},
{t:'위긴스와 맥타이의 백워드 설계모형 절차 중 목표를 설정하는 단계는 [바라던 결과의 확인]이다.',m:null},
{t:'이해중심 교육과정의 이해는 목표의 다른 표현이고, [설명], [해석], [적용], [관점], [공감], [자기지식]으로 구성되어 있다.',m:null},
{t:'이해중심 교육과정에서 평가를 계획하는 단계는 [수락할 만한 증거의 결정]이다.',m:null},
{t:'위긴스와 맥타이의 백워드 설계모형 절차 중 평가를 계획하는 단계는 [수락할 만한 증거의 결정]이다.',m:null},
{t:'이해중심 교육과정에서 교육내용을 계획하는 단계는 [학습경험과 수업의 계획]이다.',m:null},
{t:'위긴스와 맥타이의 백워드 설계모형 절차 중 교육내용을 계획하는 단계는 [학습경험과 수업의 계획]이다.',m:null},
{t:'이해중심 교육과정의 장점은 [국가교육과정] 기준과 현장의 [수업]을 일치시킬 수 있고, 교과서 중심의 수업이나 평가를 대비하는 수업에서 [교육과정] 중심의 수업으로 전환이 이루어진다.',m:null},
{t:'이해중심 교육과정의 단점은 [목표]-[수단] 패러다임을 따르고 있어 설정된 기준이나 목표가 당연시될 가능성이 있고, 평가에 대한 계획을 먼저 수립하기 때문에 평가 [의존]적인 수업 활동이 전개될 가능성이 있다.',m:null},
{t:'아이즈너는 [교육적 상상력]이라는 예술적 접근의 교육과정 개발 방안을 제시했다.',m:null},
{t:'아이즈너의 예술적 교육과정 개발모형의 목표는 [행동목표], [문제해결목표], [표현적 결과]이다.',m:null},
{t:'아이즈너의 예술적 교육과정 개발모형에서 교육과정은 [영 교육과정]을 고려한다.',m:null},
{t:'아이즈너의 예술적 교육과정 개발모형은 [교육적 상상력]을 통해 학습자에게 [다양한 학습기회]를 제공한다.',m:null},
{t:'아이즈너의 예술적 교육과정 개발모형은 학생들의 다양한 성취결과를 장력하기 위한 [비선형적] 접근을 강조한다.',m:null},
{t:'아이즈너의 예술적 교육과정 개발모형은 [범교과적] 내용의 조직을 강조한다.',m:null},
{t:'아이즈너의 예술적 교육과정 개발모형은 학생들의 교육 기회를 넓히기 위한 다양한 [의사소통] 양식을 활용하고, 이를 [제시] 양식과 [반응] 양식이라고 한다.',m:null},
{t:'아이즈너의 예술적 교육과정 개발모형의 평가 절차의 유형은 [참평가], [교육적 감식안], [교육비평]이 있다.',m:null},
]},
{id:'u3',name:'교육과정 개발·설계모형(스킬벡 등)',items:[
{t:'스킬벡의 학교중심 교육과정 개발모형에서 개별 학교의 상황 특성에 맞는 교육과정을 개발하게 하는 절차는 [상황분석]이다.',m:null},
{t:'스킬벡의 학교중심 교육과정 개발모형은 5단계의 [어느 시점에서나] 개발을 시작할 수 있어서 [개방적] 접근이 가능하며 [상호작용적]이다.',m:null},
{t:'스킬벡의 학교중심 교육과정 개발모형의 절차는 [상황분석] - [목표설정] - 프로그램 구성 - [판단과 실행] - 모니터링, 피드백, 평가, 재구성으로 이루어져 있다.',m:null},
{t:'스킬벡의 학교중심 교육과정 개발모형 중 [상황분석]에서는 교육과정 개발 상황 구성 요인을 [외적] 요인과 [내적] 요인으로 분류하여 분석한다.',m:null},
{t:'스킬벡의 학교중심 교육과정 개발모형 중 상황분석에서 학교의 외적 요인은 [사회]와 문화의 변화, [학부모]의 기대, [교육정책] 형성 등이 있다.',m:null},
{t:'스킬벡의 학교중심 교육과정 개발모형 중 상황분석에서 학교의 내적 요인은 [학습자]의 적성과 능력, [교사]의 가치관과 태도, 학교의 [풍토] 및 [시설] 등이 있다.',m:null},
{t:'스킬벡의 학교중심 교육과정 개발모형 중 프로그램 구성에서는 [교수]-[학습]활동과 [교육환경]을 설계하고, 교직원 인적자원 역할 부여와 적절한 배치, 시간표 및 규정 계획 등이 이루어진다.',m:null},
{t:'스킬벡의 학교중심 교육과정 개발모형 중 [판단과 실행]에서는 교육과정에 변화를 야기할 수 있는 문제를 규멍하고, [검토]-[분석]-[예측]을 통해 문제를 해결한다.',m:null},
{t:'스킬벡의 학교중심 교육과정 개발모형은 교사들이 [현실적]으로 적용 가능하고, 개발자의 자율성을 발휘할 수 있는 [융통성]을 가진 구조로 학교 현장의 교육적 상황을 잘 반영한다. (장점)',m:null},
{t:'스킬벡의 학교중심 교육과정 개발모형은 자율적이어서 [혼란]을 야기할 수 있고, 목표설정이 선행되지 않을 시 [방향성]이 부족해질 수 있다.',m:null},
{t:'스킬벡의 학교중심 교육과정 개발모형은 [상황분석] 등을 포함하고 있어 개발의 소요시간이 비교적 길어질 수 있다.',m:null},
{t:'교육과정 설계모형은 강조점에 따라 [과정]모형, [내용]모형, [목표]모형으로 분류할 수 있다. 가나다순으로 작성하시오.',m:null},
{t:'교육과정 설계모형 중 [내용]모형은 사회의 문화를 전달하는데 관심을 두어야 한다는 관점으로부터 출발하였다.',m:null},
{t:'교육과정 설계모형 중 [목표]모형과 관련된 학자는 보비트와 타일러가 있다.',m:null},
{t:'교육과정 설계모형 중 [과정]모형에서 출발점은 학생의 역량이나 발달이다.',m:null},
{t:'교육과정 실행 관점은 [충실성] 관점, [상호작용] 관점, [교육과정 생성] 관점이 있다.',m:null},
{t:'교육과정 실햄 관점 중 충실성 관점은 교육과정을 원래 [의도]대로 이행하는 것으로 규정하는 관점이다. 예상과 다른 결과를 얻게 되면 그것은 오류나 [실패]로 간주한다.',m:null},
{t:'교육과정 실행 관점 중 [충실성] 관점은 교육과정 실행의 과정보다 결과물에 괌심을 둔다.',m:null},
{t:'교육과정 실행 관점 중 [충실성] 관점에서 계획된 교육과정은 가능한 한 [해석]의 다양성과 [해석]될 여지를 [최소화]해야 한다.',m:null},
{t:'교육과정 실행 관점 중 충실성 관점은 쟁점 사항 문제에 대해 구체적인 처방 제시가 가능하지만, 교사를 피동적인 수령자로 간주하고, 현장의 [특수성]을 고려하지 않아 의도한 바의 교육 변화를 이끌어 내는 데에 한계를 가진다.',m:null},
{t:'교육과정 실행 관점 중 충실성 관점에서 교사의 역할은 교육과정의 [사용자]이다.',m:null},
{t:'교육과정 실행 관점 중 [상호적응적] 관점은 교육과정 계획과 실행은 상호적 관계에 있다는 입장이다.',m:null},
{t:'교육과정 실행 관점 중 상호적응적 관점은 교육과정을 실행에서 해석, 적용, 변형 단계에 초점을 두어 교사는 자신의 기존 관점을 [수정]하고, 동시에 자신의 관점에 따라 개발자의 계획을 [재계획]하고 [수정]한다.',m:null},
{t:'교육과정 실행 관점 중 상호적응적 관점에서 교사의 역할은 교육과정의 [번안] 및 [적용자]이다.',m:null},
{t:'교육과정 실행 관점 중 [형성적] 관점은 교사와 학생이 함께 만들어 나가는 교육경험을 중심으로 교육과정 실행의 성격을 규정한다.',m:null},
{t:'교육과정 실행 관점 중 형성적 관점은 교사를 교육과정 [개발자]로 간주하여 책임감을 갖도록 격려한다.',m:null},
{t:'교육과정 실행 관점 중 [형성적] 관점에서는 생성 관점에서 분명한 설명이 불가하다.',m:null},
{t:'교육과정 실행 관점 중 형성적 관점에서 교사의 역할은 교육과정의 [창작] 및 [창조자]이다.',m:null},
{t:'교육과정 운영의 기본 원리는 [타당성]의 원리, [합법성]의 원리, [민주성]의 원리, [학습자 중심]의 원리, [자율성]의 원리, [책무성]의 원리가 있다.',m:null},
{t:'교육과정 운영의 기본 원리 중 [타당성]의 원리는 교육과정의 편성과 운영이 교육목표 달성을 지향해야 한다는 의미를 내포하고 있다.',m:null},
{t:'교육과정 운영의 기본 원리 중 [합법성]의 원리는 모든 교육과정 운영은 합법적이어야 한다는 의미를 내포하고 있다.',m:null},
{t:'교육과정 운영의 기본 원리 중 [민주성]의 원리는 교육과정 운영의 의사결정이 민주적이어야 한다는 의미를 내포하고 있다.',m:null},
{t:'교육과정 운영의 기본 원리 중 [학습자 중심]의 원리는 교육과정 운영에 있어서 학습자 중심으로 사고하고 지원해야 한다는 의미를 내포하고 있다.',m:null},
{t:'교육과정 운영의 기본 원리 중 [자율성]의 원리는 외부의 영향에서 상대적 자율성을 지니고 교육과정을 운영해야 한다는 의미를 내포하고 있다.',m:null},
{t:'교육과정 운영의 기본 원리 중 [책무성[의 원리는 제시한 교육목표를 학습자들이 적정한 수준으로 달성하기까지 책임을 져야 한다는 의미를 내포하고 있다.',m:null},
{t:'교육과정의 사조의 시대적 순서는 [교과중심] 교육과정 - [경험중심] 교육과정 - [학문중심] 교육과정 - [인간중심] 교육과정이다.',m:null},
{t:'[교과중심] 교육과정은 교육과정의 중심이 되는 내용을 교과로 하는 교육과정이다.',m:null},
{t:'교과중심 교육과정의 목표는 인간을 [사회적] 존재로 만들어주는 [문화전통]의 전수이다.',m:null},
{t:'교과중심 교육과정의 교과는 인류 [문화]의 핵심적인 것을 체계적으로 조직해 놓은 것이다.',m:null},
{t:'교과중심 교육과정은 문화유산의 핵심을 교육과정으로 보기에 [논리적]이고 [체계적]이다.',m:null},
{t:'교과중심 교육과정은 [교사중심]적이고, 설명 위주의 [강의식] 교수법으로 진행된다.',m:null},
{t:'교과중심 교육과정은 인간의 능력을 교과를 통해 계발할 수 있다고 보는 [형식도야설]을 근거로 하고 있다.',m:null},
{t:'교과중심 교육과정은 내용 조직의 형태로 [분과형] 교육과정, [상관형] 교육과정, [융합형] 교육과정, [광역형] 교육과정으로 세분화된다.',m:null},
{t:'교과중심 교육과정 중 상관형 교육과정은 각 교과의 선을 유지하면서 교과를 서로 연관시켜 조직 및 [배치]하는 형태이다.',m:null},
{t:'교과중심 교육과정 중 [융합형] 교육과정은 교과의 성질을 유지하며 공통요인만을 추출하여 조직하는 형태이다.',m:null},
{t:'교과중심 교육과정 중 [광역형] 교육과정은 관련된 교과들을 하나의 학습 영역으로 통합하여 조직하는 형태이다.',m:null},
{t:'화학과 생명과학 간의 관계 요소를 추출하여 생화학을 조직하는 것은 [융합형] 교육과정의 예시이다.',m:null},
{t:'물리, 화학, 생물, 지구과학을 통합하여 과학으로 하는 경우는 [광역형] 교육과정의 예시이다.',m:null},
{t:'교과중심 교육과정은 [체계적] 교수학습이 가능하고 교사의 수업 전개가 비교적 수월하다. 또한 [객관적]인 편가기준으로 평가 및 측정이 용이하다.',m:null},
{t:'교과중심 교육과정은 단편적인 지식 주입으로 [수동적]인 학습태도가 발생하고, 암기에 치중하여 [고등정신능력] 함양이 어렵다.',m:null},
{t:'[경험중심] 교육과정은 학생의 흥미와 요구를 중심으로 내용과 활동을 구성하는 교육과정이다.',m:null},
{t:'경험중심 교육과정의 대표적인 학자인 듀이는 [아동]중심과 [진보주의]와 연관성이 있다.',m:null},
{t:'듀이는 경험의 계속적인 [재구성]을 통한 경험의 [성장]을 목표로 하였고, 경험의 능동적 측면과 수동적 측면의 관계를 파악하는 [반성적 사고](경험)을 중시하였다.',m:null},
{t:'듀이는 교육자의 교과와 학습자의 교과를 정리하고, 아동의 경험이 계속적으로 성장하도록 도와 최종 발달 단계에서는 교육자의 교과와 학습자의 교과가 [일치]하게 되는 것으로 목표로 하였다.',m:null},
{t:'경험의 성장을 위한 아동의 의미 있는 교과 발달의 3단계는 놀이나 일 - [지리]나 [역사] - [과학]과 논리 순이다.',m:null},
{t:'경험중심 교육과정의 목표는 [생활인]의 육성이다.',m:null},
{t:'경험중심 교육과정의 교과는 학교의 [지도]하에 학생들이 가지는 경험의 모든 것으로 [교과]활동과 [비교과]활동을 혼합한 것이다.',m:null},
{t:'경험중심 교육과정은 현재 생활에 필요한 [실용적] 교육을 중시하여 [생활인] 육성을 추구했다.',m:null},
{t:'경험중심 교육과정은 [비교과] 활동을 중시하고, 교사와 학생 간의 [상호작용]을 통해 도출할 수 있는 활동을 중시한다.',m:null},
{t:'경험중심 교육과정은 내용 조직의 형태로 [생성](현성) 교육과정, [활동중심] 교육과정, [중핵] 교육과정, 생활영역 교육과정으로 세분화된다.',m:null},
{t:'경험중심 교육과정 중 [생성] 교육과정은 사전계획 없이 학습자의 요구를 중심으로 즉석에서 구성하는 교육과정이다.',m:null},
{t:'경험중심 교육과정 중 생성 교육과정은 [현실성]이 강하나 [체계적]이지 않아 유치원 및 초등학교 저학년에서만 가능하다.',m:null},
{t:'경험중심 교육과정 중 생성 교육과정은 내용의 깊이가 없는 [피상적] 문제를 다룰 가능성이 있고, 생성 교육과정만으로는 학생에게 필요한 교육 경험을 빠짐없이 부여하기 어렵다.',m:null},
{t:'경험중심 교육과정 중 [중핵] 교육과정은 중핵과정과 주변과정이 동심원적으로 조직된 교육과정이다.',m:null},
{t:'중핵 교육과정은 중핵과정에 따라 [교과] 중심, [학습자] 중심, [사회] 중심으로 나뉜다.',m:null},
{t:'경험중심 교육과정은 [자발적] 학습 참여를 통해 능동적인 [학습 태도]를 촉진시킬 수 있고, [문재해결능력]을 신장한다.',m:null},
{t:'경험 교육과정은 [협동학습] 속에서 대인관계 능력, 의사소통 능력, 민주적 태도, 사회성 등을 기를 수 있다.',m:null},
{t:'경험중심 교육과정은 [기초학력] 저하가 우려되고, 교과나 학년 간 [연계성] 및 [계열성]이 균형적으로 계획되지 못하여 학습 중복, 배제 등의 문제가 발생할 수 있다.',m:null},
{t:'[학문중심] 교육과정은 진보주의 교육철학에 대한 교육적 반성운동으로 등장한 교육과정으로 [지식의 구조]를 중시한다.',m:null},
{t:'학문중심 교육과정의 목표는 [지적 수월성] 획득이다.',m:null},
{t:'학문중심 교육과정의 교과는 학문의 [기저]를 이루는 근본적인 [아이디어]인 [지식의 구조]를 중심으로 구성되어 있다.',m:null},
{t:'학문중심 교육과정은 [지식의 구조]를 핵심으로 교과내용을 조직하였고, [나선형] 교육과정으로 교육과정을 구성하였다.',m:null},
{t:'나선형 교육과정은 지식의 구조를 [계열적]으로 조직하여, 동일한 교육내용이 학교와 학년에 따라 깊이는 깊어지고, 폭은 넓어지는 교과 조직 형태이다.',m:null},
{t:'학문중심 교육과정은 탐구과정을 중시하여 [전이]를 높이고, [발견학습]과 탐구학습을 활용한다.',m:null},
{t:'학문중심 교육과정은 지식의 경제성을 추구하고, 학생의 [탐구력]과 [고등정신능력]을 향상에 용이하다.',m:null},
{t:'학문중심 교육과정은 [전인교육]과 [정의적[ 영역 교육을 경시하고, 교수자인 교사가 지식의 구조를 충분히 이해하기 어려운 점에서 [난해]하다는 평가를 받는다.',m:null},
{t:'[인간중심] 교육과정은 인본주의적 가치에 기반한 교육과정으로 [잠재적] 교육과정에 대한 관심이 크다.',m:null},
{t:'인간중심 교육과정의 목표는 [자아실현]이다.',m:null},
{t:'인간중심 교육과정의 교과는 학교 안에서 이루어지는 의도적 활동과 비의도적 활동을 합한 것으로 [잠재적] 교육과정을 포함시켜 교과를 확장시켰다.',m:null},
{t:'인간중심 교육과정의 [전인교육]을 통해 긍정적 자아개념 형성에 기여할 수 있다.',m:null},
{t:'인간중심 교육과정은 인간 [이성]의 중요성과 사회 전체의 요구를 [경시]하고, 느슨한 교육은 결국 성취의 [저하]로 이어지게 한다.',m:null},
{t:'교육과정 통합은 교과 간 [중복] 내용을 줄여 필수적인 교육내용 선정에 도움이 되고, 교과 학습과 [생활]과의 연관성을 향상 시켜 교과 학습의 의미를 삶과 관련지어 인식하게 한다.',m:null},
{t:'교육과정 통합은 학생의 흥미와 관심을 반영하기 쉽고 [학습선택권]이 확대된다. 또한 [비판적 사고]를 길러주고, 스스로 교과를 [연계]하는 습관을 길러준다.',m:null},
{t:'교육과정 통합 시 준수해야 할 일반적 원칙은 [중요성]의 원칙, [일관성]의 원칙, [적합성]의 원칙이 있다.',m:null},
{t:'통합 교육과정의 일반적 원칙 중 [중요성]의 원칙은 각 교과들의 내용이 반영되어야 한다는 의미를 내포하고 있다.',m:null},
{t:'통합 교육과정의 일반적 원칙 중 [일관성]의 원칙은 내용과 활동이 목표달성을 위해 고안된 수업 전략과 부합되어야 한다를 내포하고 있다.',m:null},
{t:'통합 교육과정의 일반적 원칙 중 [적합성]의 원칙은 학습자의 개성과 수준에 맞으며, 학습자의 전인격적인 성장을 목표로 해야 한다를 내포하고 있다.',m:null},
{t:'드레이크는 통합 교육과정의 유형을 위계에 따라 전통적 통합, 융합 통합, 교과 내 통합, [다학문적] 통합, [간학문적] 통합, [초학문적] 통합으로 분류하였다.',m:null},
{t:'[다학문적] 통합은 몇 개의 학문이 동시에 주제를 다루어 나가는 접근 방식으로 교과의 구분과 벽을 그대로 유지한 채 통합한다.',m:null},
{t:'[간학문적] 통합은 두 개 이상의 교과가 새롭고 의미 있는 통합이 이루어지도록 하는 접근 방식으로 새롭고 의미 있는 통합이 이루어진다.',m:null},
{t:'간학문적 통합의 접근방식 중 동일한 [개념] 또는 [방법]을 둘 이상의 학문에 적용하는 방식으로 해당 방식은 엄격한 교과의 [경계]가 [붕괴]된다.',m:null},
{t:'간학문적 통합의 접근방식 중 한 학문의 개념이나 방법이 다른 학문의 [문제해결]에 적용하는 방식이 있다.',m:null},
{t:'간학문적 통합의 접근방식 중 한 학문을 [주축]으로 하고 주위 다른 학문들을 [배치]하여 상호 [연계]시키는 방식으로, 중핵 교육과정과 유사한 방식이 있다.',m:null},
{t:'[초학문적] 통합은 추출된 내용을 토대로 전혀 새로운 주제영역을 설정하여 운영하는 방식으로 [학생중심적] 관점에서 자유로운 표현활동과 문제해결활동을 강조한다.',m:null},
{t:'초학문적 통합에서 학생은 공동 [계획자]이며 [탐구자]이다.',m:null},
{t:'초학문적 통합은 구체적인 방법에 따라 [경험], [표현], [흥미]로 분류된다. 가나다순으로 작성하시오.',m:null},
{t:'[형식도야설]은 교과의 가치가 일반적 정신능력을 갈고 닦는 데에 있다는 것을 보여주는 이론이다.',m:null},
{t:'형식도야설의 [일반적 전이]는 하나의 특수 사례를 통해 개발된 능력이 다양한 일반 사례에 걸쳐 적용된다는 의미이다.',m:null},
{t:'형식도야설은 사회 요구에 적합한 교육과정을 제시하지 못하여 [실용적]이지 않고, [손다이크]의 실험으로 일반적 전이가 부정당했다.',m:null},
{t:'[지식의 형식]은 피터스와 허스트가 주장한 지식의 형태로, [내재적 가치]가 구현된 내용이다.',m:null},
{t:'[내재적 가치]란 어떤 다른 목적을 위한 수단이 아닌, 활동 그 자체에 들어 있는 가치이다.',m:null},
{t:'[선험적 정당화]는 개인이 받아들이는가 아닌가와 무관하게 성립하는 정당화이다.',m:null},
{t:'지식의 형식은 사회 변화, 교육 여견, 흥미 등 삶에 구체적으로 작용하고 있는 양상에 대해서는 관심을 기울이지 않아 [선험적 정당화]의 한계를 보여준다.',m:null},
{t:'[지식의 구조]는 각 학문의 기저를 이루고 있는 핵심적인 개념과 원리이다.',m:null},
{t:'지식의 구조를 가르친다는 것은 학생들로 하여금 수준은 다르더라도 [탐구]를 하도록 하는 것이고, 해당 학습으로 탐구학습과 [발견학습]이 있다.',m:null},
{t:'지식의 구조가 교육에 주는 이점은 [학습한 내용의 쉬운 이해], [장기기억의 가능](파지), [학습 이외의 사태에 적용]([일반적 전이]의 용이), 고등지식과 초보지식 사이의 [간극]을 좁힐 수 있다는 점이다.',m:null},
{t:'지식의 구조의 활용은 [나선형 교육과정]과 [발견학습]과 [탐구학습]이다. 가나다 순으로 작성하시오.',m:null},
{t:'2022 개정교육과정의 핵심역량은 [자기관리] 역량, [지식정보처리] 역량, [창의적 사고] 역량, [심미적 감성] 역량, [협력적 소통] 역량, [공동체] 역량이 있다.',m:null},
{t:'2022 개정교육과정의 [자기관리] 역량은 자신의 삶과 진로를 스스로 설계하는 자기주도성과 관련된 역량이다.',m:null},
{t:'2022 개정교육과정의 [지식정보처리] 역량은 합리적인 문제해결을 위한 탐구 및 활용과 관련된 역량이다.',m:null},
{t:'2022 개정교육과정의 [창의적 사고] 역량은 폭넓은 지식의 융합활용과 창출과 관련된 역량이다.',m:null},
{t:'2022 개정교육과정의 [심미적 감성] 역량은 인간에 대한 공감적 이해와 문화적 감수성과 관련된 역량이다.',m:null},
{t:'2022 개정교육과정의 [협력적 소통] 역량은 상호협력적인 관계에서 공동의 목적을 구현하는 의사소통과 관련된 역량이다.',m:null},
{t:'2022 개정교육과정의 [공동체] 역량은 구성원에게 요구되는 개방적&포용적 가치와 태도와 관련된 역량이다.',m:null},
{t:'[고교학점제]는 진로에 따라 다양한 과목을 선택-이수하고, 누적 학점이 기준에 도달한 경우 졸업을 인정받는 교육과정 이수-운영제도이다.',m:null},
]},
{id:'u4',name:'교육과정 재구성·역량·다문화',items:[
{t:'과학기술에 대한 학생의 흥미와 이해를 높이고 과학기술 기반의 융합적 사고력과 실생활 문제해결력을 배양하는 교육과정은 [STEAM] 교육과정이다.',m:null},
{t:'교육과정 [재구성]은 교사가 자신만의 교육과정으로 구성해가는 모든 과정이다.',m:null},
{t:'교육과정 재구성은 교사가 교육계획 및 교과서를 [재조직화], 수정, 보완, 통합하는 등의 활동이다.',m:null},
{t:'교육과정 재구성의 일반적 방식의 종류로 [교과 내] 재구성, [교과 간] 재구성, 교과와 [비교과]를 연계한 재구성이 있다.',m:null},
{t:'교육과정 재구성은 단순 지식 암기 교육에서 [지식 활용] 교육으로의 전환과 [교수]-[학습]방법의 변화와 교사의 [전문성]이 신장되는 방향으로 진행되어야 한다.',m:null},
{t:'[역량]은 지식을 습득한 상태보다 지식을 활용할 수 있는 능력으로 ‘학습의 결과’로서 수행능력을 강조한다.',m:null},
{t:'[역량기반] 교육과정은 인간행동의 다양화된 영역에서 역량을 획득하고 증진시킬 목적으로 만들어진 교육과정이다.',m:null},
{t:'역량기반 교육과정은 기존 교육과정 목표인 학습의 축적과 재생산을 넘어 학습의 [창출]과 [적용]을 목표로 하며, 범교과를 사용하여 [통합적]이다.',m:null},
{t:'교육과정 [대강화]는 교육과정에 전체적인 개요나 핵심 사항만을 간략히 담아 제시하는 것이다.',m:null},
{t:'교육과정 대강화는 교육과정 형식과 내용의 양적 [간소화]와 질적 [적정화]를 목표로 한다.',m:null},
{t:'지나치게 상세한 국가 교육과정은 하위 교육과정을 구속시켜 지역 또는 학교수준에서 이루어지는 교육과정에 대한 [의사결정]을 위축시킨다.',m:null},
{t:'교육과정 분권화는 수준에 따라 [분권화], [지역화], [자율화]로 나뉜다.',m:null},
{t:'다문화 교육의 유형은 [기여] 모형, [부가] 모형, [변환] 모형, [사회행동] 모형, 혼합 모형이 있다.',m:null},
{t:'[기여] 모형은 소수민족 집단과 관련된 내용을 부분적으로 다룰 것을 강조하는 모형으로, 교육과정에 포함되지 않는다.',m:null},
{t:'[부가] 모형은 소수민족 집단과 관련된 내용을 기존 교육과정의 구조적 변화 없이 추가로 부가하여 가르치는 모형이다.',m:null},
{t:'[변환] 모형은 소수민족 집단과 관련된 내용을 교육과정의 기본목표, 구조 본질에 조화할 수 있도록 변화시킬 것을 강조하는 모형이다.',m:null},
{t:'[사회행동] 모형은 소수민족 집단과 관련된 문제를 해결하기 위한 노력과 생동을 수행할 것을 강조하는 모형이다.',m:null},
{t:'교육과정 [리터리시]는 교사가 갖추어야 할 교사로서의 교육과정에 대한 소양이다.',m:null},
]},
]},
{id:'psychology',name:'교육심리',units:[
{id:'u5',name:'인지·도덕성 발달(피아제·콜버그)',items:[
{t:'피아제는 인지발달에 대해 [인지적] 구성주의의 입장을 가졌다.',m:null},
{t:'[도식]은 특정한 인지구조 또는 경험을 이해하는 조직화된 방식이다.',m:null},
{t:'[적응]은 환경과의 직접적인 상호작용을 통해 도식을 형성하는 과정으로 외부적 변화에 중점을 둔다. [동화]와 [조절]이 있다. 가나다순으로 작성하시오.',m:null},
{t:'[동화]는 도식의 양적 확장으로, 자신이 가지고 있는 기존 도식 속으로 외부의 대상을 받아들이는 인지과정이다.',m:null},
{t:'동화는 도식의 [양적] 확장으로, 자신이 가지고 있는 기존 도식 속으로 외부의 대상을 받아들이는 인지과정이다.',m:null},
{t:'[조절]은 도식의 질적 변화로, 새로운 대상에 맞도록 기존의 도식을 바꾸는 인지과정이다.',m:null},
{t:'조절은 도식의 [질적] 변화로, 새로운 대상에 맞도록 기존의 도식을 바꾸는 인지과정이다.',m:null},
{t:'동화와 조절의 결과 인지적 [불평형]이 사라지는 [평형화]가 발생한다.',m:null},
{t:'[조직화]는 환경과의 직접적인 접촉과 상관없이 나타나는 개체 내의 내부적 변화로, 새로운 도식의 형성이 다른 도식과의 조정을 통해 상호 연관된 인지체계의 일부가 되는 과정이다.',m:null},
{t:'[평형화]는 동화와 조절 간의 적절한 인지적 균형을 이룬 상태이다.',m:null},
{t:'[불평형]은 새로운 정보와 기존의 인지구조 간 균형이 깨진 상태이다.',m:null},
{t:'교사는 학생의 [인지적 불평형]을 유발하도록 새로운 경험을 제공해야 한다.',m:null},
{t:'피아제의 인지발달단계는 [감각운동기] - [전조작기] - [구체적 조작기] - [형식적 조작기] 순서이다.',m:null},
{t:'피아제의 인지발달단계에서 서로 다른 연령대의 아동들은 [질적]으로 다른 방식으로 사고한다.',m:null},
{t:'감각운동기의 [대상영속성]은 대상이 더 이상 보이지 않아도 그 대상이 계속해서 존재한다는 것을 이해하는 것이다.',m:null},
{t:'전조작기 시기의 아동들은 대상과 사건을 [표상]하는 능력과 [상징]적 기능의 사용능력이 발달한다.',m:null},
{t:'전조작기 아동은 [자기중심성]을 가져 자기 자신을 타인의 입장에 놓고 생각하거나 다른 사람의 관점에서 생각하지 못한다.',m:null},
{t:'전조작기 아동은 [가역적] 사고를 하기 어려워 [비가역적]이다.',m:null},
{t:'구체적 조작기의 학생은 어떤 상황에서 두드러진 한 가지 측면에만 초점을 맞추는 것이 아니라 두 개 이상의 측면을 동시에 고려하여 [탈중심화]하는 특징을 가진다.',m:null},
{t:'구체적 조작기의 학생은 [가역적] 사고를 통해 일련의 단계를 거꾸로 생각해서 출발점으로 되돌아갈 수 있다.',m:null},
{t:'구체적 조작기의 학생은 [보존개념]을 획득하는데, [보존개념]이란 물체의 특정한 물리적 속성을 의미한다.',m:null},
{t:'구체적 조작기의 학생은 한 가지 이상의 차원에 따라 사물을 [분류]할 수 있고, 점진적인 증가나 감소에 따라 어떤 요소를 일렬로 [서열화]할 수 있다.',m:null},
{t:'형식적 조작기의 학생은 [추상적]이고 [가설]-[연역적] 사고가 가능하며, [반성적 추상화]를 통해 내적 성찰을 진행한다.',m:null},
{t:'피아제는 구체적 조작기에 [탈중심화]를 주장하였으나, 엘킨드의 자기중심성 이론에 의하면 청소년들은 [개인적 우화]와 [상상의 청중]이라는 두 가지 왜곡된 신념을 갖게 된다. 가나다 순으로 작성하시오.',m:null},
{t:'[상상의 청중]은 항상 누군가가 자신을 지켜보고 있고, 관심을 갖고 있다고 믿게 되는 경향으로 강한 자의식을 가지게 된다.',m:null},
{t:'[개인적 우화]는 자신을 대단히 중요한 존재로 여기고, 자신의 감정이나 욕구가 독특하다고 생각하여 자신을 예외적인 존재로 지각하는 것이다.',m:null},
{t:'피아제의 인지적 구성주의는 교수-학습에서 학습자의 [능동적], 적극적 역할을 강조하고, 학생의 [인지수준]에 맞는 과제의 결정할 필요를 제시하였다.',m:null},
{t:'피아제의 인지적 구성주의는 취학 전 아동의 인지능력을 [과소평가]하고, 상대적으로 연령이 높은 아동의 능력을 [과대평가]하였다.',m:null},
{t:'비고츠키는 인지발달에 대해 [사회문화적] 구성주의의 입장을 가졌다.',m:null},
{t:'비고츠키는 [사회적 상호작용]이 학습과 인지발달을 가져오는 직접적 요인이라 하였고, 특히 [언어]습득이 아동발달에 매우 중요하다 주장하였다.',m:null},
{t:'비고츠키는 [사적] 언어와 발달된 형태인 [내적] 언어를 통해 아동의 사고와 적절한 행동을 선택할 수 있다 주장하였다.',m:null},
{t:'비고츠키는 언어가 사회적 상호작용을 통해 타인이 가지고 있는 지식에 [접근]할 수 있게 하며, [인식]의 도구를 제공하고, 우리의 사고를 [조절]하고 [반영]하는 수단이 된다 주장하였다.',m:null},
{t:'[근접발달영역]([ZPD])는 실제적 발달수준과 잠재적 발달수준 사이의 영역이다.',m:null},
{t:'[실제적] 발달수준은 독립적으로 문제를 해결할 수 있는 능력 수준이다.',m:null},
{t:'[잠재적] 발달수준은 조력으로 문제를 해결할 수 있는 능력 수준이다.',m:null},
{t:'[비계설정]은 아동이 궁극적으로 스스로 문제를 해결할 수 있도록 하는 이해를 확립하는 동안에 한시적으로 제공되는 조력이다.',m:null},
{t:'비계설정 방안의 종류는 [모델링], 소리내어 생각하기, [질문] 제공, [조언과 단서] 제공, 수업자료 조정하기 등이 있다.',m:null},
{t:'[역동적 평가]는 성인의 도움을 받아 어떤 새로운 것을 학습할 수 있는 능력을 평가하는 것으로, [잠재능력]의 평가로 [근접발달영역]([ZPD])를 파악할 수 있다.',m:null},
{t:'역동적 평가와 정적 평가의 가장 큰 차이점은 평가자와 피험자 간의 [상호작용]의 유무이다.',m:null},
{t:'[상보적 교수]는 비고츠키의 사회교육적 접근에 근거한 교수법이다. 토론전략으로 [예측], [질문], 요약, [명료화]가 있다.',m:null},
{t:'효과적인 수업을 위해 비고츠키는 [잠재적] 발달 수준에 알맞는 학습조건을 제공해야 하고, 학생과 교사 간의 [상호작용]이 필요하고, 학생들이 보다 [적극적]으로 참여하는 교수-학습을 제공해야 한다 주장하였다.',m:null},
{t:'비고츠키의 사회문화적 구성주의는 아동의 발달에서 교육환경, 특히 [인적] 환경의 중요성과 학생 간 [협동학습]의 중요성을 보여준다.',m:null},
{t:'비고츠키는 바람직한 교수활동은 아동들에게 현재의 발달수준보다 조금 앞서는 [잠재적] 발달수준을 가르침으로써 발달을 주도해야 하고, 이때 학생들에게 완전하고 정확한 이해의 틀을 받쳐주는 [비계]를 제공해야 한다 주장하였다.',m:null},
{t:'인지발달에 대한 입장에서 피아제는 아동이 스스로 [탐구자]가 되어야 하는 [인지적] 구성주의를, 비고츠키는 아동에게 도움을 줄 수 있는 성인이나 또래와의 [상호작용]이 중요하다는 [사회문화적] 구성주의를 주장하였다.',m:null},
{t:'언어와 사고의 관계에 대한 입장에서 피아제는 [인지]발달 후 [언어]발달이 이루어진다 생각하여 대체로 언어의 중요성을 과소평가하였으나, 비고츠키는 [언어]발달 후 [인지]발달이 이루어진다 생각하여 내면화된 언어는 아동이 자신의 행동과 문제해결을 조정하는 국면에서 중요한 역할을 한다고 보았다.',m:null},
{t:'자기중심적 언어에 대한 입장에서 피아제는 사고의 [미숙함]을 보여주는 징표하고 생각하였으나, 비고츠키는 아동의 사고와 적절한 행동을 선택하는 것을 돕는 역할을 한다고 보았고, [사적] 언어라는 용어로 사용하였다.',m:null},
{t:'[신피아제이론]은 정보처리이론을 이용한 피아제 이론의 설명으로, 연령이 증가함에 따라 [기억]공간의 [기능적] 용량이 증가한다고 보았다.',m:null},
{t:'브론펜브레너의 생물생태학적 발달이론 모형은 [미시]체계 - [중간]체계 - [외]쳬계 - [거시]체계 - [시간]체계 순서로 이루어져 있다.',m:null},
{t:'브론펜브레너는 사람과 상황이 상호작용하는 상황들 속에서의 [역동성]과 그 상황들 간의 [전이]에 관심을 가졌다.',m:null},
{t:'[미시체계]는 아동 가까이에 있는 사람과 활동으로, 발달에 가장 강력한 영향을 주는 환경이다.',m:null},
{t:'[중간체계]는 미시체계 요소 간의 상호작용으로 구성되어 있다.',m:null},
{t:'[외체계]는 미시체계와 중간체계 모두에게 여향을 주는 사회적 영향이다.',m:null},
{t:'[거시체계]는 아이가 속하여 자란 문화이다.',m:null},
{t:'[시간체계]는 생물생태학적 모형의 마지막 수준으로, 시간종속적이며 발달에 영향을 끼치는 변화의 모든 것이다.',m:null},
{t:'에릭슨은 성격발달이론을 통해 [심리사회적] 발달이론을 발전시켰다.',m:null},
{t:'에릭슨의 성격발달이론에서 발달은 [단계]별로 진행되고, 각 단계별로 특징적인 [과제]와 발달의 기회를 제공하는 심리사회적인 도전인 [위기]가 존재한다. 또한 발달에는 [자아]가 핵심적 역할을 한다.',m:null},
{t:'[신뢰감]은 부모가 유아의 기본적 욕구를 충족시켜줄 때 형성된다.',m:null},
{t:'[기본적 신뢰감] 대 불신감',m:null},
{t:'기본적 신뢰감 대 [불신감]',m:null},
{t:'[자율성]은 독립성을 가지면서 새로 형성된 사고능력과 심동기술을 이용해 세상을 탐구할 때 발달한다.',m:null},
{t:'[자율성] 대 수치 및 의심',m:null},
{t:'자율성 대 [수치 및 의심]',m:null},
{t:'[주도성]은 아동에게 탐구하고 실험할 수 있는 자유를 부여할 때 형성된다.',m:null},
{t:'[주도성]과 죄책감',m:null},
{t:'주도성과 [죄책감]',m:null},
{t:'[근면성]은 도전적 과제를 해결하기 위해 부지런히 활동하고 완성할 때 형성된다.',m:null},
{t:'[근면성] 대 열등감',m:null},
{t:'근면성 대 [열등감]',m:null},
{t:'[정체감]은 명확하게 규정된 한계 내에서 독립성을 증가시키려는 시도를 하도록 허용할 때 발달한다.',m:null},
{t:'[자아정체감] 대 역할 혼돈',m:null},
{t:'자아정체감 대 [역할 혼돈]',m:null},
{t:'[심리적 유예기]란 선택에 대한 결심을 연기하는 기간으로 사회적, 직업적 [역할]을 탐색하는 기회가 된다.',m:null},
{t:'교사는 사춘기의 불확실성을 [공감]하면서 허용 가능한 행동 범위의 한계를 확실히 [규정]지어 주어야 한다.',m:null},
{t:'마샤는 에릭슨의 정체감 형성이론에서 [위기]와 [수행]의 두 개의 차원의 중요한 구성요소로 보고, 이 두 차원의 좋합을 통해 [자아정체감]을 네 범주로 구분하였다.',m:null},
{t:'[위기]는 자신의 가치관에 대해 [재평가]하는 기간으로, [정체성]에 대한 고민이다.',m:null},
{t:'[수행]은 계획, 가치, 신념 등에 대해 [능동적] 의사결정을 내린 상태이다.',m:null},
{t:'위기를 인위적으로 유발하기 위해 [자유학기제]를 진행한다.',m:null},
{t:'정체감 [성취]는 직업과 이념적인 부분에서 위기의 시기를 겪고 몰입하는 상태로, 위기 [O] / 수행 [O] 으로 [건전한] 상태이다.',m:null},
{t:'정체감 [유예]는 현재 정체감 위기의 상태에 있으면서 자아정체감 형성을 위해 다양한 역할, 신념, 행동 등을 실행하고 있으나 의사결정을 못한 상태로, 위기 [O] / 수행 [X] 으로 [건전한] 상태이다.',m:null},
{t:'정체감 [유실]은 자신의 신념, 직업선택 등의 중요한 의사결정에 앞서 수많은 대안에 대해 생각해보지 않고, 부모나 다른 역할모델의 가치나 기대 등을 그대로 수용하여 그들과 비슷한 선택을 하는 상태로, 위기 [X] / 수행 [O] 으로 [불건전한] 상태이다.',m:null},
{t:'[부정적 자아정체감]은 정체감 [유실]의 한 종류로, 부모의 가치관이나 사회적 가치관과 정반대가 되는 자아개념을 의미한다.',m:null},
{t:'정체감 [혼미]는 자아에 대해 안정되고 통합적인 견해를 갖는데 실패한 상태로, 위기 [X] / 수행 [X] 으로 [불건전한] 상태이다.',m:null},
{t:'쉘만의 사회적 조망수용이론에서 사회적 조망수용능력은 [감정이입]과 [동정심], [문제해결능력]으로 이루어져있다.',m:null},
{t:'사회적 조망수용이론의 발달단계는 [자기중심적] 관점수용단계 - [주관적] 조망수용단계 - [자기반성적] 조망수용단계 - [상호적] 조망수용단계 - [사회적] 조망수용단계로 총 5단계로 이루어져 있다.',m:null},
{t:'[0]단계인 [자기중심적] 관점수용단계의 아동은 타인이 자신과 심리적으로 다르다는 것을 인식하지 못한다.',m:null},
{t:'[1]단계인 [주관적] 조망수용단계의 아동은 타인이 자신과 다른 생각을 가질 수 있다 생각하나, 단지 다른 정보를 가지고 있기 때문에 다르다고 생각한다.',m:null},
{t:'[2]단계인 [자기반성적] 조망수용단계의 아동은 자신과 타인을 벗어나 제3자의 입장으로 보지 못하는 주관적 판단을 하고, 종합적인 판단은 불가하다.',m:null},
{t:'[3]단계인 [상호적] 조망수용단계의 학생은 제3자의 입장에서 이해할 수 있는 객관적 판단이 가능하다.',m:null},
{t:'[4]단계인 [사회적] 조망수용단계의 학생은 사람들을 사회적 가치, 관습, 법, 가치관 등에 영향을 받아 사고한다는 것을 이해할 수 있다.',m:null},
{t:'도덕성의 정신분석학적 관점은 도덕성의 [내면화] 과정을 중시한다.',m:null},
{t:'도덕성의 행동주의적 관점은 도덕적 [행동]의 습득을 중시한다.',m:null},
{t:'도덕성의 사회인지이론적 관점은 도덕적 행동을 하는데 있어 [모방]의 효과를 강조한다.',m:null},
{t:'도덕성의 인지발달이론적 관점은 도덕적 [추론]을 중시한다.',m:null},
{t:'피아제는 도덕적 문제에 대한 아동의 반응을 [타율적] 도덕성과 [자율적] 도덕성으로 크게 두 단계로 구분하였다.',m:null},
{t:'타율적 도덕성은 어떤 행위의 의도보다 [결과]를 중시하며, [내적] 공정성에 대한 신념을 특징으로 한다.',m:null},
{t:'자율적 도덕성은 어떤 행위의 [의도]를 중시하며, [외적] 공정성에 대한 신념을 특징으로 한다.',m:null},
{t:'콜버그는 도덕적 딜레마를 통해 인습 기준하에 도덕적 수준을 [3]수준 [6]단계로 나누었다.',m:null},
{t:'[전인습] 수준은 자기중심적 도덕으로, 타인에 의한 규칙을 제대로 이해하지 못한다.',m:null},
{t:'[인습] 수준은 타인과의 도덕으로, 사회의 규칙과 관습에 대해 부응한다.',m:null},
{t:'[후인습] 수준은 원리의 도덕으로, 사회적 규칙의 밑바탕에 있는 원리에 초점을 두어 추상적인 자신만의 원리로 도덕적 문제를 관찰한다.',m:null},
{t:'도덕적 수준 1단계는 [처벌]-[복종] 단계로, 처벌받게 될 가능성에 근거하여 도덕적 판단을 내린다.',m:null},
{t:'도덕적 수준 [1]단계는 처벌-복종 단계로, 처벌받게 될 [가능성]에 근거하여 도덕적 판단을 내린다.',m:null},
{t:'도덕적 수준 2단계는 [시장교환]의 단계로 ‘나에게 어떤 의미인가?’ 같은 상호주의에 입각하여 도덕적 판단을 내린다.',m:null},
{t:'도덕적 수준 [2]단계는 시장교환의 단계로 ‘나에게 어떤 의미인가?’ 같은 [상호주의]에 입각하여 도덕적 판단을 내린다.',m:null},
{t:'도덕적 수준 3단계는 [타인]과의 [조화] 단계로 충성심, 다른 사람들의 기대, 사회적 인습 등 [타인]의 의견에 기초하여 도덕적 판단을 내린다.',m:null},
{t:'도덕적 수준 [3]단계는 타인과의 조화 단계로 충성심, 다른 사람의 기대, 사회적 연습 등 타인의 의견에 기초하여 도덕적 판단을 내린다.',m:null},
{t:'도덕적 수준 4단계는 [법]과 [질서] 단계로 [법]과 [질서]를 그 자체로서 존중하고 복종하여 도덕적 판단을 내린다.',m:null},
{t:'도덕적 수준 [4]단계는 법과 질서 단계로 법과 질서를 그 자체로서 존중하고 [복종]하여 도덕적 판단을 내린다.',m:null},
{t:'도덕적 수준 5단계는 [사회적 계약]의 단계로 사회적으로 합의된 [규칙]에 기초하여 도덕적 판단을 내린다. 사회에 이로움을 주지 않는 법과 질서는 바뀔 수 있다.',m:null},
{t:'도덕적 수준 [5]단계는 사회적 계약의 단계로 사회적으로 합의된 규칙에 기초하여 도덕적 판단을 내린다.',m:null},
{t:'도덕적 수준 6단계는 [보편적] 원리의 단계로 사회의 법을 초월한 추상적이고 [보편적]인 원리에 기초하여 도덕적 판단을 내린다.',m:null},
{t:'[+1단계 전략]은 학생들의 인지적 갈등을 자극하되, 한 단계 높은 단계에 있는 학생들과의 논쟁을 통한 전략이다.',m:null},
{t:'콜버그 이론은 [문화권]에 따른 차이가 존재하고 도덕적 [추론]과 도덕적 [행동]을 동일시하여 비판을 받는다. 또한 도덕성과 관련된 [성별] 차이를 간과하여 훗날 [길리건]의 도덕성 발달이론을 통해 정리된다.',m:null},
]},
{id:'u6',name:'길리건·동기이론(자기결정성·암묵이론)',items:[
{t:'[길리건]의 [여성] 도덕성 발달이론은 콜버그의 도덕발달이론에서 도덕성과 관련된 [성별] 차이를 간과한 것에 대한 비판에서 시작되었다.',m:null},
{t:'길리건은 남자가 정의, 규칙, 인권과 같은 [추상적] 개념에 기초에 판단을 내리는 경향이 있다고 주장했다.',m:null},
{t:'길리건은 여자가 개인적 관계, [인간] 관계, [인간]적 요구에 대한 관심 등에 기초해 판단을 내리는 경향이 있다고 주장했다.',m:null},
{t:'길리건은 여성에게 나타나는 [돌봄]의 윤리를 제안하고 이것이 상대적으로 열등한 것이 아니라 주장하였다.',m:null},
{t:'길리건 발달이론의 도덕발달단계는 [자기이익 지향] - [자기희생으로서의 선의] - [자신과 타인과의 역동] 순이다.',m:null},
{t:'길리건의 도덕발달이론에서 [자기이익 지향] 단계에서 학습자는 자기의 이익과 생존에 자기중심적으로 행동한다.',m:null},
{t:'길리건의 도덕발달이론에서 [자기희생으로서의 선의] 단계에서 학습자는 자신의 욕구를 억제하고 타인의 요구에 응하려 시도하고, [자기희생]과 타인에 대한 배려를 동등하게 선한 것으로 간주한다.',m:null},
{t:'길리건의 도덕발달이론에서 [자신과 타인과의 역동] 단계에서는 개인의 권리 주장과 타인에 대한 책임이 조화된다.',m:null},
{t:'길리건의 도덕발달단계의 사이에는 [비판적 과도기]가 존재한다.',m:null},
{t:'[가치명료화]는 자기 자신의 가치에 대해 자기인식을 보다 명료하게 하는 것이다.',m:null},
{t:'가치명료화에서 교사는 반대되는 주장들과 논의할 때, 모든 관점을 [수용]하고 자기 자신의 어떤 견해를 [강요]해서는 안된다. 이 점에서 가치명료화 접근은 [가치중립적]이다.',m:null},
{t:'가치명료화는 많은 [선택]에서 직면하고 있는 상황에서 자신이 선택하는 가치를 명확힣여 [혼란]을 줄이는 것을 중요시한다.',m:null},
{t:'가치명료화 7단계 과정은 여러 가지 [대안 탐색] - 대안으로부터 [가치선택] - 선택된 대안의 [가치검토] - 가치의 [존중] - 가치의 [재확인] - [가치실현] - [반복실천] 순이다.',m:null},
{t:'레스트의 도덕성 4구성요소 중 도덕적 [민감성]은 어떤 상황을 도덕적인 상황으로 지각하고 해석하는 것이다.',m:null},
{t:'레스트의 도덕성 4구성요소 중 도덕적 [판단력]은 어떤 행동이 도덕적으로 옳은 것인지 판단하는 것이다.',m:null},
{t:'피아제와 콜버그의 도덕발달단계는 도덕적 [판단]에 국한되어있다.',m:null},
{t:'레스트의 도덕성 4구성요소 중 도덕적 [동기화]는 도덕적 행위를 우선시하는 것이다.',m:null},
{t:'레스트의 도덕성 4구성요소 중 도덕적 [품성]은 도덕적 행동을 실천하기 위해 필요한 자아감도, 인내력, 용기, 자기통제력을 일컫는 말이다.',m:null},
{t:'레스트의 도덕성 4구성요소 모두가 [상호작용]해야 도덕적 [행동]이 나타날 수 있다.',m:null},
{t:'[플린효과]는 지능의 시대적 상승을 나타내는 현상이다.',m:null},
{t:'스피어만은 지능의 [일반요인]과 [특수요인]으로 구성되어 있으며, 이 중 [일반요인]이 지능의 본질을 구성하는 능력이라 정의했다.',m:null},
{t:'캐텔은 지능의 일반요인이 [유동적] 지능과 [결정적] 지능으로 구성되어 있으며, 이 중 [결정적] 지능은 경험에 따라 변할 수 있다고 정의했다.',m:null},
{t:'케넬의 [유동적] 지능은 유전적이고 생리적인 영향을 많이 받는 지능요인이다.',m:null},
{t:'케텔의 유동적 지능은 암기, 지각, 추리와 같은 정보의 [관계]를 파악하는 능력이나 [기억력]과 관련된 능력이다.',m:null},
{t:'케텔의 유동적 지능은 신체의 [성장곡선[과 유사한 발달 경향을 보여준다.',m:null},
{t:'케텔의 [결정적] 지능은 정보의 내용과 관련된 능력이다.',m:null},
{t:'케텔의 결정적 지능은 언어능력, 문제해결능력, 논리적 추리력과 같이 [경험]의 영향을 많이 받는 능력이다.',m:null},
{t:'케텔의 결정적 지능은 [학습]을 통해 증가하고, 노화에 따른 [감퇴율]이 적다.',m:null},
{t:'스턴버그는 지능의 본질을 이해하기 위해서는 인간의 [인지과정]을 이해해야한다고 주장하여 [인지과제]에 관련된 요소와 [정보처리과정]을 연결하여 지능을 이해하고자 하였다.',m:null},
{t:'스턴버그의 삼원지능은 [분석적] 능력, [창의적] 능력, [실제적] 능력으로 나뉜다.',m:null},
{t:'스턴버그의 삼원지능 중 [분석적] 능력은 정보나 사물을 분석, 평가, 비판, 비교 및 대조하는 데 필요한 능력으로 [요소]하위이론으로 설명된다.',m:null},
{t:'요소하위이론은 개인의 정신작용을 [메타요소], [수행요소], [지식]-[획득요소]로 설명한다.',m:null},
{t:'요소하위이론의 [메타요소]는 다른 요소에게 무엇을 할 것인지를 지시하는 역할을 하는 인지과정이다.',m:null},
{t:'요소하위이론의 [수행요소]는 메타요소가 지시한 것을 [수행]하는 정보처리과정이다.',m:null},
{t:'요소하위이론의 [지식]-[획득요소]는 새로운 정보를 학습할 때 사용하는 인지과정으로 부호화, 조합 및 통합, 연결의 작용으로 구성되어 있다.',m:null},
{t:'스턴버그의 삼원지능 중 [창의적] 능력은 무엇인가를 고안해내고 발견하며 상상하고 가정하는 것과 관련된 능력으로 [경험]하위이론으로 설명된다.',m:null},
{t:'경험하위이론은 [통찰성], [자동화 능력]으로 이루어져있다.',m:null},
{t:'경험하위이론의 [통찰력]은 새로운 경험을 효과적으로 다루는 능력으로 선택적 [부호화], 선택적 [결합], 선택적 [비교]가 있다.',m:null},
{t:'통찰력 중 선택적 [부호화]는 중요하고 적절한 정보에 주의를 기울이는 과정이다.',m:null},
{t:'통찰력 중 선택적 [결합]은 서로 관련 없는 요소를 연관시켜 새로운 것을 창출하는 활동이다.',m:null},
{t:'통찰력 중 선택적 [비교]는 이미 존재하는 것을 새로운 각도로 보아 이로부터 새로운 것을 유추하는 능력이다.',m:null},
{t:'경험하위이론의 [자동화 능력]은 친숙한 상황이나 문제에서의 자동적 처리이다.',m:null},
{t:'스턴버그의 삼원지능 중 [실제적] 능력은 적절한 아이디어를 찾아내고 실행하며 적용하고 활용하는 능력으로 [상황]하위이론으로 설명된다.',m:null},
{t:'상황하위이론은 [환경적응], [환경조성], [환경선택]으로 이루어져 있다.',m:null},
{t:'삼원지능이론은 현재의 [학교교육]이 이 세 가지 능력을 균형 있게 [계발]할 필요성을 제안하여 지식전달 및 획득 중심에서 지식의 창의적 활용 교육으로 전환되어야 한다고 말하고 있다.',m:null},
{t:'가드너는 인간의 지능은 단일한 특성이 아니라 [사회문화적] 맥락의 영향을 받는 서로 [독립적]이며 [다양한] 유형의 능력으로 구성되어 있다고 언급했다.',m:null},
{t:'다중지능이론의 8가지 지능 영역은 [언어] 지능, [논리수학] 지능, [음악] 지능, [공간] 지능, [신체운동적] 지능, [대인관계] 지능, [자기성찰] 지능, [자연친화] 지능으로 구성되어 있다.',m:null},
{t:'가드너의 다중지능이론에서 각각의 지능은 [상호독립적]이나 [상호작용적]으로 작동한다.',m:null},
{t:'가드너는 다양한 경험과 교육을 통해 지능이 [계발]될 수 있고, 지능의 [프로파일]이 다양하다고 말했다.',m:null},
{t:'가드너는 지식으로 간주되지 않았던 능력들을 지능의 영역으로 부각하여 학생 개인의 재능과 능력에 [관심]을 기울일 것을 촉구하였다.',m:null},
{t:'가드너는 학습자가 모두 [강점] 지능과 [약점] 지능을 가진 [평등한] 존재라는 시각을 확산시켰다.',m:null},
{t:'가드너의 다중지능이론은 개인의 강점과 약점을 확인하여 이를 보완하는 방향으로 다양한 지능을 고려한 다양한 [교육목표]과 [개별화] 수업 설정이 가능하다.',m:null},
{t:'비네는 [학습부진아]를 판별하기 위한 도구를 개발하고자 아동의 정신 능력을 측정하는 검사를 고안했다.',m:null},
{t:'[정신연령]은 비네-시몬 검사에서 제안된 것으로, 평균적인 N세 아동이 풀 수 있는 문항을 풀었다면 [정신연령]은 N세에 해당된다.',m:null},
{t:'[비율지능지수]([IQ])는 생활연령에 대한 정신연령의 비율이다.',m:null},
{t:'비율지능지수는 [연령]에 따라 지능지수의 의미가 다르다는 문제가 있다.',m:null},
{t:'웩슬러가 제안한 [편차지능지수]([DIQ])는 동일 연령집단 내에서의 상대적 위치를 규정한 지능지수이다.',m:null},
{t:'DIQ는 한 검사점수의 정규분표를 평균이 [100], [표준편차]가 [15]가 되는 표준점수로 환산하여 계산한 지능지수이다.',m:null},
{t:'편차지능지수는 자신의 연령집단 내에서 차지하는 [상대적 위치]를 알려준다는 점에서 [원점수]보다 더 많은 정보를 제공할 수 있다.',m:null},
{t:'지능검사의 종류로 [개인지능]검사, [집단지능]검사, [문화평형]검사가 있다.',m:null},
{t:'문화평형검사는 [문화적 편향]을 고려하여 문화적 요소가 개인의 지능에 미칠 수 있는 영향을 제거하거나 최소화한 검사이다.',m:null},
{t:'문화평형검사는 대개 [언어]가 미치는 영향을 최소화하기 위해 그림, 도형, 공간재료 등을 활용하여 제작된다.',m:null},
{t:'지능지수는 동일 연령상의 [상대적 위치]를 나타내는 것으로 절대적인 지능의 높고 낮음을 나타내는 지수가 아니다.',m:null},
{t:'지능지수의 동점자에서는 [하위검사지수]를 고려해야 한다.',m:null},
{t:'지능지수는 개인의 모든 지적 능력을 [타당]하게 [평가]하지 못하므로, 학생 이해의 참고자료 중 하나로 활용해야 한다.',m:null},
{t:'[정서지능]은 지능과 분리된 개념으로, [정서]와 감정을 [통제]하고 조절할 줄 아는 능력이다.',m:null},
{t:'가드너의 정서지능은 [개인내적] 지능과 [대인관계] 지능으로 이루어져있다.',m:null},
{t:'샐로비와 메이어의 정서지능은 정서의 [인식과 표현], 정서의 [사고 촉진], 정서 [지식의 활용], 정서의 [반영적 조절]로 이루어져 있다.',m:null},
{t:'정서의 [인식과 표현]에는 자신과 외부의 정서 파악과 정서의 정확한 표현 및 구별 등이 있다.',m:null},
{t:'정서의 [사고 촉진]에는 정서를 이용하여 판단하고 기억하기, 정서를 활용하여 문제해결 촉진하기 등이 있다.',m:null},
{t:'정서 [지식의 활용]에는 정서 간 관계 이해 및 명명, 복합적인 감정 이해하기, 정서들 간의 전환 이해하기 등이 있다.',m:null},
{t:'정서의 [반영적 조절]에는 정적&부적 정서 수용, 자신과 타인의 정서 조절 등이 있다.',m:null},
{t:'골맨의 정서지능은 자신과 타인의 감정을 인식하고 조절하는 [자기인식], [자기조절], [자기동기화], [감정이입], [사회적 기술]로 이루어져 있다.',m:null},
{t:'[창의력]은 일반적으로 무엇인가 특이하고 새로우며 독특한 것을 만들어 내는 능력이다.',m:null},
{t:'길포드의 창의력은 [확산적] 사고와 관련되어 있고, [유창성], [융통성], [독창성], [민감성]으로 이루어져 있다.',m:null},
{t:'길포드의 창의력 구조에서 [유창성]은 어떤 요구조건을 충족시키는 해결책을 많이 생산해 내는 능력이다.',m:null},
{t:'길포드의 창의력 구조에서 [융통성]은 상황변화 대처에 있어 질적으로 서로 다른 해결방안을 많이 생산해 내는 능력이다.',m:null},
{t:'길포드의 창의력 구조에서 [독창성]은 새롭고 독특한 대답을 산출해 내는 능력이다.',m:null},
{t:'길포드의 창의력 구조에서 [민감성]은 문제 인식 능력과 인식을 통한 문제 진술 능력이다.',m:null},
{t:'정원식과 이영덕은 창의력에 지적 능력과 [성격적] 특성을 포괄시켰다.',m:null},
{t:'왈라스의 창의적 사고 과정은 [준비]단계 - [배양]단계 - [영감]단계 - [검증]단계로 구성되어 있다.',m:null},
{t:'왈라스의 창의적 사고 과정 중 [준비]단계는 여러 가지 가능성을 탐색하고 다양한 방법으로 해결책을 모색하는 단계이다.',m:null},
{t:'왈라스의 창의적 사고 과정 중 [배양]단계는 논리적 사고뿐 아니라 지적, 의지적, 정서적 기능을 결합한 후 문제를 새롭게 바라보고 다양한 요소의 조합을 시도하는 단계이다.',m:null},
{t:'왈라스의 창의적 사고 과정 중 [영감]단계는 기발하고 결정적인 아이디어가 떠오르는 단계이다.',m:null},
{t:'왈라스의 창의적 사고 과정 중 [검증]단계는 문제의 해결책이 적절한지 검증하고 아이디어의 실현가능성과 적절성 여부를 판단하는 단계이다.',m:null},
{t:'칙센트미하이는 창의성의 체제모형을 제안하며 창의성은 [개인], [영역], [화롱현장]이라는 세 요소가 [상호작용]하는 하나의 시스템으로 이해해야 한다고 주장하였다.',m:null},
{t:'창의성 체제모형에서 [영역]은 개인이 활용하는 특정분야나 학문의 영역이다.',m:null},
{t:'창의성 체제모형의 영역 속에는 해당 영역이 요구하는 [실천 양식]이나 고유한 상징적 [체계]들과 [전문성] 수준이 존재한다.',m:null},
{t:'창의성 체제모형에서 [활동현장]은 산물을 평가, 선별, 유포하는 사람 및 사회이다.',m:null},
{t:'창의성 체제모형에서 활동현장의 구성원은 아이디어의 [적합]과 영역에서의 [인정] 여부를 판단한다.',m:null},
{t:'창의성 체제모형에서 [개인]은 영역에서 활동하며 활동현장에 성과물을 제시하며 평가를 받는 사람이다.',m:null},
{t:'창의성 체제모형에서 개인은 영역의 [행동 양식]이나 [절차]를 변화시키는 일을 함으로써 활동현장의 변화를 일으키고, 이러한 변화가 다시 영역 내로 포함될 때 [창의성]이 발생하게 된다.',m:null},
{t:'[브레인스토밍] 전략은 창의적인 아이디어를 산출하기 위해 여러 사람의 아이디어를 자유롭게 토의하는 기법이다.',m:null},
{t:'브레인스토밍의 기법에는 [비판금지]의 원리, [양산]의 원리, [자유분방]의 원리, [결합과 개선]의 원리가 있다.',m:null},
{t:'브레인스토밍의 기법 중 [비판금지]의 원리는 판단이나 평가를 유보하는 것을 지향하는 원리다.',m:null},
{t:'브레인스토밍의 기법 중 [양산]의 원리는 다양한 아이디어를 제시하고, 질보다 양을 중시하는 원리다.',m:null},
{t:'브레인스토밍의 기법 중 [자유분방]의 원리는 다듬어지지 않는 의견을 내고 자유롭게 이야기하는 것을 장려하는 원리다.',m:null},
{t:'브레인스토밍의 기법 중 [결합과 개선]의 원리는 다른  아이디어와 자유롭게 결합하고 수정하는 것을 장려하는 원리다.',m:null},
{t:'[강제연결법]은 특정 물건과 관련이 없다고 생각하는 물건을 강제로 연결하여 새로운 아이디어를 산출하는 방식이다.',m:null},
{t:'[PMI] 기법은 특정 문제의 긍정적인 부분과 부정적인 부분을 확인하고, 재미있지만 중립적인 부분을 확인하는 기법이다.',m:null},
{t:'PMI 기법은 특정 문제의 [긍정]적인 부분과 [부정]적인 부분을 확인하고, 재미있지만 [중립]적인 부분을 확인하는 기법이다.',m:null},
{t:'육색사고모자 기법은 서로 다른 [사고]와 [태도]를 표시하는 색깔의 모자를 쓰고, 해당 색깔의 역할을 수행하며 아이디어를 협력하여 만드는 기법이다.',m:null},
{t:'SCAMPER은 새로운 아이디어를 내는 행위를 [자극]하기 위한 체계적인 질문방법으로, [대체] - [결합] - [적용] - [수정] - [활용] - [제거] - [재배열]이 있다.',m:null},
{t:'[SCAMPER]은 새로운 아이디어를 내는 행위를 자극하기 위한 체계적인 질문방법으로, 대체 - 결합 - 적용 - 수정 - 활용 - 제거 - 재배열이 있다.',m:null},
{t:'[시넥틱스] 기법은 서로 관련성이 없는 요소들의 결합으로 유추와 비유를 통해 창의적 사고를 촉진할 수 있다.',m:null},
{t:'학습자의 창의성 함양을 위해 교사는 [질문] 및 [의문제기]를 격려하고, [자기효능감] 획득에 도움을 주어야하며, [실수]를 허용해도 좋다.',m:null},
{t:'[인지양식]은 인지행동에 있어서 나타나는 개인차, 개인이 일관성 있게 나타나는 반응양식이다.',m:null},
{t:'인지양식은 개인의 전형적인 [정보처리양식]이다.',m:null},
{t:'위트킨은 막대테두리검사와 잠입도형검사를 통해 인지양식을 [장독립적] 인지양식과 [장의존적] 인지양식으로 구분하였다.',m:null},
{t:'장독립적 학습자는 방해요인에 대해 [독립적]이고, 심리적 분화가 잘 되어 [분석적]이며 [구조화]가 용이하다.',m:null},
{t:'장의존적 학습자는 방해요인에 대해 [의존적]이고, 심리적 분화가 잘 이루어지지 않아 [전체적]이며 [구조화]를 어려워한다.',m:null},
{t:'장독립자 학습자는 단순 내용전달에도 수업목표와 전반적인 내용을 잘 알기에 [구체적] 사항을 강조하는 수업이나 발견법이 학습에 도움이 된다.',m:null},
{t:'장의존적 학습자는 수업목표와 전반적 내용을 면밀힐 설명하고 개념을 학습자의 [경험]과 관련짓는 수업이 학습에 도움이 된다.',m:null},
{t:'케이건은 유사도형결합검사를 통해 인지양식을 [충동적] 인지양식과 [반성적] 인지양식으로 구분하였다. 오류가 많은 순으로 적으시오.',m:null},
{t:'충동형 학습자는 문제에 대한 반응시간이 [빠르]지만 오류가 [많은] 경우로, [자기교수법]을 활용하여 개선할 수 있다.',m:null},
{t:'반성형 학습자는 문제에 대한 반응시간이 [느리]지만 오류가 [적은] 경우로, [건너뛰기] 전략을 활용하여 개선할 수 있다.',m:null},
{t:'콜브는 [정보지각]방식과 [정보처리]방식의 유형에 따라 학습양식을 구분하였다.',m:null},
{t:'콜브의 학습양식에서 정보지각방식은 [구체적 경헙]과 [추상적 개념]으로 나뉜다.',m:null},
{t:'콜브의 학습양식에서 정보처리방식은 [반성적 관찰]과 [활동적 실험]으로 나뉜다.',m:null},
{t:'콜브의 학습양식에서 [분산자]는 구체적 경험과 반성적 관찰을 가진 학습자로 다양한 아이디어 산출에 강하다.',m:null},
{t:'콜브의 학습양식에서 [융합자]는 추상적 개념과 반성적 관찰을 가진 학습자로 이론화에 강하다.',m:null},
{t:'콜브의 학습양식에서 [수렴자]는 추상적 개념과 활동적 실험을 가진 학습자로 이론의 활용을 통한 문제 해결에 강하다.',m:null},
{t:'콜브의 학습양식에서 [적응자]는 구체적 경험과 활동적 실험을 가진 학습자로 계획의 실천에 적극적인 모습을 보인다.',m:null},
{t:'인지양식과 교수법의 연관성에 대한 입장은 일치시켜야 한다는 [개별학습환경] 조성의 입장과 일치시키는 것이 타당하지 않다는 [극복력] 신장의 입장으로 나뉜다.',m:null},
{t:'[동기]는 목표지향적인 활동이 유발되고 지속되는 과정이다.',m:null},
{t:'[외재적] 동기는 최종 목표를 얻기 위한 수단으로서의 어떤 활동에 참여하는 동기이다.',m:null},
{t:'[내재적] 동기는 활동 그 자체를 위해 참여하는 동기이다.',m:null},
{t:'내재적 동기 유발의 일반적인 방법으로 [도전제시], [자율성] 부여, [호기심], [창의성] 및 상상력 자극이 있다.',m:null},
{t:'[과정당화 가설]이란 내재적 흥미를 과제에 대해 보상을 주면, 그 자체가 보상을 위한 수단으로 인식되면서 내재적 동기가 감소하는 현상이다.',m:null},
{t:'과정당화 가설은 특히 [통제적] 성격의 [외적] 보상이 주어질 때 쉽게 발생한다.',m:null},
{t:'보상이 수행에 대해 [정보적] 역할을 할 때, 보상은 교육적으로 긍정적 역할을 수행한다.',m:null},
{t:'매슬로우는 심리학에서 인본주의 사조의 아버지로, 전인전 인간의 [욕구]를 반영하는 위계를 발전시켰다.',m:null},
{t:'매슬로우의 욕구위계이론은 크게 [결핍] 욕구와 [성장] 욕구로 나뉜다.',m:null},
{t:'[결핍] 욕구는 충족되지 않았을 때 충족하고자 노력하는 욕구이다.',m:null},
{t:'결핍 욕구에는 낮은 단계부터 생리적 욕구. [안전]의 욕구, 소속감과 애정의 욕구, [자아존중감]의 욕구가 있다.',m:null},
{t:'[성장] 욕구는 잠재력에 최대한 도달하고 자아실현하고자 하는 욕구이다.',m:null},
{t:'성장 욕구는 결코 완전히 충족되지 않아 끝없이 [추구]한다.',m:null},
{t:'성장 욕구에는 지적 욕구, 심미적 욕구, [자아실현] 욕구가 있다.',m:null},
{t:'매슬로우의 욕구위계이론을 통해 교사는 학생의 욕구 수준을 파악하여 그에 맞는 [지도방안]을 모색해야한다.',m:null},
{t:'결핍 욕구과 충족된 이후에야 학업에 대한 [동기]가 발생하므로 학생들의 소속감이나 자존감의 욕구를 충족시키는 [안전]한 학교가 구현되어야 한다.',m:null},
{t:'로저스는 실현 경향성 이론을 통해 [자아실현] 욕구는 선천적인 것이고, 타고난 [잠재력]을 완전계발하기 위한 지속적인 노력의 욕구라 정의했다.',m:null},
{t:'로저스의 실현 경향성 이론에서 성장을 위한 노력에는 [투쟁]과 [고통]이 수반되며, 이러한 고통을 이겨 나가는 것이 [실현 경향]이라 명시했다.',m:null},
{t:'실현 경향은 [타율성]에서 벗어나 [자율성]을 추구하여 새롭고 도전적인 경험을 하도록 하는 동기의 [원천]이다.',m:null},
{t:'실현 경향성을 늘리기 위해서는 의미있는 [타인]의 무조건적이고 긍정적인 [관심]이 필요하다.',m:null},
{t:'자기가치이론은 사람들은 [자기가치감]을 보호하고 [자기수용]을 이루려는 선천적 욕구를 가지고 있다고 말한다.',m:null},
{t:'[자기장애]전략은 자신의 가치를 보존하기 위한 행동 패턴이다.',m:null},
{t:'자기장애전략의 종류로 [미루기], [변명]하기, [걱정]하기, [노력]하지 않았다는 것을 [강조]하기 등이 있다.',m:null},
{t:'학습자가 자기장애전략을 보일때, 교사는 노력을 기울이면 능력을 증진시킬 수 있다는 [믿음]을 강조하고, [본보기]로 보여주어야 한다.',m:null},
{t:'데시와 라이언은 자신의 환경에 따라 협동하고 환경을 통제하고 하는 욕구인 [자기결정] 이론을 주장했다.',m:null},
{t:'자기결정이론에서 동기는 [자기결정적] 경향과 [비자기결정적] 경향 간의 상호작용의 산물이라고 정했다.',m:null},
{t:'자기결정이론의 동기는 자기결정성에 따라 크게 [무동기], [외재적] 동기, [내재적] 동기로 나뉜다.',m:null},
{t:'자기결정이론에서 외재적 동기는 [외적] 조절, [투사된] 조절, [동일시된] 조절, [통합된] 조절로 나뉜다.',m:null},
{t:'외적 조절의 학습자에게 외재적 보상이나 [처벌]이 많아 학습자는 [순응]하거나 [저항]한다.',m:null},
{t:'투사된 조절의 학습자는 자아나 타인으로부터 [인정]을 추구하고, 이때부터 [자아]가 관여하기 시작한다.',m:null},
{t:'동일시된 조절의 학습자는 [가치]를 부여하고, 자율적인 [목표]를 설정한다.',m:null},
{t:'통합된 조절의 학습자는 여러 목표를 [위계적]으로 통합하거나 목표의 [조화]를 추구한다.',m:null},
{t:'[내적] 조절의 학습자는 과제 자체에 만족하며, 흥미와 즐거움을 추구한다.',m:null},
{t:'자기결정이론에서 인간은 [관계성], [유능성], [자율성] 욕구를 가진다고 가정하였다. 가나다 순으로 작성하시오.',m:null},
{t:'학생들의 지식과 기술이 증가하고 있다는 증거를 보여줄 때, 학생들은 자신의 [유능성]을 지각하게 된다.',m:null},
{t:'학생들에게 선택의 기회를 제공할 때, 학생들은 자신의 [자율성]을 지각하게 된다.',m:null},
{t:'학생들에게 무조건적인 긍정적 존중과 헌신을 통해 학생들의 [관계성] 욕구 충족에 도움을 줄 수 있다.',m:null},
{t:'드웩의 암묵이론은 지능은 본질적으로 고정되어 있고 시간이 지나도 별로 변하지 않는다는 [정체이론]과 지능은 안정적이지 않고, 노력으로 증가될 수 있다는 [증가이론]으로 나뉘어, 서로 대립하고 있다.',m:null},
]},
{id:'u7',name:'기대가치이론·메타인지·자기조절학습',items:[
{t:'자신의 능력에 대한 [기대]와 과제의 [가치]는 동기를 형성하는 중요한 요인으로, 이때 [기대]와 [가치]의 곱이 학습동기의 [정도]를 결정한다.',m:null},
{t:'기대X가치이론에서 기대는 과제의 성공적인 수행을 위해 필요한 자신의 능력에 대한 [신념]이나 [판단]이다.',m:null},
{t:'기대X가치이론에서 기대는 크게 [과제난이도] 인식과 [자기도식]과 연관되어 있다.',m:null},
{t:'과제난이도 인식에서 과제가 쉽다고 느낄 때 [성공]에 대한 [기대]를 높게 가질 수 있다.',m:null},
{t:'[자기도식]은 자신에 대한 정보의 조직이고, 자아개념을 포함한다.',m:null},
{t:'높은 [자기도식]은 높은 [성공]을 기대하게 한다.',m:null},
{t:'기대X가치이론에서 가치는 과제를 수행하는 [이유]이다.',m:null},
{t:'기대X가치이론에서 가치는 크게 [내재적 흥미], [중요성], [효용가치], [비용]과 연관되어 있다.',m:null},
{t:'내재적 흥미는 사람들이 기꺼이 [참여]하도록 [유도]하는 활동의 특성과 주제의 성격을 뜻한다.',m:null},
{t:'효용가치는 미래의 [직업]이나 [목표]에 [도움]을 줄 수 있다고 느끼는 정도와 관련이 있다.',m:null},
{t:'[효용가치]는 미래의 직업이나 목표에 도움을 줄 수 있다고 느끼는 정도와 관련이 있다.',m:null},
{t:'비용은 과제에 참여함으로써 올 수 있다고 인식되는 [부정적] 측면으로 [소요시간]이나 감정적 [비용](부담, 스트레스) 등과 관련이 있다.',m:null},
{t:'기대X가치이론에서 학습동기의 정도는 기대와 가치의 [곱]으로 결정되기 때문에, 한쪽 측면이 아무리 커도 다른 한쪽 측면이 작으면 학습동기는 [낮]아지게 된다.',m:null},
{t:'기대X가치이론에서 동기 향상을 위해 교사는 학생들이 자신의 능력에 대해 정확하면서도 높은 [기대]를 형성하도록 조력해야하고, 수업에서 해당 교과나 수업주제가 어떤 점에서 [중요]하고 [가치] 있는지를 설명해주어야한다.',m:null},
{t:'[자기효능감]은 과제를 잘 해낼 수 있을 것이라는 자신의 능력에 대한 믿음이다.',m:null},
{t:'자기효능감은 과제를 잘 해낼 수 있을 것이라는 자신의 [능력]에 대한 [믿음]이다.',m:null},
{t:'자기효능감 형성에 영향을 미치는 요인으로 자신의 [성취경험], [본보기] 보이기, [사회적]&[언어적] 설득, [심리적 상태]가 있다.',m:null},
{t:'자신의 성취와 관련된 [성공경험]은 자신의 능력에 대한 긍정적 기대를 형성하도록 돕는다.',m:null},
{t:'[모델]의 성공을 관찰하면서 자신도 할 수 있다는 생각이 들게 된다면 [자기효능감]은 향상된다.',m:null},
{t:'타인의 칭찬이나 격려와 같은 [사회적]&[언어적] 설득은 자신의 [능력]을 판단하는 근거가 될 수 있음.',m:null},
{t:'과제를 수행하면서 느끼는 [심리적 상태]에 대한 해석이 자기효능감에 영향을 미칠 수 있다.',m:null},
{t:'교사의 자기효능감([교수효능감])은 교사가 가지는 학생들의 학습을 도와주는 자신의 능력에 대한 개인적인 [신념]으로, 학생들의 [학업]에 영향을 미친다.',m:null},
{t:'교사를 둘러싼 환경변인에서 [동로교사와의 소통]이 많을수록, [의사결정참여 빈도]가 높을수록 교사효능감은 증진된다.',m:null},
{t:'귀인은 수행의 [원인]에 대한 [믿음]으로, 행동의 원인을 무엇으로 생각하는지는 [후속행동]에 영향을 미친다는 점에서 개인의 [동기]와 밀접한 관련이 있다.',m:null},
{t:'귀인은 [소재], [안정성], [통제]라는 세 가지 차원에서 발생한다.',m:null},
{t:'귀인의 차원 중 [소재]는 원인의 위치로, 이 위치는 학습자의 [내부] 혹은 [외부]를 의미한다.',m:null},
{t:'귀인의 차원 중 [안정성]은 원인의 [가변성]으로, 변하면 [불안정], 변하지 않으면 [안정]하다.',m:null},
{t:'귀인의 차원 중 [통제]는 학생이 그들의 성공과 실패에 대한 [책임]을 수용하는 정도이다.',m:null},
{t:'귀인의 3가지 차원 간 관계를 통해 만들어진 귀인요소 4가지는 [능력], [노력], [운], [과제난이도]이다.',m:null},
{t:'능력은 원인이 학습자 [내부]에 위치해 있고, [안정]하며, 학습자가 통제할 수 [없다].',m:null},
{t:'노력은 원인이 학습자 [내부]에 위치해 있고, [불안정]하며, 학습자가 통제할 수 [있다].',m:null},
{t:'운은 원인이 학습자 [외부]에 위치해 있고, [불안정]하며, 학습자가 통제할 수 [없다].',m:null},
{t:'과제난이도는 원인이 학습자 [외부]에 위치해 있고, [안정]하며, 학습자가 통제할 수 [없다],',m:null},
{t:'학습자의 동기는 실패를 [노력] 부족으로 돌렸을 때 증가하는데, 그 이유는 [노력]은 [통제 가능한] 변인이기 때문이다.',m:null},
{t:'학습자의 동기는 실패를 [통제]가 [불가능한] 원인으로 돌렸을 때 감소한다.',m:null},
{t:'실패를 [능력] 부족으로 돌릴 경우 [학습된 무력감]으로 연결될 수 있다.',m:null},
{t:'학습된 무력감은 아무리 [노력]해도 [성공]할 수 없다는 [감정]으로 불가항력적인 [부끄러움]과 자신의 능력을 믿지 않는 [자기의심]이 발전하여 포기하게 된다.',m:null},
{t:'학습된 무력감을 개선하기 위해서는 교사의 귀인 피드백으로 [노력]의 귀인으로 유도해야 한다.',m:null},
{t:'귀인훈련 프로그램은 [노력] 부족에 귀인 유도 - [학습전략] 귀인 사용 - 해당 과제 [포기] 유도 순으로 진행된다.',m:null},
{t:'[목표지향성]은 학습활동과 같은 성취상황에서 활동에 임하는 근본적인 원인과 목적으로, 학습자의 학습행동과 학습방법을 설명하는 틀이다.',m:null},
{t:'목표지향성은 학습활동과 같은 성취상황에서 활동에 임하는 근본적인 원인과 목적으로, 학습자의 [학습행동]과 [학습방법]을 설명하는 틀이다.',m:null},
{t:'목표지향성의 목표유형은 [숙달목표], [수행목표], [사회적 목표], [과제회피목표]로 나뉜다.',m:null},
{t:'[숙달목표]는 학습에 대한 이해를 도모하고 계발하는 것을 추구하는 목표이다.',m:null},
{t:'[수행목표]는 다른 사람들과의 경쟁과 비교한 역량에 초점을 둔 목표이다. 타인보다 자신의 능력이 [우월]하다는 것을 드러내는 경향성이 있다.',m:null},
{t:'수행목표는 다른 사람들과의 [경쟁]과 비교한 [역량]에 초점을 둔 목표이다. 타인보다 자신의 능력이 [우월]하다는 것을 드러내는 경향성이 있다.',m:null},
{t:'수행목표는 [수행접근목표]와 [수행회피목표]로 나뉜다.',m:null},
{t:'[수행접근목표]는 유능하게 보이는 것과 타인으로부터 호의적인 평가를 받는 것을 강조하는 목표이다.',m:null},
{t:'[수행회피목표]는 무능력하게 보이는 것을 피하고 호의적이지 않은 평가를 피하는 것에 초점을 둔 목표이다.',m:null},
{t:'[사회적 목표]는 특정한 사회적 결과나 사회적 상호작용을 달성하려는 목표로, [숙달목표]와 결합되면 학습동기와 성취는 더 향상될 수 있다.',m:null},
{t:'[과제회피목표]는 과제가 쉽거나 노력을 거의 기울이지 않고 마칠 수 있을 때 성공적이라고 느끼는 상황으로, 최소한의 노력과 최소한의 기여를 보여준다.',m:null},
{t:'과제의 [가치]를 전달하거나 적절한 수준의 [도전적인] 과제를 제시하여 숙달목표를 증진할 수 있다. 이때, 보상이나 평가가 타인과의 [경쟁]과 [비교]를 지나치게 조장하지 않도록 해야한다.',m:null},
{t:'[성취동기]는 도전적이고 어려운 과제를 성공적으로 수행하려는 욕구이다.',m:null},
{t:'앳킨스는 성취동기를 [성공추구동기]와 [실패회피동기]로 분류하였다.',m:null},
{t:'성공추구동기가 높은 학생은 실패회피동기가 높은 학생들보다 [중간] 난이도 과목에 접근하려는 경향이 두드러진다.',m:null},
{t:'[성공추구동기]가 높은 학생은 지나치게 비현실적인 어려운 과제에 도전하지 않는다.',m:null},
{t:'실패회피동기가 높은 학생은 [실패]를 감수하면서도 어려운 과목을 선택하는 경향이 두드러지는데, 자신의 [실패]를 과목의 난이도에 [귀인]시키려고 하기 때문이다.',m:null},
{t:'성공추구동기가 높은 학생이 과제를 성공시키면 동기가 [감소]한다.',m:null},
{t:'성공추구동기가 높은 학생이 과제를 실패하면 동기가 [증가]한다.',m:null},
{t:'실패회피동기가 높은 학생이 과제를 성공시키면 동기가 [증가]한다.',m:null},
{t:'실패회피동기가 높은 학생이 과제를 실패하면 동기가 [감소]한다.',m:null},
{t:'[몰입]은 전적으로 어떤 일에 빠져들어 느끼는 총체적 감흥이다.',m:null},
{t:'몰입은 활동의 [도전] 정도와 개인의 [역량] 사이가 유사하여 [균형] 상태일 때 발생한다. [창의적]이거나 자유로운 [표현]이 허락된 경우 발생하기 쉽다.',m:null},
{t:'행동주의에서 학습은 [경험의 결과]로 발생한 것으로 관찰 가능한 비교적 지속적인 [행동의 변화]이다.',m:null},
{t:'고전적 조건화는 어떤 사람이 [불수의적 정서반응] 또는 [생리적 반응]을 일으키도록 하는 학습의 한 유형이다.',m:null},
{t:'고전적 조건화에서 [무조건자극]이 [중립자극]과 연합하여 [조건자극]이 될 때, [무조건자극]이 없어도 [조건반응]이 일어나게 된다.',m:null},
{t:'고전적 조건화의 주요 개념으로 [일반화], [변별], [소거], 자발적 회복, 재조건형성이 있다.',m:null},
{t:'고전적 조건화에서 일반화는 [비슷한] 자극이 동일한 [조건반응]을 이끌어 내는 것이다.',m:null},
{t:'고전적 조건화에서 변별은 [일반화]와 상반되며, 관련 있지만 동일하지 않은 자극에 [다른] 반응을 보이는 것이다.',m:null},
{t:'고전적 조건화에서 소거는 [무조건자극]을 제거하고 [조건자극]만 반복적으로 제시하여 더 이상 [조건반응]을 이끌어 내지 못하게 되는 것이다.',m:null},
{t:'고전적 조건화에서 자발적 회복은 조건반응이 [소거]된 후 [조건자극]이 다시 제시되면 [조건반응]이 재생되는 현상을 말한다.',m:null},
{t:'고전적 조건화에서 재조건형성은 자발적 회복 이후 조건자극과 무조건자극을 계속 짝지어 제시하면 [조건반응]이 원래의 강도로 되돌아오는 현상을 말한다.',m:null},
{t:'고전적 조건화를 이용하여 부적응행동을 교정하는 방법으로 [소거], [역조건화], [단계적 둔감화], 홍수법이 있다.',m:null},
{t:'부적응행동 교정법 중 [소거]는 무조건자극을 제거하고 조건자극을 반복적으로 제시하여 조건자극에 대한 반응을 억제하는 과정이다.',m:null},
{t:'부적응행동 교정법 중 역조건화는 [부정적] 반응을 초래하는 [조건자극]에 [긍정적] 반응을 일으킬 수 있는 새로운 [무조건자극]을 제시하여 긍정적 [조건반응]에 부정적 [조건자극]을 결합시키는 방법이다.',m:null},
{t:'부적응행동 교정법 중 단계적 둔감화는 조건화된 부정적 반응에 이완법 등의 활동을 [대립]시켜 놓은 후 부정적 [조건자극]을 [점진적]으로 감도를 [높여] 제시함으로써 부정적 반응을 억제하는 방법이다.',m:null},
{t:'부정응행동 교정법 중 홍수법은 [조건자극]을 충분히 제공하여 [조건반응]이 약화되기를 기대하는 방법이다.',m:null},
{t:'고전적 조건화의 한계점으로 학습자는 어떠한 환경에서 [단순한 자극]에 반응하는 것만은 아님을 제시했다.',m:null},
{t:'고전적 조건화가 [행동]을 유발시키기 위해 [자극]에 관심을 두는 반면, 조작적 조건화는 [자극]보다는 유발된 [행동]의 결과에 관심을 가진다.',m:null},
{t:'조작적 조건화에서 [강화]는 행동의 빈도를 증가시키는 과정이다.',m:null},
{t:'조작적 조건화에서 [정적 강화]는 자극을 제시하여 의도한 행동을 유발하고 유지시키는 것이다.',m:null},
{t:'조작적 조건화에서 [부적 강화]는 자극을 제거하여 의도한 행동을 유발하고 유지시키는 것이다.',m:null},
{t:'조작적 조건화에서 [벌]은 행동의 빈도를 약화시키거나 감소시키는 과정이다.',m:null},
{t:'조작적 조건화에서 [수여성 벌]은 자극을 제시하여 의도한 행동을 감소시키는 것이다.',m:null},
{t:'조작적 조건화에서 [제거성 벌]은 자극을 제거하여 의도한 행동을 감소시키는 것이다.',m:null},
{t:'조작적 조건화에서 [소거]는 강화가 제공되지 않을 경우 행동의 빈도가 감소하거나 사라지는 과정이다.',m:null},
{t:'조작적 조건화에서 [소거폭발]은 강화의 제거 이후에 나타나는 일시적인 행동의 증가로, 이러한 경우 계속해서 [무시]하는 것이 올바른 방법이다.',m:null},
{t:'[타임아웃]은 학생을 교실 밖으로 내보내는 것으로 또래학생에게 격리시키는 것으로 조작적 조건화의 [제거성 벌]에 해당된다.',m:null},
{t:'강화계획은 강화인의 [빈도]와 강화인이 주어지는 [시점]에 대한 패턴이다.',m:null},
{t:'간헐적 강화계획은 개인의 [행동] 수에 의존하는 [비율]계획과 [시간]에 의존하는 [간격]계획으로 나뉜다.',m:null},
{t:'조작적 조건화를 사용한 바람직한 행동의 증가 방법의 유형으로 [프리맥의 원리], [토큰 강화](경제), [행동조성], [응용행동분석]이 있다.',m:null},
{t:'프리맥의 원리는 덜 선호하는 행동을 [증가]시키기 위해 선호하는 행동을 [강화인]으로 이용하는 기법이다.',m:null},
{t:'토큰 강화는 적절한 행동을 [교환가치]가 있는 토큰으로 [강화]하여 행동을 변화시키는 기법이다.',m:null},
{t:'행동조성은 [단계적]으로 [목표행동]에 도달하기 위해 강화를 사용하는 방법으로 주로 저연령대 학습자에게 적합하다.',m:null},
{t:'응용행동분석은 학생의 [행동변화]를 목적으로 행동주의 원리를 [단계적]으로 적용하는 방법으로 고연령대 학습자에게 적합하다.',m:null},
{t:'응용행동분석은 [목표행동 확인] - [기저선 활동] - [강화인] 및 [처벌인] 선택 - [행동 변화 측정] - 강화인 [빈도] 감소 순으로 진행된다.',m:null},
{t:'조작적 조건화를 사용한 바람직하지 않은 행동의 감소 방안의 유형으로 [타임아웃], [상반행동강화](칭찬-무시 접근), [소거], [포화], 반응대가, 사회적 격리가 있다.',m:null},
{t:'[타임아웃]은 보상을 받을 수 있는 기회를 박탈하는 기법이다.',m:null},
{t:'타임아웃은 보상을 받을 수 있는 [기회]를 박탈하는 기법이다.',m:null},
{t:'상반행동강화는 바람직하지 않은 행동은 [관심]을 두지 않고 바람직하지 않은 행동의 [대안]이 될 수 있는 긍정적 행동에 [칭찬]을 하여 부적절한 행동을 감소시키는 기법이다.',m:null},
{t:'조작적 조건화에서 소거는 문제행동에 대해 [관심]을 보이지 않는 기법으로 일시적으로 [소거폭발]이 발생할 수 있다.',m:null},
{t:'포화(심적 포화)는 정적 강화자극의 계속적 [지급]으로 정적 강화자극으로서의 [기능]을 잃게하는 기법이다.',m:null},
{t:'사회인지학습이론은 강화인과 벌인이 [기대]를 형성한다고 주장한다.',m:null},
{t:'사회인지학습이론에서 기대는 행동에 영향을 주는 [인지과정]이다.',m:null},
{t:'[모델링]은 모델을 관찰한 결과로 발생하는 행동, 인지, 정서 변화로 [사회인지학습이론]의 핵심이다.',m:null},
{t:'모델링은 [직접] 모델링, [상징적] 모델링, [종합적] 모델링, [인지적] 모델링으로 분류된다.',m:null},
{t:'[직접] 모델링은 모델의 행동을 단순하게 모방하려는 시도이다.',m:null},
{t:'[상징적] 모델링은 책, 연극, 영화 또는 TV에등장하는 주인공은 행동을 모방하는 시도이다.',m:null},
{t:'[종합적] 모델링은 관찰한 행동의 부분을 종합함으로써 행동의 발전시키는 시도이다.',m:null},
{t:'[인지적] 모델링은 행동 뒤의 숨어 있는 행동을 말로 표현하는 것과 시범으로 보여 주는 것을 통합한 과정이다.',m:null},
{t:'모델링/관찰학습의 과정은 [주의집중] - [파지] - [재생산] - [동기화] 순이다.',m:null},
{t:'모델링 과정 중 주의집중 모델의 행동에 [주의]를 기울이는 단계이다.',m:null},
{t:'모델링 과정 중 파지는 관찰한 행동을 학습자의 [기억] 속에 상징적 [표상] 형태로 [저장]하는 단계이다.',m:null},
{t:'모델링 과정 중 재생산은 [파지]한 내용을 머릿속으로 [연습]해보거나 실제 [행동]으로 옮겨보는 단계이다.',m:null},
{t:'모델링 과정 중 동기화는 학습된 행동을 실제로 행동으로 드러내 보이기 위한 [내적 과정]이다.',m:null},
{t:'모델의 능력, 매력, 지위나 힘, [또래모델] 등 모델의 특성은 관찰자의 [주의집중]에 영향을 미친다.',m:null},
{t:'모델학습은 [일관적]일수록 학습의 효과가 크다.',m:null},
{t:'관찰자는 자신의 상황에서 [기능적 가치]가 있는 행동을 잘 모델링한다.',m:null},
{t:'자기조절은 학습자의 [기대]가 행동과 환경에 [영향]을 줄 수 있도록 만드는 것이다.',m:null},
{t:'[자기조절]은 학습자의 기대가 행동과 환경에 영향을 줄 수 있도록 만드는 것이다.',m:null},
{t:'자기조절은 [목표설정], [진행점검], [자기평가], [전략사용]으로 구성되어있다.',m:null},
{t:'[인지주의]는 행동주의에 대한 반발로 등장하였고, 인간의 [내적 인지기능]에 초점을 맞추어 인간행동을 설명하였다.',m:null},
{t:'톨만의 기호형태설을 통해 동물의 [인지] 존재 여부를 확인하였다. 강화물이 제공되지 않아도 [학습]이 이루어지고 있고, 강화물은 단지 습득된 [학습]이 [행동]으로 [표출]되도록 만드는 역할이다.',m:null},
{t:'[형태주의] 심리학자들은 문제해결의 핵심을 문제의 조직 혹은 구성에 관한 것으로 이해하였다.',m:null},
{t:'인지주의의 [정보처리이론]은 새로운 정보가 [투입]되고 [기억]되며 다시 [인출]되는 과정으로 학습자의 내부에서 [학습]이 발생하는 기제를 설명하려는 이론이다.',m:null},
{t:'정보처리이론의 구조는 [정보저장소]와 [인지처리과정]의 두 가지 요소로 구성되어있다.',m:null},
{t:'[정보저장소]는 투입된 정보가 머무르는 곳이다.',m:null},
{t:'인지처리과정이란 각각의 [정보저장소]로부터 정보가 [이동]하는 것과 관계되는 처리과정을 의미한다.',m:null},
{t:'정보저장소는 [감각기억], [작업기억], [장기기억]으로 나뉜다.',m:null},
{t:'감각기억은 학습자가 환경으로부터 [감각 수용기관]을 통해 정보를 [최초로] 저장하는 곳이다.',m:null},
{t:'작업기억은 감각기억을 거쳐 투입된 5~9개의 정보를 [해석]하고 결과를 [판단]하는 작업이 이루어지는 곳이다.',m:null},
{t:'작업기억은 중앙집행기를 중심으로 [음운 고리], [시공간 스케치판]으로 구성되어있다.',m:null},
{t:'음운 고리에서는 [단어]와 [소리]를 단기간 저장한다.',m:null},
{t:'시공간 스케치판에서는 [시각적] 또는 [공간적] 정보를 단기간 저장한다.',m:null},
{t:'작업기억 용량한계 극복방안으로 [청킹], [자동화], [분산된 처리]가 있다.',m:null},
{t:'[청킹]은 정보의 항목을 보다 크고 의미있는 단위로 묶는 정신과정이다.',m:null},
{t:'청킹은 정보의 항목을 보다 크고 의미있는 단위로 [묶는] 정신과정이다.',m:null},
{t:'[자동화]는 자각이나 의식적으로 노력없이 수행할 수 있는 정신적 조작을 수행할 수 있는 능력이다.',m:null},
{t:'[분산된 처리]는 감각정보를 분산하여 처리하는 활동으로 이때 [음운 고리]와 [시공간 스케치판]이 사용된다.',m:null},
{t:'[장기기억]은 무한한 정보를 영구적으로 저장할 수 있는 곳이다.',m:null},
{t:'인지처리과정의 유형으로 [주의], [지각], [시연], [부호화], [인출], [망각]이 있다.',m:null},
{t:'주의는 [자극]에 의식적으로 [초점]을 두는 과정이다.',m:null},
{t:'[주의]는 자극에 의식적으로 초점을 두는 과정이다.',m:null},
{t:'주의를 끌기 위한 전략으로 [시범], 시각 자료, [강조], 학생이름 호명 등이 있다.',m:null},
{t:'지각은 자극에 [의미]를 부여하고 [반응]하는 과정이다.',m:null},
{t:'[지각]은 자극에 의미를 부여하고 반응하는 과정이다.',m:null},
{t:'시연은 정보를 [유지]하기 위해 마음속으로 또는 소리 내어 정보를 [반복]하는 과정이다.',m:null},
{t:'[시연]은 정보를 유지하기 위해 마음속으로 또는 소리 내어 정보를 반복하는 과정이다.',m:null},
{t:'시연에는 단순반복인 [기계적] 시연과 새로운 정보의 의미에 초점을 두고 처리하는 [정교형] 시연이 있다.',m:null},
{t:'부호화는 [장기기억]에 정보를 [표상]하는 과정이다. 제시된 정보를 처리 가능한 형태로 [변형]한다.',m:null},
{t:'[부호화]는 장기기억에 정보를 표상하는 과정이다. 제시된 정보를 처리 가능한 형태로 변형한다.',m:null},
{t:'부호화의 전략으로 [정교화], [조직화], [심상화], 기억술, 맥락화가 있다.',m:null},
{t:'부호화에서 정교화는 기존에 가지고 있던 정보를 새로운 정보를 [연결]하여 정보를 [유의미]한 형태로 저장하는 과정이다.',m:null},
{t:'부호화에서 [정교화]는 기존에 가지고 있던 정보를 새로운 정보를 연결하여 정보를 유의미한 형태로 저장하는 과정이다.',m:null},
{t:'정교화 과정에서 [예시]와 [유추]를 활용하여 익숙한 형태로 변환 후 저장한다.',m:null},
{t:'부호화에서 조직화는 관련있는 내용을 공통 범주나 유형으로 [묶는] 과정이다.',m:null},
{t:'부호화에서 [조직화]는 관련있는 내용을 공통 범주나 유형으로 묶는 과정이다.',m:null},
{t:'조직화 과정에서 [도표], [개요] 등을 통해 조직화하여 효과적으로 저장하고 기억한다.',m:null},
{t:'부호화에서 심상화는 정보에 대한 [시각적 이미지]를 표상하는 과정이다.',m:null},
{t:'부호화에서 [심상화]는 정보에 대한 시각적 이미지를 표상하는 과정이다.',m:null},
{t:'심상화 과정에서 [시각 자료]를 활용하여 저장한다.',m:null},
{t:'부호화에서 [기억술]은 내용 속에 자연적인 상태에서 없었던 연합을 억지로 만들어 내는 기억전략이다.',m:null},
{t:'부호화에서 맥락화는 정보가 학습상황의 물리적&정서적 맥락과 함께 처리되는 것으로, [인출단서]가 되어 [부호화 특수성]의 원인이 된다.',m:null},
{t:'인출은 [장기기억] 속에 있는 정보를 꺼내고자 탐색하는 과정이다.',m:null},
{t:'[인출]은 장기기억 속에 있는 정보를 꺼내고자 탐색하는 과정이다.',m:null},
{t:'[인출단서]는 특정 정보에 접근하는 것을 도와주는 자극이다.',m:null},
{t:'인출 상황을 [부호화] 상황을 유사하게 만들 때 인출이 잘된다. 이것을 [부호화 특수성]이라고 한다.',m:null},
{t:'[망각]은 장기기억으로부터 정보를 소실하거나 [인출]할 수 없는 과정이다.',m:null},
{t:'[메타인지]는 자신의 인지과정에 대한 자각과 통제이다.',m:null},
{t:'메타인지는 자신의 인지과정에 대한 [자각]과 [통제]이다.',m:null},
{t:'메타인지의 주요 기술은 [계획], [점검], [조절], [평가]가 있다.',m:null},
]},
{id:'u8',name:'인지부하·문제해결전략',items:[
{t:'[인지부하]는 특정 과제의 수행이 인지 체제에 부과하는 부하량이다.',m:null},
{t:'[내재적] 인지부하는 과제 자체의 복잡성에 기인하는 인지부하이다.',m:null},
{t:'내재적 인지부하는 과제 자체의 [복잡성]에 기인하는 인지부하이다.',m:null},
{t:'[외재적] 인지부하는 과제를 제시하는 방식에 의해 발생하는 인지부하이다.',m:null},
{t:'외재적 인지부하는 과제를 [제시]하는 방식에 의해 발생하는 인지부하이다.',m:null},
{t:'[본질적] 인지부하는 학습을 촉진하는 인지부하이다.',m:null},
{t:'본질적 인지부하는 [학습]을 촉진하는 인지부하이다.',m:null},
{t:'[도식이론]은 지식의 덩어리들이 어떻게 표상되고 그 표상이 지식의 활용을 어떻게 촉진하는가에 대한 이론이다.',m:null},
{t:'도식이론은 지식의 덩어리들이 어떻게 [표상]되고 그 [표상]이 지식의 [활용]을 어떻게 촉진하는가에 대한 이론이다.',m:null},
{t:'[구성주의] 학습이론은 지식을 전달받기보다는 학습자가 스스로 지식을 만든다고 주장하는 학습이론이다.',m:null},
{t:'구성주의 학습이론은 지식을 전달받기보다는 학습자가 스스로 지식을 [만든다]고 주장하는 학습이론이다.',m:null},
{t:'인지적 구성주의는 [개인차]와 내적 [이해]의 구성에 초점을 맞춘 피아제의 연구에 기반하였다. [환경]과 상호작용하고 [도식]을 변경시킴으로써 의미를 찾는다.',m:null},
{t:'사회적 구성주의는 학습자들이 먼저 [사회적 맥락] 안에서 지식을 [구성]하고 그 다음에 개개인이 이것을 [내면화]한다고 본다.',m:null},
{t:'[전이]는 이전의 학습이 새로운 학습 또는 문제해결에 영향을 미치는 것이다.',m:null},
{t:'전이는 이전의 [학습]이 새로운 [학습] 또는 문제해결에 영향을 미치는 것이다.',m:null},
{t:'[정적] 전이는 이전 상황의 학습이 다른 상황에서의 학습을 촉진시킬 때 발생한다.',m:null},
{t:'정적 전이는 이전 상황의 학습이 다른 상황에서의 학습을 [촉진]시킬 때 발생한다.',m:null},
{t:'[부적] 전이는 이전 상황의 학습이 다른 상황에서의 학습이나 수행을 방해할 때 발생한다.',m:null},
{t:'부적 전이는 이전 상황의 학습이 다른 상황에서의 학습이나 수행을 [방해]할 때 발생한다.',m:null},
{t:'[구체적] 전이는 한 상황에서 배운 지식이나 기술 등을 유사한 상황에 적용하는 것이다.',m:null},
{t:'구체적 전이는 한 상황에서 배운 지식이나 기술 등을 [유사]한 상황에 적용하는 것이다.',m:null},
{t:'[일반적] 전이는 한 상황에서 배운 지식이나 기술 등을 유사하지 않은 새로운 상황에 적용하는 것이다.',m:null},
{t:'[수평적] 전이는 학생이 이미 알고 있는 내용과 다르긴 하지만 서로 비슷한 수준의 과제를 수행할 때 나타나는 것이다.',m:null},
{t:'수평적 전이는 학생이 이미 알고 있는 내용과 다르긴 하지만 서로 [비슷한] 수준의 과제를 수행할 때 나타나는 것이다.',m:null},
{t:'[수직적] 전이는 보다 상위 수준의 과제를 학습하기 위해 과거의 학습한 하위 개념을 적용하는 것이다.',m:null},
{t:'수직적 전이는 보다 [상위] 수준의 과제를 학습하기 위해 과거의 학습한 [하위] 개념을 적용하는 것이다.',m:null},
{t:'학습 전이에 영향을 미치는 요인으로 학습상황들 사이의 [유사성], 이전 학습의 [깊이], 학습경험의 [질], 학습자 경험을 위한 [상황]이 있다.',m:null},
{t:'[형식도야설]은 정신능력이 훈련으로 도야되며, 이것이 광범위한 영역으로 확대된다고 주장하는 이론으로, 일반적 전이와 연관되어 있다.',m:null},
{t:'형식도야설은 정신능력이 훈련으로 도야되며, 이것이 광범위한 영역으로 확대된다고 주장하는 이론으로, [일반적] 전이와 연관되어 있다.',m:null},
{t:'형식도야설은 [교과중심] 교육과정과 [항존]주의와 연관되어 있다.',m:null},
{t:'[동일요소설]은 여러 학습과제 사이에 동일한 요소가 존재하는 경우에만 전이가 일어난다고 보는 입장으로 특수적 전이관점을 토대로 한다.',m:null},
{t:'동일요소설은 여러 학습과제 사이에 [동일한 요소]가 존재하는 경우에만 전이가 일어난다고 보는 입장으로 [특수적] 전이관점을 토대로 한다.',m:null},
{t:'동일요소설은 [경험중심] 교유과정과 [진보]주의와 연관되어 있다.',m:null},
{t:'[동일원리설]은 선행학습에서 획득된 원리를 후속학습에 활용할 수 있을 때 전이가 일어난다고 주장하는 이론이다.',m:null},
{t:'동일원리설은 [선행학습]에서 획득된 [원리]를 [후속학습]에 활용할 수 있을 때 전이가 일어난다고 주장하는 이론이다.',m:null},
{t:'동일원리설은 [학문중심] 교육과정과 연관되어 있다.',m:null},
{t:'[형태이조설]은 통찰을 전이의 결정적인 요소로 보아 선행학습 장면의 역학적 관계에 대한 통찰이 발생해야 다른 장면으로 전이가 가능하다는 주장이다.',m:null},
{t:'형태이조설은 [통찰]을 전이의 결정적인 요소로 보아 선행학습 장면의 역학적 관계에 대한 [통찰]이 발생해야 다른 장면으로 전이가 가능하다는 주장이다.',m:null},
{t:'형태이조설은 [학문중심] 교육과정과 브루너의 [지식의 구조], [발견학습]과 연관되어 있다.',m:null},
{t:'동일원리설은 전이에 대한 [기계적] 이론으로 과정을 거치면 [자동적]으로 전이가 발생하지만, 형태이조설은 관계를 [통찰]하고 그 [통찰]을 활용하려는 [욕구]가 있어야만 전이가 발생한다.',m:null},
{t:'문제해결단계의 절차는 [문제확인] - [문제표상] - [전략선택] - [전략실행] - [결과평가]이다.',m:null},
{t:'문제해결전략에는 구조화된 문제 해결에 유용한 [알고리즘]과 비구조화된 문제 해결에 유용한 [어림법]이 있다.',m:null},
{t:'문제해결전략에는 [구조화]된 문제 해결에 유용한 알고리즘과 [비구조화]된 문제 해결에 유용한 어림법이 있다.',m:null},
]},
]},
{id:'edutech',name:'교육공학',units:[
{id:'u9',name:'교수설계 변인·협동학습모형(TGT 등)',items:[
{t:'교수설계:수업설계의 3대 변인으로 교수의 [조건], 교수의 [방법], 교수의 [성과]가 있다.',m:null},
{t:'교수의 조건 변인은 교사에 의해 [통제]될 수 없는 [제약] 조건으로, 교과의 [특성], 교과의 [목적], [제약 조건], [학습자 특성]이 있다.',m:null},
{t:'교수의 [조건] 변인은 교사에 의해 통제될 수 없는 제약 조건으로, 교과의 [특성], 교과의 [목적], [제약 조건], [학습자 특성]이 있다.',m:null},
{t:'교수의 조건 변인 중 교과의 특성은 각 교과의 서로 다른 [지식]과 [지식의 구조]이다.',m:null},
{t:'교수의 조건 변인 중 교과의 [특성]은 각 교과의 서로 다른 지식과 지식의 구조이다.',m:null},
{t:'교수의 조건 변인 중 교과의 목적은 교과를 통해 학생을 [성취]하고자 하는 [교수목적]이다.',m:null},
{t:'교수의 조건 변인 중 교과의 [목적]은 교과를 통해 학생을 성취하고자 하는 교수목적이다.',m:null},
{t:'교수의 조건 변인 중 [제약 조건]은 교사 본인이 속해 있는 교육상황의 여러 요인이다.',m:null},
{t:'교수의 조건 변인 중 제약 조건은 교사 본인이 속해 있는 [교육상황]의 여러 요인이다.',m:null},
{t:'교수의 조건 변인 중 [학습자 특성]은 학습자의 현재 상태이다.',m:null},
{t:'교수의 조건 변인 중 학습자 특성은 학습자의 [현재 상태]이다.',m:null},
{t:'교수의 [방법] 변인은 각기 다른 조건에서 다른 결과를 성취하기 위한 방안의 종류이다. 교사마다 [상대적]이며, 교사의 [직접적] 개입이 가능하다.',m:null},
{t:'교수의 방법 변인은 각기 다른 조건에서 다른 결과를 [성취]하기 위한 방안의 종류이다. 교사마다 [상대적]이며, 교사의 [직접적] 개입이 가능하다.',m:null},
{t:'교수의 방법 변인으로 [조직 전략], [전달 전략], [관리 전략]이 있다.',m:null},
{t:'교수의 방법 변인 중 [조직] 전략은 교과의 내용을 구조와 학습자의 수준에 적합하게 조직하는 방법이다.',m:null},
{t:'교수의 방법 변인 중 [전달] 전략은 조직한 내용을 효과적이고 효율적으로 학생에게 전수하는 방법이다.',m:null},
{t:'교수의 방법 변인 중 [관리] 전략은 교수-학습의 전체 과정을 통제하고, 어떤 조직 전략과 전달 전략의 요소를 사용할 것인지를 결정한다.',m:null},
{t:'교수의 [성과] 변인은 교수 방법의 효과 정도를 보여주는 교수활동의 최종 산물로, [효과성], [효율성], [매력성], [안정성]이 있다.',m:null},
{t:'교수의 성과 변인은 교수 방법의 [효과] 정도를 보여주는 교수활동의 [최종 산물]로, [효과성], [효율성], [매력성], [안정성]이 있다.',m:null},
{t:'교수의 성과 변인 중 효과성은 의도한 교육목표가 [달성]되었는지의 정도이다.',m:null},
{t:'교수의 성과 변인 중 [효과성]은 의도한 교육목표가 달성되었는지의 정도이다.',m:null},
{t:'교수의 성과 변인 중 효율성은 목표달성에 투입된 [노력]이나 [비용] 등이다.',m:null},
{t:'교수의 성과 변인 중 [효율성]은 목표달성에 투입된 노력이나 비용 등이다.',m:null},
{t:'교수의 성과 변인 중 매력성은 학습자의 [흥미]를 유발하거나 유지시켜주는 동기이다.',m:null},
{t:'교수의 성과 변인 중 [매력성]은 학습자의 흥미를 유발하거나 유지시켜주는 동기이다.',m:null},
{t:'교수의 성과 변인은 물리적인 안정과 정서적 안정을 저해하는 요인이 되어서는 안되는데, 이는 [안정성]이 높은 교수법이다.',m:null},
{t:'일반적 교수설계의 절차는 [요구분석] - [학습자 분석] - [교수목표 설정] - [학습과제 분석]이다.',m:null},
{t:'교수설계에서 [요구]는 실제 수행과 기대되는 수행 간의 차이이다.',m:null},
{t:'교수설계에서 [요구분석]은 불확실한 문제의 본질을 규명하면서 그 문제를 해결하는 가장 적절한 방안을 제안하려고 하는 활동이다.',m:null},
{t:'교수설계에서 요구분석은 불확실한 문제의 [본질]을 규명하면서 그 문제를 [해결]하는 가장 적절한 [방안]을 제안하려고 하는 활동이다.',m:null},
{t:'교수설계의 요구분석 기법에는 [자원 명세서], [사용 분석], [설문 조사], 구조화된 집단 등이 있다.',m:null},
{t:'요구분석 기법의 [자원 명세서] 기법은 대상 학습자 집단의 특성과 그들에게 현재 어떤 유형의 교육이 가능한지를 파악하는 것이다.',m:null},
{t:'요구분석 기법의 자원 명세서 기법은 대상 학습자 집단의 [특성]과 그들에게 현재 어떤 유형의 교육이 [가능]한지를 파악하는 것이다.',m:null},
{t:'요구분석 기법의 [사용 분석] 기법은 기존 프로그램이 얼마나 사용되고 있는지에 관한 정보를 수집하는 것이다.',m:null},
{t:'요구분석 기법의 사용 분석 기법은 기존 프로그램이 얼마나 [사용]되고 있는지에 관한 정보를 수집하는 것이다.',m:null},
{t:'요구분석 기법의 [설문 조사] 기법은 관심 집단의 작은 표본을 대상으로 다양한 정보를 수집하기 위해서 실시하는 것이다.',m:null},
{t:'요구분석 기법의 구조화된 집단에는 초점 집단, 명목 집단, [델파이 패널]이 있다.',m:null},
{t:'델파이 패널은 참가자의 [익명성]을 보장한다.',m:null},
{t:'요구분석 후 [교육적]으로 개선이 여려운 원인을 [교육적]으로 해결하려고 할 때 실패가능성은 증가한다.',m:null},
{t:'학습자 분석 기법에서 [사전학습능력]은 특정 단위의 학습활동을 하는 데 있어서 이미 학습된 성취수준이다.',m:null},
{t:'학습자 분석 기법에서 [선수학습능력]은 어떤 학습을 시작하는 단계에서 학생들이 갖추고 있어야 할 지식이다.',m:null},
{t:'교수설계에서 [학습과제 분석]은 가르쳐야 할 모든 종류의 지식이나 기능을 분석함으로써 교수내용에 관한 정보를 제공하기 위해 하는 활동이다.',m:null},
{t:'교수설계에서 학습과제 분석은 가르쳐야 할 모든 종류의 지식이나 기능을 분석함으로써 [교수내용]에 관한 정보를 제공하기 위해 하는 활동이다.',m:null},
{t:'학습과제 분석 기법은 크게 [학습목표] 분석과 [하위기능] 분석으로 나뉜다.',m:null},
{t:'인지적 영역의 학습목표로 [언어정보], [지적기능], [인지 전략]이 있다.',m:null},
{t:'정의적 영역의 학습목표로 [태도]가 있다.',m:null},
{t:'심동적 영역의 학습목표로 [운동기능]이 있다.',m:null},
{t:'과제 분석의 주요 기법은 [군집분석], [위계분석], [통합분석], [절차분석]이 있다.',m:null},
{t:'[군집분석]은 언어정보의 학습과제를 분석할 때 주로 사용하고, 주요 정보를 효과적으로 묶어 분석한다.',m:null},
{t:'군집분석은 [언어정보]의 학습과제를 분석할 때 주로 사용하고, 주요 정보를 효과적으로 [묶어] 분석한다.',m:null},
{t:'[위계분석]은 지적기능의 학습과제를 분석할 때 주로 사용하고, 과제 달성에 필요한 여러 기능들을 상위 기능과 하위 기능으로 분석한다.',m:null},
{t:'위계분석은 [지적기능]의 학습과제를 분석할 때 주로 사용하고, 과제 달성에 필요한 여러 기능들을 [상위] 기능과 [하위] 기능으로 분석한다.',m:null},
{t:'지적기능은 하위 기능부터 [변별] - [개념] - [원리] - [문제해결학습]으로 분류한다.',m:null},
{t:'[통합분석]은 태도의 학습과제를 분석할 때 주로 사용하고, 위계분석과 군집분석, 절차분석을 동시에 사용한다.',m:null},
{t:'통합분석은 [태도]의 학습과제를 분석할 때 주로 사용하고, [위계분석]과 [군집분석], [절차분석]을 동시에 사용한다.',m:null},
{t:'[절차분석]은 운동기능의 학습과제를 분석할 때 주로 사용하고, 과제를 수행하기 위한 순서를 분석한다.',m:null},
{t:'절차분석은 [운동기능]의 학습과제를 분석할 때 주로 사용하고, 과제를 수행하기 위한 [순서]를 분석한다.',m:null},
{t:'[강의법]은 중요한 정보를 효율적인 교사의 강의를 매개로 전달하는 교수방법으로, 가장 전통적인 교수법이다.',m:null},
{t:'강의법은 다량의 정보를 [체계적]으로 전달이 가능하고, 교수자가 수업을 [통제]하기 용이하다.',m:null},
{t:'강의법은 교수자의 [능력]과 준비에 따라 수업의 질이 크게 달라지고, 학습자의 [고등정신기능] 함양이 어렵고 [수동적 태도]가 발생한다.',m:null},
{t:'[객관]적이며 논리적으로 분명한 지식 전수 및 설명이 필요한 경우에 강의법은 적합한 교수법이 될 수 있다.',m:null},
{t:'[고차원]적 과제를 다루거나 학생의 [참여]가 필수적인 경우 강의법 수업은 적절하지 않다.',m:null},
{t:'[문답법]은 교수자와 학습자간 상호적인 질의응답을 통해 학습자의 탐구능력과 추상적 사고 작용, 비판적 태도, 표현력 등을 기를 수 있는 교수법이다',m:null},
{t:'문답법은 교수자와 학습자간 상호적인 [질의응답]을 통해 학습자의 [탐구능력]과 [추상적 사고] 작용, 비판적 태도, 표현력 등을 기를 수 있는 교수법이다',m:null},
{t:'문답법에서 발문을 진행할 때, [학습의욕]을 불러일으키는 발문과 학습자의 사고를 자극하는 [개방적] 발문을 실시하는 것이 적절하다.',m:null},
{t:'문답법은 학습자의 적극적인 학습활동을 유발하여 최종적으로 [자기주도적] 학습을 유발한다.',m:null},
{t:'문답법은 질의응답에서 많은 시간이 소요되어 [대집단]에서 사용이 제한된다.',m:null},
{t:'토의법은 [비판]적인 학습문제를 분석하고 해당 문제 상황에 대한 [해결책]을 탐색하고 [태도]의 변화를 유도하기 위해 진행된다.',m:null},
{t:'토의법은 [사회적] 기능 및 [민주적] 태도를 함양하고 학습자의 [자율성]을 향상시킨다.',m:null},
{t:'토의법은 다량의 [학습내용]을 전달하기 어렵고, 일부 학생이 토론을 [주도]하는 경우, 다수의 학생이 수업에서 [소외]될 수 있다.',m:null},
{t:'효과적인 토의를 위해 명확한 토의 [목적], 구체적인 [계획], 전체적인 토의 결과 [공유] 및 정리시간 배분이 이루어져야 한다.',m:null},
{t:'[배심토의]는 상반되는 견해를 대표하는 패널이 사회자의 진행에 따라 토의하는 방식으로, 청중의 참여도가 [낮다].',m:null},
{t:'[버즈토의]는 소집단으로 분과토의를 한 후 최종적으로 전체 집단이 모여 토의결과를 집결 후 결론을 내려 대집단의 [종합토의]의 효과를 얻는다.',m:null},
{t:'버즈토의는 [소집단] 형성으로 각자에게 자유로운 발언의 기회를 가진다는 점에서 [적극적인] 토의를 유도한다.',m:null},
{t:'[문제해결법]은 현실에서 경험하게 되는 문제를 반성적 사고를 활용하여 해결하는 과정을 중시하는 교수법이다.',m:null},
{t:'문제해결법은 현실에서 경험하게 되는 문제를 [반성적 사고]를 활용하여 해결하는 과정을 중시하는 교수법이다.',m:null},
{t:'문제해결법의 절차는 [문제제기] - [문제인식] - [대안설정] - [대안탐색] - 최선의 [대안선정] - [결과검증] 순이다.',m:null},
{t:'[프로젝트법]은 학습자가 계획한 것을 구체적으로 실현하고 형상화하기 위해 학습자 스스로 계획을 수립하여 실행하고 평가하는 자발적이고 창의적인 학습방법이다.',m:null},
{t:'[발견학습]은 학문의 개념이나 원리를 발견하는 과정을 학습자에게 직접 체험시킴으로써, 과학의 성과와 과학자의 탐구 및 방법을 종합적으로 학습시키려는 교수학습법이다.',m:null},
{t:'발견학습의 절차는 [탐색] 및 [문제파악] - [자료 제시] 및 관찰 탐색 - [자료 추가 제시] 및 관찰 탐색 - [규칙성] 발견 및 [개념 정리] - 적용 및 응용 순이다.',m:null},
{t:'발견학습은 [학문중심] 교육과정과 브루너의 [지식의 구조]와 연관되어있다.',m:null},
{t:'[탐구학습]은 과학의 본질적인 과정인 가설 검증 절차를 체득하는 교수법이다.',m:null},
{t:'탐구학습은 과학의 본질적인 과정인 [가설] 검증 절차를 체득하는 교수법이다.',m:null},
{t:'탐구학습의 절차는 [문제발견] 및 인식 - [가설설정] - [실험설계] - [실험] - [자료 해석] 및 [가설 검증] - 결론 및 [일반화] 순이다.',m:null},
{t:'탐구학습은 [문제해결법]이 발전한 형태로, [학문중심] 교육과정과 연관되어있다.',m:null},
{t:'[협동학습]은 소집단이 공동 목표를 성취하기 위해 동료들과 함께 학습하는 구조화된 체계적인 수업기법이다.',m:null},
{t:'협동학습은 [소집단]이 [공동 목표]를 성취하기 위해 동료과 함께 학습하는 구조화된 체계적인 수업기법이다.',m:null},
{t:'협동학습을 통해 [학업성취] 향상의 인지적 효과와 [자아존중감] 및 [학습동기] 향상의 정의적 효과를 꾀할 수 있다.',m:null},
{t:'협동학습의 원리로 [긍정적 상호의존성], [대면적 상호작용], [개별책무성], [사회적 기술], [집단 과정]이 있다.',m:null},
{t:'협동학습의 원리 중 [긍정적 상호의존성]은 개개인이 집단의 성공을 위해 자신뿐만 아니라 동료들도 성취해야 하기 때문에 서로 도움을 주는 관계가 되는 것을 뜻한다.',m:null},
{t:'협동학습의 원리 중 긍정적 상호의존성은 개개인이 집단의 [성공]을 위해 자신뿐만 아니라 동료들도 성취해야 하기 때문에 서로 [도움]을 주는 관계가 되는 것을 뜻한다.',m:null},
{t:'협동학습의 원리 중 [대면적 상호작용]은 집단 구성원 각자가 집단의 목표를 성취하기 위해 구성원들의 노력을 격려하고 촉진시키는 행위를 하는 것을 뜻한다.',m:null},
{t:'협동학습의 원리 중 대면적 상호작용은 집단 구성원 각자가 집단의 목표를 성취하기 위해 구성원들을 서로 [격려]하고 [촉진]시키는 행위를 하는 것을 뜻한다.',m:null},
{t:'협동학습의 원리 중 [개별책무성]은 과제를 숙달해야 하는 책임으로, 각 학생들에게 있기에 무임승객 효과와 봉 효과를 방지한다.',m:null},
{t:'협동학습의 원리 중 개별책무성은 과제를 숙달해야 하는 [책임]으로, 각 학생들에게 있기에 [무임승객] 효과와 [봉] 효과를 방지한다.',m:null},
{t:'무임승객 효과는 학승능력이 [낮은] 학습자가 [적극적]으로 학습에 참여하지 않고, 학습능력이 [높은] 학습자의 성과를 받으려는 현상이다.',m:null},
{t:'봉 효과는 학습능력이 [높은] 학습자가 자기의 [노력]이 다른 학습자에게 돌아갈까봐 [소극적]으로 학습에 참여하려는 현상이다.',m:null},
{t:'협동학습의 원리 중 [사회적 기술]은 집단 내에서의 의사소통으로 갈등 관리, 의사결정, 리더쉽 등이 있다.',m:null},
{t:'협동학습의 원리 중 [집단 과정]은 진행한 소집단 활동에 대에 반성적 사고를 하는 것이다.',m:null},
{t:'협동학습에서 소집단을 구성할 때 구성원을 [이질적]으로 구성해야한다.',m:null},
{t:'직소모형의 공통절차는 [소집단 구성] - [개인별 전문과제] 부과 - [전문가집단] 활동 - [개별평가] - 점수 산출이다.',m:null},
{t:'직소2 모형은 직소1 모형과 달리 [리더]가 없고, [집단보상]이 존재한다.',m:null},
{t:'직소1 모형은 동료들의 다른 전문과제를 참고하지 않아도 자신의 전문과제 그 자체로 이해할 수 있도록 특별히 설계되어야 하지만, 직소2 모형에서는 [교사]가 개입하여 [수업]을 진행하고 개인별 전문과제가 부과되어, 일반적인 활용과제 활용이 가능하다.',m:null},
{t:'STAD 모형은 효과적인 협동학습을 위해 개개인에게 [향상점수]를 부여하고, [개별책무성], 학습 참여의 [균등한 기회]를 매우 중시하는 것이 특징이다.',m:null},
{t:'STAD 모형의 절차는 [교사]의 [수업 안내] - [소집단] 구성 및 학습 - 개별평가 - 개별&팀별 [향상점수] 산출 - 소집단 점수의 게시와 [보상]이다.',m:null},
{t:'STAD 모형에서 학습자의 협동학습을 유도하기 위해 학습과제지와 정답지를 [인원수]에 [부족]하게 지급한다.',m:null},
{t:'STAD 모형에서 개별 향상점수는 개개인의 현재점수에서 [기본점수]를 차감한 점수로, 보통 음수를 방지하기 위해 구간별로 점수를 선정하여 차등 지급한다.',m:null},
{t:'TGT 모형은 STAD 모형의 퀴즈나 시험을 [토너먼트 게임]으로 대체하여 [경쟁]을 유도하는 협동학습 모형이다.',m:null},
{t:'TGT 모형에서는 퀴즈 대신 게임을 진행하여 학습자에게 흥미를 부여하고, 과거 성적이 [유사]한 다른 구성원들과 토너먼트 테이블에서 경쟁한다.',m:null},
{t:'TGT 모형의 절차는 [교사]의 [수업] 안내 - [소집단] 구성 및 학습 - [토너먼트 게임] - [집단점수]의 게시와 보상',m:null},
{t:'TGT 모형은 STAD 모형과 달리 [개별점수]가 존재하지 않는다.',m:null},
]},
{id:'u10',name:'TAI·PBL 등 협동·문제중심학습',items:[
{t:'[TAI] 모형은 협동학습과 개별학습을 결합한 수업모형으로 수학교과에서 개발되었다.',m:null},
{t:'TAI 모형은 [협동학습]과 [개별학습]을 결합한 수업모형으로 수학교과에서 개발되었다.',m:null},
{t:'TAI 모형의 절차는 소집단 구성 - [배치 검사] - 교육과정 자료 배포 - [소집단 학습] - [교수집단] - [집단]점수와 [집단]보상이다.',m:null},
{t:'TAI 모형의 절차 중 협동학습이 발생하는 단계는 [소집단 학습] 단계, 개별학습이 발생하는 단계는 [교수집단] 단계이다.',m:null},
{t:'TAI 모형의 절차 중 교수집단에서 교사는 [같은 수준]에 있는 아동을 불러내어 직접 가르치는 시간을 갖는다.',m:null},
{t:'TAI 모형을 통해 학생은 성취 수준의 점검절차를 통해 수준에 맞는 적합한 학습의 [개별화]로 시간 낭비 없이 학습이 진행되고, 소집단 학습을 통해 [긍정적 상호의존성]이 형성되게 된다.',m:null},
{t:'[LT] 모형은 사람과 사람 간 피드백 그대화를 위해 개발된 협동학습으로 [긍정적 상호의존성], [대면적 상호작용], [개별책무성], [사회적 기술], [집단과정]이 모두 포함되었다.',m:null},
{t:'LT 모형은 너무 [포괄적]이기 때문에 교사가 교과목과 주제에 맞게 적절히 [구조화]시킬 필요가 있다.',m:null},
{t:'[GI] 모형은 타협의 과정을 통해 학문적 지식을 배우고 사회 문제를 해결하는 경험을 갖게 하려는 협동학습 모형이다.',m:null},
{t:'Co-op Co-op 모형은 학급 전체 과제를 학급의 여러 [소집단]이 협동적으로 해결하기 위해 [소집단]별로 협동학습을 하는 형태를 가진다.',m:null},
{t:'Co-op Co-op 모형에서 주제는 작은 범위부터 [집단 구성원]들의 [소주제], [소집단]의 [집단 주제], [학급 전체]의 [학급 주제]로 총 3종류가 존재한다.',m:null},
{t:'Co-op Co-op 모형의 절차는 학생 중심 학급토론 - 학습집단의 선택 - 집단 세우기와 협동적 기술 개발 - [집단 주제] 선택 - [소주제] 선택 - [소주제] 준비 - [소주제] 발표 - [집단 주제] 발표 준비 - [집단 주제] 발표 - [반성과 평가]이다.',m:null},
{t:'[개별화교수]는 수업의 모든 요소를 학습자 특성에 맞게 조정하는 교수방법으로 학습자의 [개인차]를 고려하였다.',m:null},
{t:'프로그램 학습은 [조작적 조건화]와 학습내용 조직의 [계열성] 원리에 기초를 두었다.',m:null},
{t:'[팀티칭]은 협동교수 방법으로 2명 이상의 (다른 분야) 교사가 동일한 학습집단의 학습지도를 위해 수업을 협동적으로 계획하고 지도하는 교수방법이다.',m:null},
{t:'팀티칭을 통해 교사의 [전문성]을 최대로 이용할 수 있어 학생들에게 보다 풍부한 경험을 제공할 수 있고, 다양한 [학습집단]에 다양한 [교수방법]을 제공할 수 있다.',m:null},
{t:'[자기조절]은 목표를 세우고 그 목표에 도달할 수 있도록 이끌어주는 동기, 사고과정, 전략, 행동을 통합하는 과정이다.',m:null},
{t:'[자기조절학습]은 학습자 스스로가 자기 능력을 객관적으로 인식하고 이에 알맞은 학습목표를 설정하며 이를 달성하기 위한 실천계획을 세워 스스로의 힘으로 학습평가에 도달하는 것이다.',m:null},
{t:'자기조절학습은 학습자 스스로가 자기 능력을 객관적으로 인식하고 이에 알맞은 [학습목표]를 설정하며 이를 달성하기 위한 [실천계획]을 세워 스스로의 힘으로 [학습평가]에 도달하는 것이다.',m:null},
{t:'자기조절학습의 일반적인 구성요소는 [메타인지] 요인, [학습전략] 요인, [동기] 요인이다.',m:null},
{t:'반두라는 자기조절학습의 구성요인을 [목표설정], [자기관찰], [자기평가], [자기반응]으로 설정하였다.',m:null},
{t:'짐머만은 자기조절학습 전략으로 [자기평가], 정보의 조직과 변형, 목표 설정과 계획, 정보 탐색, [계속적인 기록과 관찰], [환경 구조화], [자기 보상 및 처벌], 정보의 반복과 기억, 사회적 도움, [복습] 등을 소개하였다.',m:null},
{t:'[교수내용지식]([PCK])은 특정 내용을 특정 학생들이 효과적으로 이해할 수 있ㄷ록 가르치는 방법에 대한 교사의 지식이다.',m:null},
{t:'캐롤은 전체 교육과정에 관심을 둔 [완전학습]을 위해 학교학습모형을 제시하였다.',m:null},
{t:'학교학습모형에서 [학습의 정도]는 이미 수업목표에서 설정한 도달 기준에 비추어 실체로 성취된 학습 정도이다.',m:null},
{t:'학교학습모형의 학습의 정도는 (학습에 [사용]한 시간) / (학습에 [필요]한 시간) 이다.',m:null},
{t:'캐롤의 학교학습모형에서 교사 변인은 [학습기회]와 [교수의 질]이다.',m:null},
{t:'캐롤의 학교학습모형에서 학습자 변인은 [학습지속력]과 [적성], [교수이해력]이다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 학습기회는 학생에게 주어진 학습과제의 학습을 위해 실제로 [허용]되는 시간이다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 [학습기회]는 학생에게 주어진 학습과제의 학습을 위해 실제로 허용되는 시간이다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 완전학습을 성취하는 데 가장 핵심적인 개념은 [학습기회]이다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 [교수의 질]은 학습정도가 극대화될 수 있도록 학습과제가 개개 학습자에게 효과적으로 제시, 설명, 구성되는 정도이다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 [학습지속력]은 학생이 일정 수준 성취할 때까지 계속해서 노력하는 시간이다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 학습지속력은 학생이 일정 수준 [성취]할 때까지 계속해서 [노력]하는 시간이다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 학습지속력은 학습자 [내부]로부터 나오는 것으로 학습자의 [학습동기], [학습태도]와 관련이 깊다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 적성은 학생 각자가 [학습성취]에 필요로 하는 시간의 양이다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 [적성]은 학생 각자가 학습성취에 필요로 하는 시간의 양이다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 교수이해력은 교수내용이나 쇼사의 설명을 [이해]하는 학생의 능력으로, 학습자의 일반지능, [언어능력]에 의해 결정된다.',m:null},
{t:'캐롤 모형의 5가지 변인 중 [교수이해력]은 교수내용이나 쇼사의 설명을 이해하는 학생의 능력으로, 학습자의 일반지능, 언어능력에 의해 결정된다.',m:null},
{t:'캐롤의 학교학습모형에서 학습에 사용한 시간과 비례 관계에 있는 변인은 [학습기회]와 [학습지속력]이다.',m:null},
{t:'캐롤의 학교학습모형에서 학습에 필요한 시간과 반비례 관계에 있는 변인은 [교수의 질]과 적성, [교수이해력]이다.',m:null},
{t:'[유의미학습]은 새로운 학습과제가 학습자의 인지구조와 관련되어 의미 있는 관계를 맺는 학습이다.',m:null},
{t:'유의미학습은 새로운 학습과제가 학습자의 [인지구조]와 관련되어 의미 있는 관계를 맺는 학습이다.',m:null},
{t:'구속성과 실사성을 지닌 학습과제는 [논리적] 유의미성을 갖는다.',m:null},
{t:'[구속성]과 [실사성]을 지닌 학습과제는 논리적 유의미성을 갖는다. 가나다 순으로 작성하시오.',m:null},
{t:'[실사성]은 한 과제를 다양하게 표현하더라도 그 과제의 의미는 변하지 않는 성질이다.',m:null},
{t:'실사성은 한 과제를 다양하게 표현하더라도 그 과제의 [의미]는 변하지 않는 성질이다.',m:null},
{t:'[구속성]은 임의적으로 맺어진 관계가 학습되었을 때, 그 관계는 다시 임의로 변경될 수 없는 성질이다.',m:null},
{t:'구속성은 임의로 맺어진 관계가 [학습]되었을 때, 그 관계는 다시 임의로 [변경]될 수 없는 성질이다.',m:null},
{t:'학습과제가 [논리적] 유의미성을 가지고, 학습자의 인지구조 속에 학습과제와 관련된 [관련정착 의미]가 있으면, 그 학습과제는 학습자에 대하여 잠재적 유의미성을 갖는다.',m:null},
{t:'학습과제가 논리적 유의미성을 가지고, 학습자의 인지구조 속에 학습과제와 관련된 관련정착 의미가 있으면, 그 학습과제는 학습자에 대하여 [잠재적] 유의미성을 갖는다.',m:null},
{t:'[관련정착 의미]는 학습자의 인지구조에 이미 형성된 것으로, 유의미학습 과정에서 새로운 개념과 인지구조와 관계를 맺을 수 있는 근거를 제공해준다.',m:null},
{t:'관련정착 의미는 학습자의 [인지구조]에 이미 형성된 것으로, 유의미학습 과정에서 새로운 개념과 [인지구조]와 관계를 맺을 수 있는 근거를 제공해준다.',m:null},
{t:'학습과제가 [잠재적] 유의미성을 가지고 있고, 햑습자가 그 과제를 자신의 [인지구조]에 적용시키려고 하는 [유의미학습 태세]를 갖추고 있다면, 그 학습과제는 학습자에 대하여 심리적 유의미성을 갖는다.',m:null},
{t:'학습과제가 잠재적 유의미성을 가지고 있고, 햑습자가 그 과제를 자신의 인지구조에 적용시키려고 하는 유의미학습 태세를 갖추고 있다면, 그 학습과제는 학습자에 대하여 [심리적] 유의미성을 갖는다.',m:null},
{t:'유의미학습 태세는 학습과제를 [인지구조]에 구속적이고도 실사적으로 관련시키고자 하는 학습자의 [성향]이다.',m:null},
{t:'[유의미학습 태세]는 학습과제를 인지구조에 구속적이고도 실사적으로 관련시키고자 하는 학습자의 성향이다.',m:null},
{t:'유의미학습의 과정은 [실사성]과 [구속성]을 갖는 [학습과제]인 독립변인 - [관련정착 의미]를 보유한 인지구조와 [유의미학습 태세]의 [인지과정]인 매개변인 - 학습의 결과인 종속변인 순으로 이루어진다.',m:null},
{t:'[포섭]은 새로운 개념이 학습자의 기존 인지구조에 일체화되는 과정이다.',m:null},
{t:'포섭은 새로운 개념이 학습자의 기존 인지구조에 [일체화]되는 과정이다.',m:null},
{t:'선행조직자는 새로운 학습과제를 학습하기 전 미리 제시하는 학습과제보다 [추상적]이고 [일반적]이며 표괄적인 [도입자료]로, 새로운 자료와 이전 학습의 [연결]을 돕는 장치이다.',m:null},
{t:'[선행조직자]는 새로운 학습과제를 학습하기 전 미리 제시하는 학습과제보다 추상적이고 일반적이며 표괄적인 도입자료로, 새로운 자료와 이전 학습의 [연결]을 돕는 장치이다.',m:null},
{t:'[설명조직자]는 학습자에게 친숙하지 않은 학습과제를 제시할 때, 새 학습과제의 이해를 돕기 위해 사용하는 선행조직자이다.',m:null},
{t:'[비교조직자]는 학습자의 인지구조 속에 학습과제와 유사한 선행지식이 있을 때 혼동을 줄이기 위해 사용하는 선행조직자이다.',m:null},
{t:'설명식 수업의 원리 중 [선행조직자]의 원리는 [선행조직자] 사용 시 새 학습과제를 학습할 때 점진적 증진 효과를 최대화할 수 있다.',m:null},
{t:'설명식 수업의 원리 중 [점진적 분화]의 원리는 가장 포괄적이고 일반적인 개념을 먼저 제시하고 점차 세분화되고 특수한 의미로 분화하도록 제시하는 것이다.',m:null},
{t:'설명식 수업의 원리 중 점진적 분화의 원리는 가장 [포괄적]이고 [일반적]인 개념을 먼저 제시하고 점차 [세분화]되고 [특수한] 의미로 분화하도록 제시하는 것이다.',m:null},
{t:'설명식 수업의 원리 중 [통합적 조정]의 원리는 새로운 학습내용은 이전 학습 내용과 일치되고 통합되어야 한다는 것이다.',m:null},
{t:'유의미수용학습 수업모형의 교수절차는 [선행조직자]의 제시 - [학습과제]와 [자료]의 제시 - [인지적 조직]의 강화이다.',m:null},
{t:'가네의 교수이론에서 학습영역은 [언어정보], [지적기능], [인지 전략], [태도], [운동기능]이 있다.',m:null},
{t:'지적기능은 하위기능부터 [변별], [개념], [원리], [문제해결]로 구성되어 있다.',m:null},
{t:'가네의 학습의 사태는 [정보처리이론]을 근거로 개발되었다.',m:null},
{t:'가네의 학습의 사태와 수업의 사태는 크게 [학습을 위한 준비]([3]단계), [획득과 수행]([4]단계), [학습의 전이]([2]단계)로 구성되어 있다.',m:null},
{t:'학습의 사태에서 학습을 위한 준비는 학습의 [시작] 단계로, [주의집중], [기대], [관련 정보의 재생] 또는 [장기기억으로부터의 기능 재생]이 포함된다.',m:null},
{t:'학습의 사태에서 [주의집중]은 학습자가 관련 자극을 받아들이거나 이해하는 것으로, 그 결과 학습 기대가 일어난다.',m:null},
{t:'학습의 사태에서 주의집중은 학습자가 관련 [자극]을 받아들이거나 이해하는 것으로, 그 결과 [학습 기대]가 일어난다.',m:null},
{t:'학습의 사태에서 주의집중은 정보처리이론에서 [주의]와 관련있다.',m:null},
{t:'학습의 사태에서 [기대]는 학습자에게 주어졌거나 또는 스스로 설정한 학습목표에 도달하기 위한 학습자의 특수한 동기화(반응)이다.',m:null},
{t:'학습의 사태에서 기대는 학습자에게 주어졌거나 또는 스스로 설정한 학습목표에 도달하기 위한 학습자의 특수한 [동기화]([반응])이다.',m:null},
{t:'학습의 사태에서 기대는 정보처리이론에서 [지각]과 관련있다.',m:null},
{t:'학습의 사태에서 [관련 정보의 재생 또는 장기기억으로부터의 기능 재생]은 새로운 학습의 필수 선수학습능력의 장기기억으로부터의 재생이다.',m:null},
{t:'학습의 사태에서 관련 정보의 재생 또는 장기기억으로부터의 기능 재생은 새로운 학습의 필수 [선수학습능력]의 [장기기억]으로부터의 재생이다.',m:null},
{t:'학습의 사태에서 획득과 수행은 학습 [발생] 및 정확한 정보 [저장]의 단계로, [선택적 지각], [의미론적 부호화], [재생과 반응], [피드백]이 포함된다.',m:null},
{t:'학습의 사태에서 [선택적 지각]은 물리적 자극을 알 수 있는 형태로 변형시키고, 작동적 기억에 그 내용을 잠시 파지한다.',m:null},
{t:'학습의 사태에서 선택적 지각은 물리적 자극을 알 수 있는 형태로 변형시키고, 작동적 기억에 그 내용을 잠시 [파지]한다.',m:null},
{t:'학습의 사태에서 [의미론적 부호화]는 자극 특성이 개념망이나 의미망으로 받아들여져 장기기억으로 저장하는 것이다.',m:null},
{t:'학습의 사태에서 의미론적 부호화는 자극 특성이 개념망이나 의미망으로 받아들여져 [장기기억]으로 저장하는 것이다.',m:null},
{t:'학습의 사태에서 의미론적 부호화는 정보처리이론에서 [부호화]와 관련있다.',m:null},
{t:'학습의 사태에서 [재생과 반응]은 장기기억으로부터 새롭게 저장된 부호를 재생하고 반응을 실행하는 과정이다.',m:null},
{t:'학습의 사태에서 재생과 반응은 [장기기억]으로부터 새롭게 저장된 부호를 [재생]하고 [반응]을 실행하는 과정이다.',m:null},
{t:'학습의 사태에서 재생과 반응은 정보처리이론에서 [인출]과 관련있다.',m:null},
{t:'학습의 사태에서 학습의 전이는 평가 및 학습의 마무리 단계로, [재생을 위한 암시]와 [일반화]가 포함된다.',m:null},
{t:'학습의 사태에서 [재생을 위한 암시]는 이후의 학습과 관련되는 재생을 위해 부가적 암시를 제공하는 단계다.',m:null},
{t:'학습의 사태에서 재생을 위한 암시는 이후의 학습과 관련되는 [재생]을 위해 부가적 암시를 제공하는 단계다.',m:null},
{t:'학습의 사태에서 [일반화]는 학습한 내용을 다양한 상황에 일반화하여 새로운 상황으로의 학습 전이를 높인다.',m:null},
{t:'학습의 사태에서 일반화는 학습한 내용을 다양한 상황에 일반화하여 새로운 상황으로의 학습 [전이]를 높인다.',m:null},
{t:'수업의 사태에서 학습을 위한 준비에는 [주의집중], [학습목표 제시], [선수학습 요소의 재생 자극]이 포함되어 있다.',m:null},
{t:'수업의 사태에서 [주의집중]은 학습동기를 유발시키기 위한 일차적 요소이며 시각자료 제시 등으로 학습자의 주의를 획득하는 단계다.',m:null},
{t:'수업의 사태에서 주의집중은 학습동기를 [유발]시키기 위한 일차적 요소이며 [시각자료] 제시 등으로 학습자의 [주의]를 획득하는 단계다.',m:null},
{t:'수업의 사태에서 [학습목표 제시]는 평가기준에 대한 학습의 방향을 제시하는 과정이다.',m:null},
{t:'수업의 사태에서 학습목표 제시는 [평가기준]에 대한 학습의 방향을 제시하는 과정이다.',m:null},
{t:'수업의 사태에서 [선수학습 요소의 재생 자극]은 학습자가 새로운 정보를 학습하는 데 미리 필요한 기능을 확인하는 것이다.',m:null},
{t:'수업의 사태에서 선수학습 요소의 재생 자극은 학습자가 [새로운] 정보를 학습하는 데 [미리] 필요한 기능을 확인하는 것이다.',m:null},
{t:'수업의 사태에서 획득과 수행에는 [자극 제시하기], [학습 안내 제시하기], [성취 행동 유도하기], [피드백 제공하기]가 있다.',m:null},
{t:'수업의 사태에서 [자극 제시하기]는 학습자에게 학습할 내용을 제시하는 과정이다.',m:null},
{t:'수업의 사태에서 [학습 안내 제시하기]는 이전 정보와 새로운 정보를 적절히 통합시키고 그 결과를 장기기억에 저장시킬 수 있도록 도움을 주는 단계이다.',m:null},
{t:'수업의 사태에서 학습 안내 제시하기는 이전 정보와 새로운 정보를 적절히 [통합]시키고 그 결과를 [장기기억]에 저장시킬 수 있도록 도움을 주는 단계이다.',m:null},
{t:'수업의 사태에서 [성취 행동 유도하기]는 학습한 요소들을 실제로 실행할 수 있는지를 증명하는 기회를 제공하는 단계이다.',m:null},
{t:'수업의 사태에서 성취 행동 유도하기는 학습한 요소들을 실제로 실행할 수 있는지를 [증명]하는 기회를 제공하는 단계이다.',m:null},
{t:'수업의 사태에서 [피드백 제공하기]는 성취 행동에 대한 결과를 알려주는 단계이다.',m:null},
{t:'수업의 사태에서 재생과 전이에는 [성취 행동 평가하기], [파지 및 전이 높이기]가 있다.',m:null},
{t:'수업의 사태에서 [성취 행동 평가하기]는 다음 단계의 학습이 가능한지를 결정하기 위해 평가를 실시하는 단계다.',m:null},
{t:'수업의 사태에서 성취 행동 평가하기는 [다음 단계]의 학습이 가능한지를 결정하기 위해 [평가]를 실시하는 단계다.',m:null},
{t:'수업의 사태에서 [파지 및 전이 높이기]는 학습내용을 다른 상황에 일반화하거나 적용할 수 있는 경험을 제공하는 단계이다.',m:null},
{t:'수업의 사태에서 파지 및 전이 높이기는 학습내용을 다른 상황에 [일반화]하거나 [적용]할 수 있는 경험을 제공하는 단계이다.',m:null},
{t:'메릴의 내용요소제시이론은 하나의 아이디어를 교수하는 방법 처방에 관심을 둔 [미시적] 교수설계이론 중 하나이다.',m:null},
{t:'메릴은 학업수행의 수준을 [기억], [활용], [발견]으로 나누고, 학습내용을 [사실], [개념], [절차], [원리]로 나누어 그들의 관계를 행렬표로 나타내었다.',m:null},
{t:'메릴은 [학업수행]의 수준을 기억, [활용], [발견]으로 나누고, [학습내용]을 사실, [개념], [절차], [원리]로 나누어 그들의 관계를 행렬표로 나타내었다.',m:null},
{t:'내용요소제시이론의 일차제시형에서 예시는 [설명식]과 [사례]를 혼합한 제시방식이다.',m:null},
{t:'내용요소제시이론의 일차제시형에서 법칙은 [설명식]과 [일반성]을 혼합한 제시방식이다.',m:null},
{t:'내용요소제시이론의 일차제시형에서 회상은 [질문식]과 [일반성]을 혼합한 제시방식이다.',m:null},
{t:'내용요소제시이론의 일차제시형에서 연습은 [질문식]과 [사례]를 혼합한 제시방식이다.',m:null},
{t:'내용요소제시이론의 일차제시형에서 [내용성격]에 따라 일반성과 사례로, [전달방식]에 따라 설명식과 질문식으로 나뉜다.',m:null},
{t:'내용요소제시이론의 일차제시형에서 [예시]는 설명식과 사례를 혼합한 제시방식이다.',m:null},
{t:'내용요소제시이론의 일차제시형에서 [법칙]은 설명식과 일반성을 혼합한 제시방식이다.',m:null},
{t:'내용요소제시이론의 일차제시형에서 [회상]은 질문식과 일반성을 혼합한 제시방식이다.',m:null},
{t:'내용요소제시이론의 일차제시형에서 [연습]은 질문식과 사례를 혼합한 제시방식이다.',m:null},
{t:'라이겔루스의 [개념학습]이론은 조직전략 중 미시전략에 해당하는 이론이다.',m:null},
{t:'라이겔루스의 개념학습이론은 조직전략 중 [미시전략]에 속하는 이론으로, 개념을 새로운 대상에 적용하는 것인 [전이]가 목적인 학습이론이다.',m:null},
{t:'개념학습이론의 교수원리에는 [전형의 형성], [변별], [일반화]가 있다.',m:null},
{t:'개념학습이론에서 전형의 형성은 개념을 대표하는 [본질적 특성]을 학습하는 것이다.',m:null},
{t:'개념학습이론에서 변별은 한 가지 개념의 사례들이 공통적으로 지니고 있는 속성 혹은 특성인 [결정적 속성]을 학습하여 개념 대상을 변별하는 과정이다.',m:null},
{t:'개념학습이론에서 일반화는 개념이 가지고 있는 [가변적 특성]을 통해 개념 대상에 속하는 모든 것을 적용하는 과정이다.',m:null},
{t:'개념학습이론의 절차는 [제시] - [연습] - [피드백] 순이다.',m:null},
{t:'라이겔루스의 [정교화]이론은 조직전략 중 거시전략에 해당하는 이론이다',m:null},
{t:'라이겔루스의 정교화이론은 조직전략 중 [거시]적 조직전략에 관한 이론으로, 수업의 전체적 윤곽 제시를 시작으로 점차 구체화되고 세분화되면서 이미 제시되었던 일반적이고 간단하면서 기초적인 내용([정수])을 정교화하는 방식으로 수업이 전개된다.',m:null},
{t:'정교화이론의 절차는 [전체개요] - [정교화] - [요약] - [종합] 순이다.',m:null},
{t:'정교화이론에서 정수는 [교수내용]을 대표하는 소수의 일반적이고 간단하면서도 구체적인 아이디어나 원리로 [지식의 구조]와 유사하다.',m:null},
{t:'정교화이론의 기본전략 중 [단순]-[복잡의 정교적 계열화]는 단순한 내용으로부터 복잡한 내용으로의 계열으로 정수화를 통해 시작된다.',m:null},
{t:'정교화이론의 기본전략 중 단순-복잡의 정교적 계열화은 [단순]한 내용으로부터 [복잡]한 내용으로의 계열으로 [정수화]를 통해 시작된다.',m:null},
{t:'정교화이론의 기본전략 중 [학습 선수능력의 계열화]는 학습의 위계에 기초하여 특정 지식을 학습하기 전에 해당 지식을 학습하기 위해 필요한 지식들을 먼저 배우도록 순서화하는 것이다.',m:null},
{t:'정교화이론의 기본전략 중 학습 선수능력의 계열화는 학습의 [위계]에 기초하여 특정 지식을 학습하기 전에 해당 지식을 학습하기 위해 필요한 지식들을 [먼저] 배우도록 [순서화]하는 것이다.',m:null},
{t:'정교화이론의 기본전략 중 [요약자]는 학습한 것을 망각하지 않도록 하기 위한 복습으로, 개념에 대한 간결한 진술이 이루어진다.',m:null},
{t:'정교화이론의 기본전략 중 요약자는 학습한 것을 [망각]하지 않도록 하기 위한 [복습]으로, 개념에 대한 간결한 진술이 이루어진다.',m:null},
{t:'정교화이론의 기본전략 중 [종합자]는 단일 유형의 아이디어들을 관련짓고 통합하기 위한 전략으로, 통합적 사례가 제시된다.',m:null},
{t:'정교화이론의 기본전략 중 종합자는 단일 유형의 아이디어들을 관련짓고 [통합]하기 위한 전략으로, [통합적 사례]가 제시된다.',m:null},
{t:'정교화이론의 기본전략 중 [비유]는 새로운 아이디어들을 친숙한 아이디어들곽 관련시켜 새로운 아이디어를 보다 쉽게 이해하도록 돕는 전략이다.',m:null},
{t:'정교화이론의 기본전략 중 [인지전략 자극자]는 학습자가 사용하는 인지전략을 보다 활성할시킬 수 있도록 도와주는 전략이다.',m:null},
{t:'정교화이론의 기본전략 중 [학습자 통제 형태]는 학습에 대한 통제권을 부여하여 단계로, 학습의 효율과 효과를 증진시킨다.',m:null},
{t:'정교화이론의 7대 기본전략에는 [단순-복잡의 정교적 계열화], [학습 선수능력의 계열화], [요약자], [종합자], [비유], 인지전략 자극자, 학습자 통제 형태가 있다.',m:null},
{t:'켈러의 동기설계이론(ARCS)은 교수자료의 [동기적] 측면을 향상시키기 위한 체계적 방법으로 제안되었고, 동기 유발 및 유지에 대해 [처방적]인 전략을 제시한다.',m:null},
{t:'ARCS 이론은 크게 [주의집중], [관련성], [자신감], [만족감]으로 구성되어 있다. 충족 시 [동기]가 상승한다.',m:null},
{t:'ARCS의 주의집중은 학습자의 [호기심]과 [관심]을 유발하고 유지시키는 요소이다.',m:null},
{t:'ARCS의 관련성은 교수-학습활동을 학습자의 [필요] 및 [가치]와 연결하는 요소이다.',m:null},
{t:'ARCS의 자신감은 [성공]에 대한 자신감과 기대를 가지도록 하는 요소이다.',m:null},
{t:'ARCS의 만족감은 교수-학습활동에 대한 [강화[를 관리하여 [동기]가 계속되게 하는 요소이다.',m:null},
{t:'ARCS의 주의집중에는 [지각적 주의환기]의 전략, [탐구적 주의환기]의 전략, [다양성]의 전략이 있다.',m:null},
{t:'ARCS의 관련성에는 [친밀성]의 전략, [목적지향성]의 전략, [필요나 동기와의 부합성 강조]의 전략이 있다.',m:null},
{t:'ARCS의 자신감에는 [학습의 필요조건 제시] 전략, [성공의 기회 제시] 전략, [개인적 조절감 증대] 전략이 있다.',m:null},
{t:'ARCS의 만족감에는 [자연적 결과 강조] 전략, [긍정적 결과 강조] 전략, [공정성 강조] 전략이 있다.',m:null},
{t:'ARCS에서 [지각적 주의환기]의 전략은 지각적으로 학습자의 주의를 유발 및 유지시키는 전략이다.',m:null},
{t:'ARCS에서 [탐구적 주의환기]의 전략은 학습자에게 스스로 문제나 질문 등을 만들어 보도록 하여 정보탐구행동을 자극하도록 하는 전략이다.',m:null},
{t:'ARCS에서 탐구적 주의환기의 전략은 학습자에게 스스로 문제나 질문 등을 만들어 보도록 하여 [정보탐구행동]을 자극하도록 하는 전략이다.',m:null},
{t:'ARCS에서 [다양성]의 전략은 교수의 요소들을 변화시켜 학습자의 흥미를 유지하는 전략이다. 예시로 다양한 [상호작용]식 교수학습의 [혼합] 사용이 있다.',m:null},
{t:'ARCS에서 [친밀성]의 전략은 학습자의 경험과 가치에 연관되는 예문이나 용어등을 사용함으로써 얻어질 수 있는 전략이다.',m:null},
{t:'ARCS에서 [목적지향성]의 전략은 결과 측면의 관련성을 높일 수 있는 구체적 방법을 제시해 주기 위해 교수의 목표 등을 포함시킬 것을 강조하는 전략이다.',m:null},
{t:'ARCS에서 [필요나 동기와의 부합성 강조]의 전략은 교수의 과정 또는 방법 측면의 관련성을 강조하여 학습자의 필요나 동기와 부합되는 수업을 사용하는 전략이다.',m:null},
{t:'ARCS에서 [학습의 필요조건 제시] 전략은 수행의 필요조건과 평가기준을 제시하여 학습자가 성공 가능 여부를 짐작하도록 돕는 전략이다.',m:null},
{t:'ARCS에서 [성공의 기회 제시] 전략은 학습과정과 수행의 조건에서 적절한 수준의 도전감을 제공하는 전략이다.',m:null},
{t:'ARCS에서 [개인적 조절감 증대] 전략은 개인의 노력이나 능력에 성공이 귀착되어있음을 피드백과 조절의 기회 제공을 통해 전달하는 전략이다.',m:null},
{t:'ARCS에서 [자연적 결과 강조] 전략은 학습자의 내적 동기를 유지시키기 위해 내적 보상을 지급하는 전략이다.',m:null},
{t:'ARCS에서 [긍정적 결과 강조] 전략은 바람직한 행동ㅇ르 계속 유지시키기 위해 긍정적 피드백이나 외적 보상을 지급하는 전략이다.',m:null},
{t:'ARCS에서 [공정성 강조] 전략은 학습자의 학업성취에 대한 기준과 결과를 일관성 있게 유지하는 전략이다.',m:null},
{t:'구성주의적 교수-학습법에서는 [학습자 중심]의 학습환경이 조성되어 인지발달을 위한 [비계활동]과 공동체와의 [협동학습]이 강조되며, 평가 역시 [과정] 중심의 평가로 변화하였다. 이때 교사는 [보조자]와 [촉진자]의 역할을 수행해야 한다.',m:null},
{t:'[문제중심학습]은 실제적이고 비구조화된 문제의 해결이 중심으로 이루어지는 교수-학습활동이다.',m:null},
{t:'문제중심학습은 실제적이고 [비구조화]된 문제의 [해결]이 중심으로 이루어지는 교수-학습활동이다.',m:null},
{t:'문제해결능력은 크게 [가설-연역적 추론]기능과 [자기주도적 학습]기능으로 나뉜다.',m:null},
{t:'문제중심학습은 [자기주도적]인 개인 학습 활동과 [협동학습]적인 문제해결 과정으로 구성되어있다.',m:null},
{t:'Barrows의 PBL 절차는 강좌 소개 - [문제 제시] - [문제 재확인] - 발표 - [문제 결론] 순이다.',m:null},
{t:'PBL의 문제 제시 단계에서 학습자들은 문제해결을 위해 [생각] - [사실] - [학숩과제] - [향후계획]의 네 단계를 거치면서 문제를 검토한다.',m:null},
]},
{id:'u11',name:'인지적 도제·블렌디드·플립러닝',items:[
{t:'인지적 도제이론은 [전문가]의 과제수행 과정이나 문제해결 과정을 [초보자]인 학생이 관찰하여 [전문가]의 사고과정을 학습하도록 하는 모형으로, 사고의 [시각화]를 강조하는 교수-학습 모형이다.',m:null},
{t:'[인지적 도제]이론은 전문가의 과제수행 과정이나 문제해결 과정을 초보자인 학생이 관찰하여 전문가의 사고과정을 학습하도록 하는 모형으로, 사고의 [시각화]를 강조하는 교수-학습 모형이다.',m:null},
{t:'인지적 도제이론은 [모델링] - [코칭] - [비계설정] - [명료화] - [성찰] - [탐색] 순으로 진행된다.',m:null},
{t:'인지적 도제이론 중 [모델링] 단계는 과제를 수행하기 위해 필요한 과정을 학습자가 관찰할 수 있도록 교사나 전문가가 과제 수행 과정을 보여주는 단계이다.',m:null},
{t:'인지적 도제이론 중 모델링 단계에서는 [내적]인 과정을 [외적]으로 표현하는 것을 요구하고, 보통 자신의 생각을 말로 표현하여 생각을 [시연]한다.',m:null},
{t:'인지적 도제이론 중 [코칭] 단계는 학습자가 학습을 하거나 과제를 수행하는 동안 교사나 전문가가 그들을 관찰하고 도움을 제공하는 단계이다.',m:null},
{t:'인지적 도제이론 중 [비계설정] 단계는 학습자의 과제 수행을 돕기 위해 제공하는 도움으로 코칭보다는 좁은 의미로 사용된다. 스스로 과제를 수행하는 단계가 되면 점차 [소멸]되어야 한다.',m:null},
{t:'인지적 도제이론 중 [명료화] 단계는 학습자들이 그들의 지식이나 사고, 문제해결 과정을 명백하게 진술하도록 하는 단계이다.',m:null},
{t:'인지적 도제이론 중 [성찰] 단계는 문제 상황에 대한 학습자 자신의 반응을 전문가나 다른 학생의 것과 비교하는 단계이다.',m:null},
{t:'인지적 도제이론 중 [탐색] 단계는 학습자가 스스로 자신의 문제해결 방법을 고안하도록 안내하는 단계이다.',m:null},
{t:'인지적 도제이론의 핵심 요소이며, 교사의 직접적인 개입이 보이는 단계는 [모델링], [코칭], [비계설정]이다.',m:null},
{t:'인지적 도제이론의 절차 중 학습자 중심 활동이 주가 되는 단계는 [명료화], [성찰], [탐색]이다.',m:null},
{t:'[인지적 유연성]은 지식을 상황에 맞게 유연하게 재구성하는 능력이다.',m:null},
{t:'인지적 유연성 이론은 [상황 의존적 스키마 연합체]를 형성하기 위한 교수-학습 모형이다.',m:null},
{t:'복잡하고 다차원적 특성을 지니는 지식을 학습자가 지식의 필요에 맞게 재구성하고 표상하기 위해 [상황 의존적 스키마 연합체]가 필요하다.',m:null},
{t:'인지적 유연성 이론에는 실생활과 관련된 [사례 기반 수업], [주제 중심 학습], 지식에 대한 [임의적 접근]을 가능하게 하는 [하이퍼미디어 활용] 학습환경 설계가 필요하다.',m:null},
{t:'인지적 유연성 이론을 활용하여 학습환경을 설계할 때 고려사항으로 [소사례] 제시, 다양한 [지식 표상], [반복 학습] 기회 제공, [다원적 조망] 교차 제공, 상호관련성, 보조 탐색 도구 등이 있다.',m:null},
{t:'복잡한 전체 사례를 이해하도록 사례에 대한 구체적인 예를 [소사례]로 제시하여 학습자의 지식 적용 및 전이를 높일 수 있다.',m:null},
{t:'복잡한 전체 사례를 이해하도록 사례에 대한 구체적인 예를 소사례로 제시하여 학습자의 [지식 적용] 및 [전이]를 높일 수 있다.',m:null},
{t:'복잡하고 비구조적인 지식의 이해에서는 다양한 [지식 표상]으로 지식의 특성을 반영하여 문제에 대한 이해 및 해결능력을 향상시킬 수 있다.',m:null},
{t:'복잡하고 비구조적인 지식의 이해에서는 다양한 지식 표상으로 지식의 특성을 반영하여 문제에 대한 [이해] 및 [해결능력]을 향상시킬 수 있다.',m:null},
{t:'반복 학습 기회 제공은 단순히 반복해서 사용하는 것이 아닌 동일한 과제를 여러 번 수행하면서 과제 속 다양한 [정보]를 [탐색]하도록 하는 활동에 해당한다. 이를 통해 [통찰력]을 기를 수 있다.',m:null},
{t:'[다원적 조망] 교차 제공은 특정 문제 또는 사례를 다양한 맥락과 관점에서 해석하는 활동으로, 이해하면서 [인지적 유연성]을 기를 수 있다.',m:null},
{t:'다원적 조망 교차 제공은 특정 문제 또는 사례를 다양한 [맥락]과 관점에서 해석하는 활동으로, 이해하면서 [인지적 유연성]을 기를 수 있다.',m:null},
{t:'사례와 개념, 사례와 사례 간 상호관련성을 위해 적절한 거리를 두어 제시해야하며, 너무 근접 시 지나친 [일반화]를 발생시키고, 너무 멀어지면 둘 사이 [연관성]을 발견하기 어려워진다.',m:null},
{t:'보조 탐색 도구를 통해 [인지적 부담감]을 줄이고, [방향감] 상실을 방지할 수 있다.',m:null},
{t:'상황학습에서는 [지식]이나 기능은 유의미한 맥락 안에서 제공될 때 효과적으로 학습된다고 주장한다.',m:null},
{t:'상황학습에서 지식은 [실제적인 맥락]과 함께 제공되어야 하며, 실생활에서 다루어지는 [실제적인 과제]를 사용해야한다.',m:null},
{t:'[정착교수]는 지식이나 기능이 고유한 맥락 안에 정착되어 있는 교수법이다.',m:null},
{t:'정착교수에서는 학습자끼리의 [상호협력]과 [도움]을 학습활동의 최우선 과제로 삼는다.',m:null},
{t:'정착교수는 [공학]에 기초하여 구성되어야 하고, 현실적 문제를 중심으로 한 [이야기식] 표현을 사용한다. 또한, [통합교육과정]의 형태의 [복잡성]을 가진 문제로 진행이 이루어져야한다.',m:null},
{t:'[실천공동체]는 인간의 노력이 공유된 영역에서 집단적인 학습의 과정에 참여하는 사람들에 의해 형성된다.',m:null},
{t:'상보적 교수이론은 협력적인 교수대화를 사용하고, 토론전략을 이용하는데 전략으로 [예측]하기, [질문]하기, [요약]하기, [명료화]하기가 있다.',m:null},
{t:'상보적 교수이론을 이용해 교사는 전략들을 사용하는 [시범]을 보이고, 학생들을 연습시켜 교사 주도적인 방법을 사용하다가, 점차적으로 이러한 전략이 학생에게 [내면화]되면서 학생 주도적인 활동으로 변하게 된다.',m:null},
{t:'[목표기반 시나리오]는 정해진 목표를 중심으로 시나리오라는 설정된 상황에 배치되어 맡은 역할을 수행하는 과정에서 정해진 목표를 성취하도록 하는 교수-학습모형이다.',m:null},
{t:'목표기반 시나리오는 [목표], [임무], [표지이야기], 역할, [시나리오 운영], 자원, 피드백으로 구성되어 있다.',m:null},
{t:'목표기반 시나리오의 구성 중 [목표]는 학습자들이 시나리오를 통해 도달하는 영역이다.',m:null},
{t:'목표기반 시나리오의 구성 중 목표는 학습자들이 시나리오를 통해 [도달]하는 영역이다.',m:null},
{t:'목표기반 시나리오의 구성 중 [임무]는 학습자들이 설정된 목표를 성취하기 위해 수행해야 하는 과제이다.',m:null},
{t:'목표기반 시나리오의 구성 중 임무는 학습자들이 설정된 [목표]를 성취하기 위해 수행해야 하는 [과제]이다.',m:null},
{t:'목표기반 시나리오에서 동기 유발과 목표 의식 자극을 위해 임무는 학습자의 실제 상황과 맞는 [유의미]하고 [실제적]인 과제로 제시되어야 한다.',m:null},
{t:'목표기반 시나리오의 구성 중 [표지이야기]는 임무의 당위성과 실체성을 나타내기 위한 이야기이다.',m:null},
{t:'목표기반 시나리오의 구성 중 표지이야기는 임무의 [당위성]과 [실체성]을 나타내기 위한 이야기이다.',m:null},
{t:'목표기반 시나리오의 구성 중 [역할]은 학습자들이 표지이야기 속에서 맡게되는 인물로, 학습구성원들은 모두 같은 인물의 역할을 맡는다.',m:null},
{t:'목표기반 시나리오의 구성 중 [시나리오 운영]은 학습자가 임무 달성을 위해ㅐ 학습활동을 예측하고 이를 시나리오 이야기를 구성하는 데 배치한 것이다.',m:null},
{t:'목표기반 시나리오의 구성 중 [자원]은 목표 달성에 필요한 정보와 도구이다.',m:null},
{t:'목표기반 시나리오으 구성 중 [피드백]은 학습자들이 미션을 수행하는 과정에서 발생하는 어려움의 해결을 돕는 교수자의 도움이다.',m:null},
{t:'[자원기반학습]은 학습자 스스로 다양한 학습 자원과 직접적인 상호작용을 함으로써 이루어지는 학습 형태이다.',m:null},
{t:'자원기반학습은 학습자 스스로 다양한 학습 자원과 직접적인 [상호작용]을 함으로써 이루어지는 학습 형태이다.',m:null},
{t:'자원기반학습을 위한 학습기술로 [비판적 사고]기술, [정보자원의 탐색] 및 [활용]기술, [정보자원의 평가]기술이 있다.',m:null},
{t:'자원기반학습의 비판적 사고기술은 가치를 판단하기 위해 적용되는 합리적 사고의 작용으로 정보의 [판단력], 정보의 [분석력], 정보의 정리 및 조직력이 있다.',m:null},
{t:'자원기반학습의 정보자원의 탐색 및 활용기술은 정보를 효과적으로 사용하기 위해 모든 유형의 정보를 [파악]하고 [탐색]하여 필요한 부분을 [활용]하는 기술이다.',m:null},
{t:'자원기반학습의 정보자원의 평가기술은 문제해결에 필요한 가치 있는 정보를 [선정]하기 위해 필요한 요소로 이루어지는 학습기술로, 정보에 대한 [신뢰성], [정보출처]에 대한 권위, [사실]과 [의견]의 구분 등이 있다.',m:null},
{t:'자원기반학습 환경은 [자원], [맥락], [도구]자원, [비계]자원으로 구성되어있다.',m:null},
{t:'자원기반학습의 교수-학습 모형 중 BIG 6 Skills 모형의 절차는 [과제정의] - [정보탐색전략] - [소재파악과 접근] - [정보활동] - [통합정리] - [평가]이다.',m:null},
{t:'자원기반학습에서 단순한 학습자원의 제시에만 그친다면 학습은 [이루어지지 않는다].',m:null},
{t:'구성주의에서는 학습자 중심의 학습지원 환경의 설계가 중시되어 ‘교수설계‘보다는 ’[학습설계]‘라는 용어를 주로 사용한다.',m:null},
{t:'구성주의 학습환경 설계 시 고려해야 할 요소로 문제, [관련사례], [정보자원], [인지도구], [대화]/[협력도구], [사회적]/[맥락적 지원]이 있다.',m:null},
{t:'구성주의 학습환경에서 문제는 대체로 쉽게 풀리지 않고, 다양한 [관점]을 도출할 수 있는 문제를 제시하여 새로운 학습을 유발해야한다.',m:null},
{t:'구성주의 학습환경에서 [관련사례]는 제시된 문제에 포함된 쟁점들을 보다 명확히 파악하게 만드는 학습환경이다.',m:null},
{t:'구성주의 학습환경에서 [정보자원]은 학습자의 문제 규정 및 가설 설정을 이루어지게 만드는 학습환경이다.',m:null},
{t:'구성주의 학습환경에서 정보자원은 학습자의 [문제 규정] 및 [가설 설정]을 이루어지게 만드는 학습환경이다.',m:null},
{t:'구성주의 학습환경에서 [인지도구]는 학습자가 실제 문제를 해결해가는 인지과정을 지원하고 촉진하는 학습환경이다.',m:null},
{t:'구성주의 학습환경에서 인지도구는 학습자가 실제 문제를 해결해가는 [인지과정]을 지원하고 촉진하는 학습환경이다.',m:null},
{t:'구성주의 학습환경에서 [대화]/[협력도구]는 컴퓨터 매개 통신과 같이 학습자 상호 간에 이루어지는 학습활동을 지원하는 수단으로 지식 구성 과정을 촉진하는 학습환경이다.',m:null},
{t:'구성주의 학습환경에서 대화/협력도구는 컴퓨터 매개 통신과 같이 [학습자 상호] 간에 이루어지는 학습활동을 지원하는 수단으로 지식 구성 과정을 촉진하는 학습환경이다.',m:null},
{t:'구성주의 학습환경에서 [사회적]/[맥락적 지원]은 학습자의 학습 과정과 관련된 학습의 사회적 맥락적 요인이다.',m:null},
{t:'구성주의 학습환경에서 사회적/맥락적 지원은 학습자의 [학습 과정]과 관련된 학습의 사회적 맥락적 요인이다.',m:null},
{t:'구성주의 학습환경에서 학습자의 탐색 활동을 지원하는 교수 활동은 [모델링] 활동이다.',m:null},
{t:'구성주의 학습환경에서 학습자의 [탐색] 활동을 지원하는 교수 활동은 모델링 활동이다.',m:null},
{t:'구성주의 학습환경에서 학습자의 [명료화] 활동을 지원하는 교수 활동은 코칭 활동이다.',m:null},
{t:'구성주의 학습환경에서 학습자의 명료화 활동을 지원하는 교수 활동은 [코칭] 활동이다.',m:null},
{t:'구성주의 학습환경에서 학습자의 성찰 활동을 지원하는 교수 활동은 [비계설정] 활동이다.',m:null},
{t:'구성주의 학습환경에서 학습자의 [성찰] 활동을 지원하는 교수 활동은 비계설정 활동이다.',m:null},
{t:'ADDIE는 교수체제설계의 기본과정인 [분석], [설계], [개발], [실행], [평가]의 앞글자를 따서 부르는 교수체제설계의 기본모형으로, 다양한 ISD 모형의 기초가 된다.',m:null},
{t:'ADDIE의 분석 단계에는 [요구분석], [학습자 분석], [환경분석], [직무] 및 [과제] 분석이 있다.',m:null},
{t:'ADDIE의 분석 단계 중 [요구분석]에서는 현재 상태와 원하는 상태 사이의 차이를 확인하여 달성해야 할 수준이나 과제를 분석한다.',m:null},
{t:'ADDIE의 분석 단계 중 [학습자 분석]에서는 학습자의 연령, 동기, 적성 등 현재 특성을 분석한다.',m:null},
{t:'ADDIE의 분석 단계 중 [환경분석]에서는 수업이 이루어지는 환경인 학습환경과 학습환경을 활용하는 환경인 수행환경을 분석한다.',m:null},
{t:'ADDIE의 분석 단계 중 환경분석에서는 수업이 이루어지는 환경인 [학습환경]과 그것을 활용하는 환경인 [수행환경]을 분석한다.',m:null},
{t:'ADDIE의 분석 단계 중 직무 및 학습과제 분석에서는 [학습목표]의 특성을 분석한다.',m:null},
{t:'ADDIE의 [분석] 단계는 교수설계의 초기에 설계를 위한 조직적인 계획을 결정하는 단계이다.',m:null},
{t:'ADDIE의 [설계] 단계는 어떻게 교수-학습활동을 계획할 것인가를 결정하는 단계로 교육과 훈현의 구체적인 청사진을 제시하는 단계이다.',m:null},
{t:'ADDIE의 설계 단계에서는 [수행목표진술], [평가도구]의 개발, 계열화, 교수 전략 및 [매체] 선정 등이 이루어진다.',m:null},
{t:'ADDIE의 [개발] 단계에서는 청사진에 따라 교수자료를 실제로 [개발], 수정, 보완하는 단계로 형성평가를 실시한다.',m:null},
{t:'ADDIE의 개발 단계에서는 청사진에 따라 교수자료를 실제로 개발, 수정, 보완하는 단계로 [형성평가]를 실시한다.',m:null},
{t:'교수설계의 형성평가에서는 학습목표 달성에 대한 교수-학습자료와 매체의 [적합성], 학습목표에 대한 평가도구의 [일관성], 개발비용, 활용성 등 다양한 기준에서 평가를 실시한다.',m:null},
{t:'ADDIE의 [실행] 단계는 형성평가를 거친 산출물을 실제 현장에서 활용 및 적용해보는 단계이다.',m:null},
{t:'ADDIE의 평가 단계는 교수설계 과정의 [효율성]을 평가하고, 교수내용이 효과적으로 전달되었느냐를 평가하는 단계이다.',m:null},
{t:'ADDIE의 평가 단계에서는 교수설계의 성과 변인인 [효과성], [효율성], [매력성], 안정성을 평가한다. 또한 최종 산출물을 사용할지 폐기할지 결정한다.',m:null},
{t:'딕과 캐리의 교수체제설계모형은 [교수목적] 확인 - [교수]분석 - [학습자] 및 [맥락]분석 - [수행목표 기술] - [평가도구] 개발 - [수업전략] 개발 - [수업자료] 개발 및 선정 - 수업 [형성평가] 실행 - 교수 프로그램의 [수정] - [총괄평가] 실행 순으로 진행된다.',m:null},
{t:'딕과 캐리의 ISD에서 [교수목적 확인] 단계는 학습을 마친 후 학습자가 무엇을 할 수 있게 되기를 원하는가를 결정하는 단계로, 수행목표보다 더 포괄적인 목적을 제시한다.',m:null},
{t:'딕과 캐리의 ISD에서 [교수분석] 단계는 학습자가 교수목적에 도달하기 위해 단계별로 무엇을 어떻게 수행할 것인가를 결정하는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 교수분석 단계는 학습자가 [교수목적]에 도달하기 위해 단계별로 무엇을 어떻게 수행할 것인가를 결정하는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 [학습자] 및 [맥락분석] 단계는 학습자의 특성과 학습상황, 학습자가 학습내용을 활용하게 될 맥락을 분석하는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 [수행목표 기술] 단계는 교수분석 및 출발점 행동 진술에 입각하여, 학습이 종결되었을 때 학습자가 무엇을 할 수 있는지를 구체적으로 진술하는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 수행목표 기술 단계는 [교수분석] 및 [출발점 행동] 진술에 입각하여, 학습이 [종결]되었을 때 학습자가 무엇을 할 수 있는지를 구체적으로 진술하는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 [평가도구 개발] 단계는 목표에서 가르치고자 했던 기능을 학습자가 성취했는지 알아볼 수 있는 검사문항을 개발하는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 평가도구 개발 단계는 목표에서 가르치고자 했던 기능을 학습자가 [성취]했는지 알아볼 수 있는 [검사문항]을 개발하는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 [수업전략 개발] 단계는 교수 프로그램의 최종 목표를 성취하기 위해 이용하고자 하는 전략을 설정하는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 수업전략에는 교수 전 활동, 정보제시, 연습 및 피드백, 시험, 후속 활동 등 [교수전략]이 도출되어야 한다.',m:null},
{t:'딕과 캐리의 ISD에서 [수업자료 개발 및 선정] 단계는 수립된 교수전략에 의거하여 교수와 관련된 모든 형태의 자료를 만드는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 수업자료 개발 및 선정 단계는 수립된 [교수전략]에 의거하여 교수와 관련된 모든 형태의 자료를 만드는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 수업 [형성평가 실행]은 초안 제작 후 프로그램의 질을 개선하는 데 필요한 자료를 수집하는 평가이다.',m:null},
{t:'딕과 캐리의 ISD에서 형성평가의 종류로 [일대일] 평가, [소집단] 평가, [현장] 평가 등이 있다.',m:null},
{t:'딕과 캐리의 ISD에서 [일대일] 평가는 교수설계자와 개별 학습자 간의 직접적인 상호작용을 통해 오류를 규명하여 제거하는 평가이다',m:null},
{t:'딕과 캐리의 ISD에서 일대일 평가는 교수설계자와 [개별] 학습자 간의 [직접적]인 상호작용을 통해 오류를 규명하여 제거하는 평가이다',m:null},
{t:'딕과 캐리의 ISD에서 [소집단] 평가는 학습자가 교사와 상호작용 없이 교수를 활용할 수 있는가를 확인하는 평가이다.',m:null},
{t:'딕과 캐리의 ISD에서 소집단 평가는 학습자가 교사와 [상호작용] 없이 교수를 활용할 수 있는가를 확인하는 평가이다.',m:null},
{t:'딕과 캐리의 ISD에서 [현장] 평가는 궁극적으로 교수 프로그램을 사용하려는 의도한 학습 상황과 유사한 학습 상황에서 활용해보는 평가이다.',m:null},
{t:'딕과 캐리의 ISD에서 현장 평가는 궁극적으로 교수 프로그램을 사용하려는 의도한 학습 상황과 [유사]한 학습 상황에서 활용해보는 평가이다.',m:null},
{t:'딕과 캐리의 ISD에서 [교수 프로그램]의 [수정] 단계는 형성평가를 결과를 바탕으로 교수 프로그램이 가지고 있는 결점을 수정 보완하는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 교수 프로그램의 수정 단계는 [형성평가]를 결과를 바탕으로 교수 프로그램이 가지고 있는 결점을 수정 보완하는 단계이다.',m:null},
{t:'딕과 캐리의 ISD에서 [총괄평가 시행] 단계는 교수 프로그램의 절대적 혹은 상대적 가치를 평가하는 단계로, [형성평가] 완료 후 충분한 수정이 이루어진 후에 실시된다. 이때, 보통 외부 평가자에게 의뢰한다.',m:null},
{t:'딕과 캐리의 ISD에서 총괄평가 시행 단계는 교수 프로그램의 절대적 혹은 상대적 [가치]를 평가하는 단계로, [형성평가] 완료 후 충분한 수정이 이루어진 후에 실시된다. 이때, 보통 [외부 평가자]에게 의뢰한다.',m:null},
{t:'실즈와 글래스고의 ISD는 전체 설계과정을 [순환적]으로 구성하여 딕과 캐리모형의 [선형성]을 극복한 모형이다.',m:null},
{t:'존스와 리치의 래퍼드 [프로토타입] 모형은 많은 시간과 비용에도 기대했던 최종 산출물이 나오지 않았을 때의 문제를 해결하는 [프로토타입] 설계 모형이다.',m:null},
{t:'4C/ID 모형은 복잡한 학습을 구성하는 능력의 [통합]과 연결에 초점을 둔 모형으로, 이때 4C에 해당되는 것은 [학습과제], 지원 정보, 절차적 정보, 부분과제 연습이다.',m:null},
{t:'교육공학은 교수-학습 문제를 해결하기 위해 관련된 [과학적] 지식 또는 일반적으로 [조직화]된 지식을 체계적으로 적용하려는 학문 영역이다.',m:null},
{t:'쉐논과 슈람의 통신과정모형은 [커뮤니케이션]을 지속적인 [순환과정]으로 표현한 모형이다.',m:null},
{t:'쉐논과 슈람의 통신과정모형에서 의사소통은 송신자가 [인코딩](부호화)한 통신을 수신자가 [디코딩](해독)하면서 진행된다.',m:null},
{t:'쉐논과 슈람의 통신과정모형에서 의사소통은 송신자와 수신자의 [경험의 장]이 많이 겹칠수록 활발해진다.',m:null},
{t:'쉐논과 슈람의 통신과정모형에는 의사소통의 방해요소인 [잡음]이 존재하며, 이 문제를 해결하기 위해 각자의 [피드백]이 필요하다.',m:null},
{t:'[교수매체]는 수업내용을 전달하는 데 사용하는 일반적인 매체를 일컫는 말이다.',m:null},
{t:'교수매체는 학습자의 [주의집중]과 [동기유발]에 도움을 주고 [학습효과]를 증진시킨다. 또한 교수매체를 통한 새로운 형태의 교수-학습 [전략]의 구현을 가능하게 한다.',m:null},
{t:'교수매체 선정 시 고려사항으로 [학습자] 특성, [수업 상황], [학습목표]와 내용, 매체의 물리적 속성과 기능 등이 있다.',m:null},
{t:'교수매체 연구의 종류로 [매체비교] 연구, [매체속성] 연구, [매체선호] 연구, [매체활용의 경제성]에 관한 연구가 있다.',m:null},
{t:'[매체비교] 연구는 서로 다른 매체 사이의 효과성을 비교하는 연구로, 결과적 측면에서 비교한다. 하지만, 새로운 매체의 신기성 효과와 교수방법 변인을 통제하지 못한다.',m:null},
{t:'매체비교 연구는 서로 다른 매체 사이의 [효과성]을 비교하는 연구로, 결과적 측면에서 비교한다. 하지만, 새로운 매체의 [신기성] 효과와 [교수방법] 변인을 통제하지 못한다.',m:null},
{t:'[매체속성] 연구는 학습자의 인지과정 또는 학습성취에 영향을 미치는 매체의 속성에 대한 연구이다.',m:null},
{t:'매체속성 연구는 학습자의 [인지과정] 또는 [학습성취]에 영향을 미치는 매체의 속성에 대한 연구이다.',m:null},
{t:'[매체선호] 연구는 학습자가 매체에 따라 가지고 있는 태도에 따라 학업성취도가 달라지는지 확인하는 연구이다.',m:null},
{t:'매체선호 연구는 학습자가 매체에 따라 가지고 있는 [태도]에 따라 [학업성취도]가 달라지는지 확인하는 연구이다.',m:null},
{t:'[매체활용의 경제성]에 관한 연구는 어떠한 조건에서 매체를 활용하는 것이 경제적으로 이익인지 확인하는 연구이다.',m:null},
{t:'매체활용의 경제성에 관한 연구는 어떠한 [조건]에서 매체를 활용하는 것이 경제적으로 이익인지 확인하는 연구이다.',m:null},
{t:'교수매체를 활용한 설계모형, ASSURE 모형은 [학습자 분석] - [목표진술] - [매체와 자료 선정] - [매체와 자료 활용] - [학습자 참여 요구] - [평가와 수정] 순으로 진행된다.',m:null},
{t:'교수매체를 활용한 설계모형, ASSURE 모형은 [학습자 분석] - [목표진술] - 매체와 자료 선정 - [매체와 자료 활용] - [학습자 참여 요구] - 평가와 수정 순으로 진행된다.',m:null},
{t:'ASSURE 모형에서 [학습자 분석] 단계는 일반적 특성, 특별한 출발점 능력, 학습양식 등 학습자의 특성을 분석하는 단계이다.',m:null},
{t:'ASSURE 모형에서 학습자 분석 단계는 [일반적] 특성, 특별한 [출발점] 능력, [학습양식] 등 학습자의 다양한 요인 및 특성을 분석하는 단계이다.',m:null},
{t:'ASSURE 모형의 목표진술 단계에서 A 규칙은 학습자가 누구인지 [대상]을 명확히 잡는 과정이다.',m:null},
{t:'ASSURE 모형의 목표진술 단계에서 B 규칙은 학습자가 성취해야 하는 것을 관찰 가능한 행동으로 진술하여 [종착점 행동]을 설정하는 과정이다.',m:null},
{t:'ASSURE 모형의 목표진술 단계에서 C 규칙은 학습목표에 도달하는 데 사용되는 자원, 시간, 제약 등을 명시하여 [조건]을 설정하는 단계이다.',m:null},
{t:'ASSURE 모형의 목표진술 단계에서 D 규칙은 학습자의 목표 달성 여부를 확인할 수 있는 [판단 기준]을 제시하는 과정이다.',m:null},
{t:'ASSURE 모형에서 매체와 자료 선정 단계의 선정 기준은 교육과정과의 [일치성], [정확성]과 [최신]정도, 학습자의 [흥미]와 [참여]를 유발하는 여부 등이다.',m:null},
{t:'ASSURE 모형에서 매체와 자료의 활용 단계는 [사전 검토하기], [자료 준비하기], [환경 준비하기], [학습자 준비시키기], [학습경험 제공하기]로 구성되어있다. 능동/수동 구분하여 작성하시오.',m:null},
{t:'ASSURE 모형의 매체와 자료의 활용 단계에서 [사전 검토하기] 단계는 수업자료를 미리 확인하여 전체적인 내용을 이해하는 단계이다.',m:null},
{t:'ASSURE 모형의 매체와 자료의 활용 단계에서 [자료 준비하기] 단계는 필요한 모든 자료를 준비하고, 어떤 순서와 방법으로 자료나 매체를 사용할 것인지를 결정하는 단계이다.',m:null},
{t:'ASSURE 모형의 매체와 자료의 활용 단계에서 자료 준비하기 단계는 필요한 모든 자료를 준비하고, 어떤 [순서]와 [방법]으로 자료나 매체를 사용할 것인지를 결정하는 단계이다.',m:null},
{t:'ASSURE 모형의 매체와 자료의 활용 단계에서 [환경 준비하기] 단계는 수업을 하려는 장소가 매체의 사용에 적절한지 파악하고 환경을 준비하는 단계이다.',m:null},
{t:'ASSURE 모형의 매체와 자료의 활용 단계에서 [학습자 준비시키기] 단계는 사전안내를 통해 학습자에게 수업에 대한 기대감과 동기를 부여하는 단계이다.',m:null},
{t:'ASSURE 모형의 매체와 자료의 활용 단계에서 학습자 준비시키기 단계는 [사전안내]를 통해 학습자에게 수업에 대한 [기대감]과 [동기]를 부여하는 단계이다.',m:null},
{t:'ASSURE 모형의 매체와 자료의 활용 단계에서 [학습경험 제공하기] 단계는 매체를 활용하여 수업을 진행하는 단계이다.',m:null},
{t:'ASSURE 모형에서 [학습자 참여 요구] 단계는 학습자의 능동적인 참여를 요구하는 단계로, 학습자에게 학습할 내용을 [연습]할 기회와 그에 따른 [피드백]을 준다.',m:null},
{t:'ASSURE 모형에서 학습자 참여 요구 단계는 학습자의 능동적인 참여를 요구하는 단계로, 학습자에게 학습할 내용을 [연습]할 기회와 그에 따른 [피드백]을 준다.',m:null},
{t:'ASSURE 모형에서 [평가와 수정] 단계는 수업이 끝난 후 수업의 효과와 영향에 대한 평가를 실시하는 단계이다.',m:null},
{t:'ASSURE 모형에서 평가와 수정 단계는 수업이 끝난 후 수업의 [효과]와 [영향]에 대한 평가를 실시하는 단계이다.',m:null},
{t:'디지털 리터리시는 디지털 시대에 필수적으로 요구되는 [정보 이해] 및 [표현 능력]이다.',m:null},
{t:'[디지털 리터리시]는 디지털 시대에 필수적으로 요구되는 정보 이해 및 표현 능력이다.',m:null},
{t:'[코스웨어]는 컴퓨터 기반의 교육용 프로그램이다.',m:null},
{t:'[멀티미디어]는 두 가지 이상의 매체가 결합되어 정보를 제공하는 것이다.',m:null},
{t:'멀티미디어의 주요 원리는 정보처리이론의 작업기억에 위치한 [음운고리], [시공간 스케치판]에 의한 [인지부하] 발생을 근거로 적용되었다.',m:null},
{t:'멀티미디어의 주요 원리는 [응집] 원리, [중복] 요소 제외 원리, [제시 양식]의 원리, [친근화] 원리, 이미지 원리 등이 있다.',m:null},
{t:'m-러닝은 [맥락적]이고, 학습자의 [개별성]을 지원하고, [공유성]이 큰 모바일 러닝과정을 말한다.',m:null},
{t:'[블렌디드] 러닝은 이러닝 교육방식에 전통적인 면대면 교육방식이 갖고 있는 교육적 장점을 결합하여 학습효과를 극대화한 교수방법이다.',m:null},
{t:'[플립] 러닝은 온라인을 활용하여 사전에 개별적으로 교수의 강의를 듣고, 교실에서는 과제를 포함한 다양한 학습활동을 수행하는 교수방법이다.',m:null},
]},
{id:'u12',name:'원격교육·메타버스·매체선정',items:[
{t:'[원격교육]은 다른 시간과 다른 공간에서의 교육형태이거나 같은 시간에 다른 공간에서 행해지는 교육형태이다.',m:null},
{t:'원격교육에서 일반적인 매체 선정 준거는 [학습자] 변인, [교수목표] 변인, 비용 변인, [상호작용성]이다.',m:null},
{t:'베이츠의 ACTIONS 모형의 매체 선정 준거는 [접근성], [비용], [교수]와 [학습], [상호작용]과 [학습자 친화 정도], 조직적 특성, 참신성, 신속성이다.',m:null},
{t:'원격교육과 전통적 교실 수업에서의 교수활동은 [수업 상황]과 [학생 심리], 수업매체에 대한 인식수준 등의 측면에서 차이를 보인다.',m:null},
{t:'[에듀테크]는 교육에 ICT 기술을 적용하여 기존의 교육 서비스를 개선하거나 새로운 서비스를 제공하는 차세대 교육이다.',m:null},
{t:'[메이커스페이스]는 지역사회나 교육 기관에 위치한 일종의 공동 작업 공간이다.',m:null},
{t:'[학습분석 테크놀로지]는 빅데이터들이 자동 분석 시스템에 의해 처리되어 학습과 관련된 진단, 예측, 처방을 내놓는 기술이다.',m:null},
{t:'[적응적 학습 테크놀로지]는 개별 학습자의 학습 수준과 패턴에 따라 적절한 활동 및 내용을 제시하는 기술이다.',m:null},
{t:'[가상현실]은 사람이나 사물에 관련된 실제적 경험을 테크놀로지를 활용하여 가상으로 재현해낸 것이다.',m:null},
{t:'에듀테크 활용에서 교사는 [학습촉진자], [동기부여자], [공동학습자]의 역할을 가져야한다.',m:null},
{t:'[메타버스]는 현실을 넘어 구현된 가상의 세계이다.',m:null},
{t:'[증강현실]은 외부 세계를 증강시키는 유형으로 현실 공간에 가상의 물체를 겹쳐보이게 하여 상호작용하는 기술이다.',m:null},
{t:'증강현실의 교육적 사용 사례로 [디지털교과서]의 실감형 콘텐츠가 있다.',m:null},
{t:'[라이프로깅]은 내부 세계를 증강시키는 유형으로 사람에 대한 일상적인 경험과 정보를 캡쳐, 저장, 공유하는 기술이다.',m:null},
{t:'라이프로깅의 교육적 사용 사례로 [학습]&[신체활동]지원 라이프로깅이 있다.',m:null},
{t:'[거울세계]는 외부 세계를 시뮬레이션한 유형으로 실제 세계를 반영하여 외부 환경 정보를 통합적으로 제공하는 기술이다.',m:null},
{t:'거울세계의 교육적 사용 사례로 [디지털실험실], [가상 교육공간](ZOOM) 등이 있다.',m:null},
{t:'[가상세계]는 내부 세계를 시뮬레이션한 유형으로 디지털 데이터로 구축한 비현실적인 가상세계이다.',m:null},
{t:'가상세계의 교육적 적용 사례로 [제페토] 등이 있다.',m:null},
{t:'증강현실은 실제 보이지 않는 부분을 [시각적]&[입체적]으로 학습하여 효과적인 문제해결을 돕는다.',m:null},
{t:'라이프로깅은 [자기성찰]을 돕고, 학습로그데이터를 바탕으로 맞춤화된 방향으로 학습을 촉진하고 [중도탈락]을 방지한다.',m:null},
{t:'거울세계는 교수-학습의 [공간적]&[물리적] 한계를 극복하였고, 협력도구를 통해 온라인 실시간 수업을 진행할 수 있게 한다.',m:null},
{t:'가상세계는 실제 연출하기 어려운 환경을 가상 시뮬레이션을 통해 [실습]할 수 있게 해주고, 비현실적인 시공간의 체험을 가능하게 한다..',m:null},
{t:'메타버스 활용 수업을 위해 [학습목표]와 [성취기준]을 고려한 체계적인 [수업설계]가 필요하고, 수업에 가장 적합한 플랫폼의 선정과 메타버스 활용에 대해 교사의 [피드백]이 수시로 이루어져야 한다.',m:null},
]},
]},
{id:'evaluation',name:'교육평가',units:[
{id:'u13',name:'교육평가의 이해·측정관·척도',items:[
{t:'교육평가는 교육적 [성과]를 확인하고 [가치]를 판단하는 일이다.',m:null},
{t:'교육평가의 목적과 기능으로 [교육적 성취 확인] 기능, [학습 곤란점 진단] 및 [치료], [분류]&[선발]의 기능, [교육적 개선]의 기능, 학습자 이해의 기능, 올바른 교육정책 수립 등이 있다.',m:null},
{t:'측정관에서 인간 행동 특성을 [불변]한다.',m:null},
{t:'평가관에서 인간 행동 특성은 [변화]한다.',m:null},
{t:'측정관에서는 [신뢰도]가 [타당도]보다 우선순위가 높다.',m:null},
{t:'평가관에서는 [타당도]가 [신뢰도]보다 우선순위가 높다.',m:null},
{t:'측정관과 관련된 교육관은 [선발적] 교육관이다.',m:null},
{t:'평가관과 관련된 교육관은 [발달적] 교육관이다.',m:null},
{t:'평가관에서는 평가도구가 교수과정에서 의도한 목표를 얼마나 잘 나타내고 있는지를 결정하기 위해 [내용타당도]에 관심을 둔다.',m:null},
{t:'총평관에서는 개인과 환경 사이의 상호작용을 분석함에 따라 주로 [구인타당도]를 중시한다.',m:null},
{t:'총평관과 관련된 교육관은 [인본주의적] 교육관이다.',m:null},
{t:'[메타평가]는 평가 자체에 대한 평가이다.',m:null},
{t:'[교육평가 모형]에서는 대부분 [교수프로그램]을 평가하여 [교수목표 도달], [성취여부] 등을 확인한다.',m:null},
{t:'타일러의 [목표성취모형]은 사전에 수립해 놓은 목표를 평가의 준거로 삼아 그 목표가 어느정도 성취되었는지를 판단하는 데 초점을 두는 평가접근 방식이다.',m:null},
{t:'타일러의 목표성취모형은 사전에 수립해 놓은 목표를 평가의 [준거]로 삼아 그 목표가 어느정도 [성취]되었는지를 판단하는 데 초점을 두는 평가접근 방식이다.',m:null},
{t:'타일러의 목표성취모형에서 교육평가는 교육 프로그램이나 수업에 의해 [교육목표]가 어느 정도 달성되었는가를 확인하고 결정하는 과정이다.',m:null},
{t:'타일러의 목표성취모형의 평가절차는 [목표선정] - [목표명시] - [도구제작] - [자료수집] - [가치판단]이다.',m:null},
{t:'타일러의 목표성취모형은 교육과정과 평가의 [논리적 일관성]을 유지해야 함을 강조하고, 목표의 중요성을 강조하여 목표달성 여부의 확인을 통해 교사 자신들의 교육활동에 대한 [책무성]을 가지도록 자극한다.',m:null},
{t:'타일러의 목표성취모형은 교육목표-교육내용-교육평가 간의 논리적인 [일관성]을 갖고 있고, 평가를 통해 [교육목표]의 실현 정도를 명확하게 파악할 수 있다.',m:null},
{t:'타일러의 목표성취모형은 [행동적 용어]로 진술하기 어려운 목표와 목표로 설정하지 않은 교육의 [잠재적] 효과에 대해서는 평가에서 제외한다는 비판점을 보인다.',m:null},
{t:'타일러의 목표성취모형은 수단과 방법을 가리지 않고 [목표성취]라는 결과만 좋으면 그만이라는 [수단의 정당화]라는 비교육적 사태를 초래한다.',m:null},
{t:'프로버스의 [괴리모형]은 교육을 통해 달성해야 할 준거와 실제 수행 사이의 차이인 [괴리]를 분석하는데 중점을 둔 모형이다.',m:null},
{t:'프로버스의 괴리모형은 타일러의 목표성취모형과 유사하나, 타일러는 [목표달성] 정도 측정을 중시하고 프로버스는 목표와 수행 사이의 [불일치] 부분 확인을 중시한다.',m:null},
{t:'헤몬드의 평가모형은 평가절차를 구체화하여 [학교 수준]에 적합한 평가모형이다.',m:null},
{t:'헤몬드는 교육 프로그램을 기술하고 평가변인들을 조직하기 위한 목적으로 3차원 입방체([수업], [기관], [행동])를 고안하여 개념화하였다.',m:null},
{t:'헤몬드의 평가모형의 절차는 [변인 설정] - [방법 결정] - [결과 분석] - [결과 보고]이다.',m:null},
{t:'헤몬드의 평가모형을 통해 교육효과를 체계적이고 명확하게 평가할 수 있으나, 그만큼 평가할 변인이 많고 평가 결과를 [수량화]하기 어렵다는 단점이 존재한다.',m:null},
{t:'스크리븐의 [탈목표모형]에서 교육평가는 프로그램이 의도했던 효과뿐 아니라 [부수적] 효과까지 포함시킨 [실제적] 효과를 평가하는 것이다.',m:null},
{t:'스크리븐의 탈목표모형에서는 평가의 [타당성]을 확보해야하고, 이로 인해 [전문가]로서의 평가자 역할을 강조한다.',m:null},
{t:'스크리븐의 탈목표모형은 사전에 설정된 목표만을 기준으로 한 평가에서 벗어나 교육의 과정 중 발생하는 [잠재적 교육과정]의 결과의 가치의 판단을 강조한다.',m:null},
{t:'스크리븐의 탈목표모형에서 [내재적] 준거는 판단하려고 하는 대상에 내제되어 있는 기준으로, [평가도구]나 방법의 [신뢰도]와 객관도, 평가도구의 제작 등이 포함된다.',m:null},
{t:'스크리븐의 탈목표모형에서 [외재적] 준거는 판단하려는 대상의 밖으로 드러나는 준거(효과)로, 프로그램의 [기능적 속성], 평가 자체의 [효과], 평가에 의한 [변화]등이 포함된다.',m:null},
{t:'스크리븐은 평가에 관한 관심의 범위를 [확대]시켜야 한다는 것을 주장하여 [외재적] 준거를 추가로 제시하였다.',m:null},
{t:'스크리븐의 탈목표모형에서 형성평가는 개발 중이나 진행 중에 있는 수업의 [개선]을 위해 형성적으로 실시하는 평가로, 스크리븐이 처음 도입하였다',m:null},
{t:'스크리븐의 탈목표모형에서 총괄평가는 완성된 수업의 [가치]를 종합적으로 판단하려는 평가이다.',m:null},
{t:'스크리븐의 탈목표모형에서 상대적 가치판단의 유무로 [비교평가]와 [비비교평가]를 구별하였다.',m:null},
{t:'스크리븐의 탈목표모형의 평가절차는 [프로그램 시행과 관찰] - [일차적 효과의 분석] - [이차적 효과의 분석] - [표적집단의 요구 분석] - [사실상의 효과 분석]이다.',m:null},
{t:'탈목표모형의 [프로그램 시행과 관찰] 단계에서는 목표의식 없이 성과를 다각적으로 관찰하고 기록한다.',m:null},
{t:'탈목표모형의 프로그램 시행과 관찰 단계에서는 [목표의식] 없이 [성과]를 다각적으로 관찰하고 기록한다.',m:null},
{t:'탈목표모형의 [일차적 효과의 분석] 단계에서는 의도했던 성과를 분석 및 정리하여 목표를 준거로 그 가치를 판단한다.',m:null},
{t:'탈목표모형의 일차적 효과의 분석 단계에서는 의도했던 성과를 분석 및 정리하여 [목표]를 준거로 그 가치를 판단한다.',m:null},
{t:'탈목표모형의 [이차적 효과의 분석] 단계에서는 목표에 진술되지 않았거나, 의도하지 않았던 부수적인 효과를 확인한다.',m:null},
{t:'탈목표모형의 이차적 효과의 분석 단계에서는 목표에 진술되지 않았거나, [의도]하지 않았던 부수적인 효과를 확인한다.',m:null},
{t:'탈목표모형의 [표적집단의 요구 분석] 단계에서는 프로그램 참가자의 이해관계, 당사자들의 프로그램에 대한 요구나 기대를 폭넓게 조사하여 항목별로 열거한다.',m:null},
{t:'탈목표모형의 표적집단의 요구 분석 단계에서는 프로그램 참가자의 [이해관계], 당사자들의 프로그램에 대한 [요구]나 [기대]를 폭넓게 조사하여 항목별로 열거한다.',m:null},
{t:'탈목표모형의 [사실상의 효과 분석] 단계에서는 이차적 효과 진단 후, 일차적 효과 분석 결과와 연관하여 프로그램의 실체적 효과를 종합적으로 판단한다.',m:null},
{t:'탈목표모형의 사실상의 효과 분석 단계에서는 [이차적 효과] 진단 후, [일차적 효과] 분석 결과와 연관하여 프로그램의 [실체적 효과]를 종합적으로 판단한다.',m:null},
{t:'스크리븐의 탈목표모형은 타일러의 목표성취모형의 [한계]를 넘어 사전에 수립된 교육목표 이외의 교육효과에 대한 평가도 이루어져야 함을 강조한다.',m:null},
{t:'스네이크의 [종합실상모형]은 평가를 통한 교육과정의 개선을 주장하고 교육과정에 대한 기술 및 판단을 강조하는 접근방법이다.',m:null},
{t:'아이즈너는 과학적&기술적 방법의 교육평가가 가진 부작용을 제거하기 위한 [감정]&[비평] 모형을 제시하였다.',m:null},
{t:'아이즈너는 목표중심모형이나 의사결정모형의 경우 교육현상을 [계량화]시킴으로써 개별 현상의 [고유성]을 무시하는 경향이 있다고 기존 평가접근의 한계를 비판하였다.',m:null},
{t:'아이즈너는 실제적 과제를 매개로 한 [참평가]와 질적 접근의 비평적 평가인 [교육비평], 평가자의 전문성이 평가결과의 타당성과 합리성을 확보해 주는 [교육적 심미안]을 제시하였다.',m:null},
{t:'아이즈너는 [실제]적 과제를 매개로 한 참평가와 [질적 접근]의 비평적 평가인 교육비평, 평가자의 [전문성]이 평가결과의 [타당성]과 [합리성]을 확보해 주는 교육적 심미안을 제시하였다.',m:null},
{t:'아이즈너의 교육비평은 평가자의 [전문성]에 전적으로 의존하는 만큼 다양한 평가 상황에서 평가의 [주관성]이나 편파성 등의 문제가 제기될 수 있다.',m:null},
{t:'스티플빔의 [의사결정모형]에서 교육평가는 [의사결정자]에게 필요한 정보를 [제공]하여 [의사결정]을 조력하는 과정이다.',m:null},
{t:'스티플빔의 CIPP 의사결정모형에는 의사결정자가 진행하는 [의사결정 유형]과 의사결정을 촉진하는 평가자의 [평가 유형]과 그와 연결되는 [평가 활동]이 존재한다.',m:null},
{t:'의사결정모형의 의사결정 유형에는 [계획]단계, [구조화]단계, [실행]단계, [결과]단계가 있다.',m:null},
{t:'의사결정모형의 평가 유형에는 [맥락]평가, [투입]평가, [과정]평가, [산출]평가가 있다.',m:null},
{t:'의사결정모형의 계획단계는 [맥락]평가와 연결된다.',m:null},
{t:'의사결정모형의 [계획]단계는 맥락평가와 연결된다.',m:null},
{t:'의사결정모형의 구조화단계는 [투입]평가와 연결된다.',m:null},
{t:'의사결정모형의 [구조화]단계는 투입평가와 연결된다.',m:null},
{t:'의사결정모형의 실행단계는 [과정]평가와 연결된다.',m:null},
{t:'의사결정모형의 [실행]단계는 과정평가와 연결된다.',m:null},
{t:'의사결정모형의 결과단계는 [산출]평가와 연결된다.',m:null},
{t:'의사결정모형의 [결과]단계는 산출평가와 연결된다.',m:null},
{t:'의사결정모형의 맥락평가 활동에서는 구체적인 [목표수립]의 배경과 [상황] 및 [환경적 여건]을 파악한다.',m:null},
{t:'의사결정모형의 투입평가 활동에서는 현재 어떠한 [산물]이 투입되고 있는지, 앞으로 어떠한 [산물]이 투입되어야 하는가를 파악한다.',m:null},
{t:'의사결정모형의 과정평가 활동에서는 구조화 단계에서 수립한 [전략]이 실행되는 과정에서 고려해야 할 점을 파악한다.',m:null},
{t:'의사결정모형의 산출평가 활동에서는 교육 프로그램을 계속할 것인지, 변경할 것인지, 그만둘 것인지를 [가치판단]하는데 필요한 정보를 제공한다.',m:null},
{t:'스티플핌의 CIPP를 비롯한 의사결정모형은 [지속적]인 평가를 통해 피드백을 제공하고 [의사결정]을 위한 유용한 정보를 제공하여 프로그램 개선에 직접적으로 기여할 수 있다.',m:null},
{t:'스티플핌의 CIPP를 비롯한 의사결정모형은 평가자의 정보제공을 위한 기능만을 강조하고 의사결정자에게 [가치판단]을 위임함으로써 평가자의 역할이 [경시]될 수 있다.',m:null},
{t:'울프의 [재판평가모형]은 평가진행을 재판과정처럼 모형화하여 평가의 과정을 설명한 모형으로 공개적, 체계적, 객관적 증거에 입각하여 변론하기에 양측의 [입장]을 충분히 알 수 있다.',m:null},
{t:'구바와 링컨의 [자연주의적 평가]는 평가의 과정에 관련된 개인 또는 집단들의 서로 다른 [이해관계]에 따라 타협하며 보다 나은 평가행위를 구성한다.',m:null},
{t:'[소비자중심 평가]는 교육을 위하여 사용되는 모든 것을 교육상품으로 보고, 나아가 교육의 행위도 서비스로 간주하여 교육프로그램의 대상인 소비자가 무엇을 원하고 필요로 하는가에 관심을 두는 평가모형이다.',m:null},
{t:'교육평가는 평가준거에 따라 [규준참조평가], [준거참고평가], [능력참조평가], [성장참조평가]로 나뉜다.',m:null},
{t:'[규준참조평가]는 학습자의 평가 결과를 그가 속한 비교집단에 비추어 상대적인 위치나 서열을 밝히는 평가방법이다.',m:null},
{t:'규준참조평가는 학습자의 평가 결과를 그가 속한 비교집단에 비추어 [상대적]인 위치나 서열을 밝히는 평가방법이다.',m:null},
{t:'규준참조평가는 [개인차] 변별이 용이하고 [선발적 교육관]에 근거한 [외재적 동기] 유발이 용이하다.',m:null},
{t:'규준참조평가는 검사의 타당도를 간과하어 [학습목표]의 [도달정도]와 [여부] 판단이 어렵고, [과다한 경쟁심] 유발로 인한 [정의적] 행동 특성에 부정적 영향을 미친다.',m:null},
{t:'[준거참조평가]는 숙달 수준인 준거에 비추어 학습자의 점수를 비교하여 학습자 수행 수준을 해석하고 그에 따른 정보를 제공하는 평가이다.',m:null},
{t:'준거참조평가는 [숙달] 수준인 준거에 비추어 학습자의 점수를 비교하여 [학습자 수행] 수준을 해석하고 그에 따른 정보를 제공하는 평가이다.',m:null},
{t:'준거참조평가는 검사의 [타당도]를 중시하여 학습목표의 도달정도와 여부의 정확한 판단이 가능하고, 학습 실패의 원인을 [교수자]와 [교수 환경]에서 찾아 개선하고자 노력한다. 또한 [발달적 교육관]에 근거하여 [개인차]를 줄이고자 노력하여 경쟁자극이 없다.',m:null},
{t:'준거참조평가는 [개인차] 변별이 곤란하고, 점수가 [정규분포]를 가정하지 않아 [선발]에 활용이 곤란하고, [경쟁]을 통한 [외재적 동기] 유발이 결핍된다.',m:null},
{t:'[능력참조평가]는 학생이 지니고 있는 능력에 비추어 얼마나 최선을 다하였느냐에 초점을 두는 평가이다.',m:null},
{t:'능력참조평가는 학생이 지니고 있는 능력에 비추어 얼마나 [최선]을 다하였느냐에 초점을 두는 평가이다.',m:null},
{t:'능력참조평가는 능력을 얼마나 발휘했는가에 관심을 두어 [학업성취도] 검사에서 적용함이 바람직하다.',m:null},
{t:'학생의 능력에 대한 정확한 [정보]가 없을 경우 능력참조평가의 활용 및 개발이 어렵고, 해당 능력에 [제한]하여 학습자의 수행을 해석하는 한계가 존재한다.',m:null},
{t:'[성장참조평가]는 교육과정을 통해 얼마나 성장하였느냐에 관심을 두는 평가이다.',m:null},
{t:'성장참조평가는 학생들에게 [학업 증진]의 기회 부여와 [개인화]를 강조한다.',m:null},
{t:'능력지향평가와 성장지향평가는 [행정적 기능]이 강조되는 [고부담검사]와 같은 평가환경에서는 평가겨로가에 대한 [공정성] 문제가 제기되어 적용하기 어렵다.',m:null},
{t:'[흥미]는 어떤 대상에 특별한 관심을 갖고자 주의를 하게 하는 느낌으로 대표적인 검사로 [직업흥미] 검사가 있다.',m:null},
{t:'[자아개념]은 자기 자신에 관한 각 개인의 지각으로 [자신감]과 [자아존중감]으로 구성되어 있다.',m:null},
{t:'[성격]은 지속적이고 일관되게 나타나는 자신만의 독특한 사고, 감정, 행동유형으로 대표적인 검사로 [MBTI] 검사가 있다.',m:null},
{t:'정의적 영역에 대한 평가방법으로 [질문지법], 관찰법, 면접법, 투사법, [평정법]이 있다.',m:null},
{t:'질문지법은 어떤 문제에 대해 작성된 일련의 [질문]에 대해 피험자가 스스로 대답을 기술하도록 하는 방식이다.',m:null},
{t:'관찰법은 교사의 관찰에 의해 정의적 특성을 추리하여 평가하는 방식으로 [계획된 관찰]을 중시한다.',m:null},
{t:'관찰법은 질문지법이나 평정법에 의해 측정할 수 없는 [행동 변화]에 대한 자료를 얻을 수 있고, [허위반응] 및 [중립화] 경향을 어느정도 방지하지만, [점수화]하는데 제한이 있다.',m:null},
{t:'평정법은 측정하고자 하는 특성을 특정 기준에 따라 판단하는 방법으로 [리커트 척도]와 [의미변별척도]가 있다.',m:null},
{t:'리커트 척도는 [긍정]&[부정]이 구분되는 특성을 양 극단에 배치하여 [수량화]하여 측정한다.',m:null},
{t:'리커트 척도는 [측정도구] 작성과 [자료분석]이 용이하나 응답의 [중립화] 경향이 있다.',m:null},
{t:'의미변별척도는 개념의 의미를 양극의 뜻으로 갖는 대비되는 [형용사]군으로 만들어 의미를 측정하는 방법으로, 일반적으로 태도, 지각, 가치관을 측정할 때 사용된다.',m:null},
]},
{id:'u14',name:'평가유형(진단·형성·총괄)·채점오류',items:[
{t:'교육평가는 평가기능 및 시점에 따라 [진단평가], [형성평가], [총괄평가]로 나뉜다.',m:null},
{t:'[진단평가]는 교수-학습이 시작되기 전 학습자의 능력 및 특성을 파악하고 그 정보를 교육목표 설정, 교수-학습활동 계획, 평가계획 수립 등에 기초를 삼는 활동이다.',m:null},
{t:'진단평가의 목적은 학습자에게 적절한 [수업전략]을 [투입]하기 위함이다.',m:null},
{t:'진단평가에서 확인해야 하는 학습자의 특성으로 [선수학습능력]과 [사전학습능력] 등이 있다.',m:null},
{t:'진단평가에는 다양한 절차와 방법이 존재하고, 전 학년도의 [성적표]나 학교생활기록부, 교사에게 해당 학생의 정보제공을 요청하여 얻은 정보 등을 활용하여 제작한다.',m:null},
{t:'[형성평가]는 수업이 진행되는 도중에 실시하는 평가로 현재 진행중인 학습내용에 대한 학습자의 이해 정도나 기능 수준을 확인하고 이를 극대화하기 위해 실시하는 평가이다.',m:null},
{t:'형성평가의 결과는 학습자와 교사에게 [피드백]되어 학습을 촉진하고 수업을 [개선]하는 기초 정보가 된다.',m:null},
{t:'형성평가의 목적은 학습이 이루어지는 과정에서 교수-학습을 [개선]하는 것이다.',m:null},
{t:'형성평가는 학습의 개별화를 추구하고, [피드백]의 역할을 수행한다. 또한 [학습곤란]을 진단하고 칭찬 및 정보제공을 통한 [학습동기]를 유발한다.',m:null},
{t:'형성평가의 주체 및 검사도구의 제작의 중심은 [교사]이다.',m:null},
{t:'형성평가는 지금까지 진행된 교육목표의 [성취여부]를 파악하기 위해 최저 준거에 준하는 난이도로 제작되어야하고, [준거참조평가]가 적합하다.',m:null},
{t:'형성평가의 평가도구 제작 시 학습단위 중 중요한 모든 요소와 [이원분류표]에 의한 행동소의 각 단계를 모두 포함시켜야 한다.',m:null},
{t:'[총괄평가]는 교수-학습과정이 종료된 후, 교수목표의 달성 여부와 정도를 종합적으로 판정하는 평가이다.',m:null},
{t:'총괄평가의 목적은 성취수준의 [도달 여부]를 판정하여 서열을 파악하거나, [자격증] 취득 또는 교사에게 [책무성]을 부여하기 위해 진행된다.',m:null},
{t:'총괄평가는 [규준참조평가]와 [준거참조평가]를 혼용한다.',m:null},
{t:'총괄평가의 결과는 다음 교육을 위한 [진단평가]로 이용될 수 있다.',m:null},
{t:'총괄평가의 검사도구는 교사보다는 [평가전문가]에 의해 제작된 검사도구를 사용한다. 교사는 [수업내용]에 근거한 검사도구를 제작할 수 있기에 총괄평가의 [방향성] 손실 위험이 있다.',m:null},
{t:'교육평가는 평가방법에 따라 [양적 평가]와 [질적 평가]로 나뉜다.',m:null},
{t:'양적 평가는 검사와 측정에 의해 [수량화]된 자료를 수집하는 평가이다.',m:null},
{t:'양적 평가는 [신뢰성]을 보장받을 수 있으나 평가대상을 전체적으로 조망하지 못하여 [심층적]으로 평가하지 못한다.',m:null},
{t:'질적 평가는 관찰이나 기술, 면담, 실기평가 등 다양한 유형의 평가를 통해 수량화되지 않은 [다양한] 형태의 자료를 얻는 평가이다.',m:null},
{t:'질적 평가는 평가자의 [주관적] 판단, 즉 [전문성]에 의존하고, 이는 평가결과를 [일반화]하는데 제한점을 둔다.',m:null},
{t:'질적 평가는 학습자 개인과 사회에 모두 영향을 주는 시험인 [고부담시험]과 맞지 않는다.',m:null},
{t:'교육평가는 상호작용 여부에 따라 [정적 평가]와 [역동적 평가]로 나뉜다.',m:null},
{t:'정적 평가는 상호작용 및 [피드백]이 없는 평가로, [피드백]을 제공하는 것은 측정오차를 유발할 수 있으므로 지양해야 할 일로 간주한다.',m:null},
{t:'역동적 평가는 학생의 [잠재능력]을 평가하고 학습을 [유발]하기 위해 평가과정에서 [상호작용]을 실시하는 평가이다.',m:null},
{t:'정적 평가는 [산출물]을 강조하고, 역동적 평가는 학습 및 변화하는 [심리적] 과정의 정량화를 강조한다.',m:null},
{t:'[수행평가]는 교사가 학습자들의 학습과제 수행과정 및 결과를 직접 관찰하고, 그 관찰 결과를 전문적으로 판단하는 평가방식이다.',m:null},
{t:'수행평가는 교사가 학습자들의 학습과제 [수행과정] 및 [결과]를 직접 [관찰]하고, 그 [관찰] 결과를 전문적으로 판단하는 평가방식이다.',m:null},
{t:'수행평가는 [대안적] 평가의 한 사례이고, [직접적] 평가와 [실기중심] 평가는 수행평가의 특성 중 하나이다.',m:null},
{t:'수행평가는 [지필중심] 평가가 인간의 능력을 [총체적]으로 평가하지 못한다는 비판에서 제안되었ㅇ다.',m:null},
{t:'수행평가는 [실제적] 수행의 [종합적] 판단으로 학습결과 뿐만아니라 학습과정에서의 [교수활동]과 [학습활동]을 모두 중시한다.',m:null},
{t:'수행평가를 통해 학생의 개별 학습과정을 [진단]하고 이를 기반으로 학습활동을 [촉진]할 수 있다.',m:null},
{t:'수행평가 과제 선정 시 일반적인 고려사항으로 [수업목표]와의 [일치성], 과제의 [현실성], 과제의 [다차원성], 과제의 [주제통합성]이 있다.',m:null},
{t:'수행평가 채점 시 평가기준을 하나로 통합하여 종합적인 판단을 내리는 [총체적] 채점보다는 구체적 요소들 하나하나에 대한 평가를 중심으로 채점이 이루어지는 [분석적] 채점이 바람직하다.',m:null},
{t:'수행평가 채점 시 다른 교사와 협력하여 [공동채점]을 진행하면, 채점의 [타당성], 공정성, [신뢰성]을 높일 수 있다.',m:null},
{t:'수행평가는 종합적이고 전인적인 평가가 가능하고 [고등사고능력] 측정에 적합한 평가이다.',m:null},
{t:'[포트폴리오]는 학생 개개인의 목표와 관심 정도를 파악할 수 있는 비교적 장기간에 걸쳐 수행한 과제의 모음집이다.',m:null},
{t:'포트폴리오는 학생이 자신의 [강점]과 [약점]을 정확하게 파악할 수 있게하고, 학습활동에 [능동적]으로 참여하게 하고, 자신의 학습에 [책무성]을 갖게 한다.',m:null},
{t:'[루브릭]은 학생들의 과제를 평가하는데 필요한 평가안내서이다.',m:null},
{t:'루브릭은 [과제]나 학습활동과 관련된 중요한 영역이나 특성, 각 영역을 평정하는 [평가척도], 각 수준에 대한 구체적인 지표를 포함해야 한다.',m:null},
{t:'루브릭은 평가의 적용 방식에 따라 [총체적] 루브릭과 [분석적] 루브릭으로 나뉜다.',m:null},
{t:'총체적 루브릭은 [단순한] 수행을 판단할 때 사용하지만, 평가 후 루브릭을 통한 [구체적]인 피드백 제공이 어렵다.',m:null},
{t:'분석적 루브릭은 [복잡한] 수행을 판단할 때 사용하고, 각 특성마다 [독립]된 점수를 부여하기에 수행의 [강점]과 [약점]에 대한 피드백을 줄 때 유용하다.',m:null},
{t:'교사는 루브릭을 통해 학생의 수행을 보다 [객관적]으로 평가하고 그 결과를 정확히 [의사소통]할 수 있다.',m:null},
{t:'학생은 루브릭을 통해 자신의 수행을 스스로 평가함으로써 보다 [자기주도적]인 학습자가 될 수 있다.',m:null},
{t:'[과정중심평가]는 학습자의 과정에 초점을 맞추어 형성적 평가 목적을 강조하는 평가이다.',m:null},
{t:'과정중심평가는 [준거참조평가]와 [수행평가], [형성평가]의 특징을 모두 갖는다.',m:null},
{t:'피드백은 학생의 [평가결과]를 토대로 성적이나 정&오답 여부를 알려주어 학생의 [오개념]을 수정하는 역할 혹은 교사의 교육활동을 [반성]하고 [개선]하기 위한 정보 추출 활동을 일컫는 말이다.',m:null},
{t:'교사 주도의 피드백의 종류로는 [평가결과표] 제공, [모범답안] 또는 문제풀이 제시, 집단 대상 공통 피드백, 개별 [면답] 피드백 등이 있다.',m:null},
{t:'학생 주도의 피드백의 종류로는 [동료평가]를 통한 평가결과지 또는 의견, [자기평가]를 통한 자기점검표 혹은 자기성찰기록 등이 있다.',m:null},
{t:'피드백은 적절한 [시기]에 제공되어야하고, 학생들의 [학습동기[를 촉진할 수 있어야 한다. 또한 개인별 특성을 고려한 [맞춤형] 피드백으로 제공되어야한다.',m:null},
{t:'피드백을 통해 학생의 실제 평가 [성취수준]과 도달해야 할 [학습목표] 간의 차이를 보여주어 학생의 [성장]과 학습에 도움이 되어야 한다.',m:null},
{t:'[자기평가]는 특정 주제나 교수-학습 영역에 대하여 학습자들이 스스로 자신을 평가하는 방법이다.',m:null},
{t:'자기평가는 [자기주도적] 학습, [학습자 중심] 교육과정에서 큰 역할을 한다.',m:null},
{t:'자기평가에서 학습자들은 [평가주체자]가 되고 직접적으로 평가에 참여하여 [능동적]이고 [통제적]인 학습태도를 기를 수 있다. 이는 [자기주도적] 학습능력 향상으로 연결된다.',m:null},
{t:'자기평가를 통해 학습자는 [메타인지] 능력을 향상시킬 수 있고, 학습자의 [반성적 고찰]을 통해 학생의 긍정적 [자아개념] 형성과 피드백 효과를 얻을 수 있다.',m:null},
{t:'객관적으로 자신을 보지 못하는 학생들은 자신을 [과소평가]하거나 [과대평가]할 수 있어 평가의 [객관도]가 떨어질 수 있다',m:null},
{t:'자기평가는 학습자의 [학습의욕]을 고취시키는 도구, 평가의 보조 자료로 생각하고 활용하는 것이 바람직하다.',m:null},
{t:'[동료평가]는 동표 학습자를 서로 평가하는 방법이다.',m:null},
{t:'동료평가는 학습자인 동시에 평가자로서 서로 [전략]을 습득하도록 돕고 동시에 상황에 맞고 의미 있는 학습을 할 수 있다.',m:null},
{t:'동료평가는 평가 주체에 따라 [짝 평가], 전체 평가, 모둠 간 평가, 모둠 내 기여도 평가로 나뉜다.',m:null},
{t:'동료평가를 통해 학생들은 상호작용을 통한 [문제해결력] 및 긍정적 [학습태도]를 함양한다. 또한 [메타인지] 전략을 익히고 [자기평가]를 도울 수 있다.',m:null},
{t:'동료평가는 자신과 동일한 입장의 동료들에게 피드백을 받는 활동으로 피드백에 대한 [불안감]을 감소시킬 수 있다.',m:null},
{t:'동료평가는 평가의 [객관성]이 결여되고, 평가전문성이 부족하여 [객관도]와 [신뢰도]가 낮다.',m:null},
{t:'[성취평가제]는 국가 교육과정에 근거하여 개발된 교과목을 성취기준, 성취수준에 따라 학생의 학업 성취수준을 평가하는 방법으로 [준거참조평가]가 사용된다.',m:null},
{t:'[컴퓨터 보조검사]는 컴퓨터가 평가를 위한 교사의 업무를 보조하는 역할을 수행하는 경우의 평가유형이다.',m:null},
{t:'[컴퓨터이용 검사]는 컴퓨터를 사용하여 검사를 치루는 경우의 평가유형이다.',m:null},
{t:'컴퓨터이용 검사는 시험이 끝남과 동시에 피험자에게 [점수]를 제공할 수 있다.',m:null},
{t:'[컴퓨터이용 개별적응검사]는 컴퓨터를 활용하여 학생의 수준에 따라 치르는 검사의 난이도가 달라져 각 개별 학생의 능력 수준에 맞는 문제로만 구성된 검사이다',m:null},
{t:'컴퓨터이용 개별적응검사는 컴퓨터를 활용하여 학생의 수준에 따라 치르는 검사의 [난이도]가 달라져 각 개별 학생의 능력 수준에 맞는 문제로만 구성된 검사이다',m:null},
{t:'컴퓨터이용 개별적응검사(CAT)는 학생의 수준을 세밀하게 측정하고, 측정의 [정확성]과 [효율성]이 높다',m:null},
{t:'[타당도]는 측정도구가 측정하려고 의도한 것을 얼마나 충실하게 측정하고 있는가의 정도로, 검사도구 목적의 적합성을 나타낸다.',m:null},
{t:'타당도는 측정도구가 측정하려고 의도한 것을 얼마나 [충실]하게 측정하고 있는가의 정도로, 검사도구 [목적의 적합성]을 나타낸다.',m:null},
{t:'타당도의 종류는 크게 [내용타당도], 준거타당도([공인타당도] + [예언타당도]), [구인타당도], [결과타당도]가 있다.',m:null},
{t:'[내용타당도]는 문항표집의 적절성으로 한 검사를 구성하는 문항들이 전체의 내용영역과 행동영역을 얼마나 잘 대표하고 있는가의 정도이다.',m:null},
{t:'내용타당도는 문항표집의 [적절성]으로 한 검사를 구성하는 문항들이 전체의 [내용영역]과 [행동영역]을 얼마나 잘 [대표]하고 있는가의 정도이다.',m:null},
{t:'내용타당도를 높이기 위해서는 교육목표를 [내용영역]과 [행동영역]으로 이분화시켜 표현한 [이원분류표]의 작성이 필수적이다.',m:null},
{t:'[공인타당도]는 검사도구에서 구한 점수와 이미 타당성을 입증받은 다른 검사도구에서 구한 점수 간 상관을 토대로 검사도구의 타당성을 평가하는 방법이다.',m:null},
{t:'공인타당도는 [기존 검사도구 대체] 시에 사용한다.',m:null},
{t:'[예언타당도]는 검사도구에 구한 점수와 미래에 피험자에게 나타날 행동 특성을 수량화한 준거점수 간의 상관을 토대로 검사도구의 타당성을 평가하는 방법이다.',m:null},
{t:'예언타당도는 [선발시험]에 적절하게 쓰인다.',m:null},
{t:'[구인타당도]는 특정 검사도구가 측정하려는 심리적 특성에 대해 조작적 정의를 내리고, 그 정의를 기준으로 특정 검사도구가 측정하고자 하는 심리적 특성인 구인을 얼마나 제대로 측정하고 있는지를 분석함으로써 검사도구의 타당성을 평가하는 방법이다.',m:null},
{t:'구인타당도는 특정 검사도구가 측정하려는 [심리적] 특성에 대해 [조작적 정의]를 내리고, 그 정의를 기준으로 특정 검사도구가 측정하고자 하는 심리적 특성인 [구인]을 얼마나 제대로 측정하고 있는지를 분석함으로써 검사도구의 타당성을 평가하는 방법이다.',m:null},
{t:'구인타당도는 [검사도구 개발] 시에 사용한다.',m:null},
{t:'[결과타당도]는 검사결과가 검사의 목적에 얼마나 부합하는가, 의도한 결과를 얼마나 달성하였고 의도하지 않은 어떤 결과가 나왔는지에 대한 검증이다.',m:null},
{t:'[신뢰도]는 대상을 얼마나 정확하게 측정하는가의 정도로, 검사도구 측정의 일관성이다.',m:null},
{t:'신뢰도는 대상을 얼마나 [정확]하게 측정하는가의 정도로, 검사도구 [측정의 일관성]이다.',m:null},
{t:'신뢰도 추정방법은 2회 반복검사를 통한 신뢰도 추정법인 [재검사 신뢰도], [동형검사 신뢰도]와 1회 검사를 통한 신뢰도 추정법인 [반분 신뢰도]와 [문항내적 합치도]로 나뉜다.',m:null},
{t:'[재검사 신뢰도]는 한 검사를 한 집단의 대상으로 일정한 시간 간격을 두고 두 번 실시한 후, 점수 간 상관계수를 측정하는 방법이다.',m:null},
{t:'재검사 신뢰도는 [추정]이 간단하나, [실시 간격]에 따라 신뢰도 추정값이 달라진다.',m:null},
{t:'[동형검사 신뢰도]는 유사한 두 개의 검사를 한 집단을 대상으로 각각 다른 시기에 실시한 후, 점수 간 상관계수를 측정하는 방법이다.',m:null},
{t:'동형검사 신뢰도는 연습효과, 기억효과 등의 영향을 [최소화]할 수 있지만, 동질적인 동형검사를 만드는 과정이 어렵다는 단점이 있다.',m:null},
{t:'[반분 신뢰도]는 한 검사를 한 집단을 대상으로 실시한 후, 그 검사를 두 부분으로 나누어 독립된 두 개의 검사로 간주하고 이들의 상관계수를 계산한 후, [스피어만-브라운] 공식을 이용하여 교정 후 신뢰도를 산출하는 방법이다.',m:null},
{t:'반분 신뢰도는 두 번 검사를 실시하지 않고 신뢰도를 추정할 수 있으나, [반분 방식]에 따라 신뢰도 계수가 달라진다.',m:null},
{t:'[문항내적 합치도]는 문항 하나하나를 하나의 검사로 감주하여 문항들 간의 슈상성 혹은 측정의 일치성을 추정하는 방법이다.',m:null},
{t:'높은 [신뢰도]는 [타당도]의 선행 조건으로, [신뢰도]가 낮으면 [타당도]는 절대 기대할 수 없다.',m:null},
{t:'[객관도]는 채점자의 주관적인 편견을 얼마나 배제하였는가의 문제로, [채점자 내 신뢰도]와 [채점자 간 신뢰도]로 나뉜다.',m:null},
{t:'채점자 내 신뢰도는 한 채점자가 모든 측정대상에 대해 [계속적]으로 [일관성] 있게 측정하는 정도이다.',m:null},
{t:'채점자 간 신뢰도는 채점결과가 채점자들 사이에서 얼마나 [유사]한가의 정도이다',m:null},
{t:'객관도 부족의 원인으로 [측정도구] 자체의 문제와 채점자의 [소양] 부족이 있다.',m:null},
{t:'명확한 평가의 [기준]과 동료교사들의 [공동 채점] 후 [결과 종합]은 객관도를 높이는데 도움이 된다.',m:null},
{t:'[평정의 오류]는 평가자의 주관이 개이밯여 발생하는 평가오류이다.',m:null},
{t:'평정의 오류에는 [집중경향]의 오류, [인상]의 오류, [논리적] 오류, 표준의 오류, 근접의 오류가 있다.',m:null},
{t:'집중경향의 오류는 평가 시 [중간 점수]에 채점결과가 집중되는 경향성으로, 높은 점수와 낮은 점수 부여의 부담으로 발생하여 고점과 저점간의 [변별력]이 떨어진다.',m:null},
{t:'인상의 오류(후광효과)는 평가 시 수행 결과물 자체보다 학생이 가진 [배경] 정보에 영향을 받아 잘못된 판단을 하는 경우이다.',m:null},
{t:'표준의 오류는 각 채점자가 평가의 [기준]을 달리 둠으로써 발생하는 오류이다.',m:null},
{t:'근접의 오류는 여러 속성을 근접하여 [연속적]으로 평정하는 경우 발생하는 오류로, 이전의 평가가 이후의 평가에 영향을 미치는 현상이다.',m:null},
]},
]},
{id:'admin',name:'교육행정',units:[
{id:'u15',name:'교육행정 이론·분산적 리더십',items:[
{t:'교육행정의 [공권설](국가통치권론)은 교육행정을 총체적인 국가행정의 관점에서 파악하려는 견해로 [교육에 관한 행정]이라고도 한다.',m:null},
{t:'교육행정의 [조건정비론]은 교육행정을 교육목표를 효율적으로 달성하기 위해 필요한 인적, 물적 모든 조건을 정비, 확립하는 수단이나 봉사적 활동이라 보는 견해로 [교육을 위한 행정]이라고도 한다.',m:null},
{t:'교육행정의 조건정비론은 교육행정을 [교육목표]를 효율적으로 달성하기 위해 필요한 인적, 물적 모든 조건을 정비, 확립하는 수단이나 봉사적 활동이라 보는 견해로 [교육을 위한 행정]이라고도 한다.',m:null},
{t:'교육행정의 원리로 [민주성]의 원리, 효율성의 원리, 합법성의 원리, 기회균등의 원리 등이 있다.',m:null},
{t:'교육행정학의 과학적 관리론은 조직의 [능률]은 조직을 과학적으로 관리해야 가능한다는 인식이 확산되면서 시작되었다.',m:null},
{t:'과학적 관리론의 교육적 적용법 중 하나는 [분업화]로 교원은 학생을 가르치는데 전념하고, 별도의 행정가가 학교행정을 책임져야 한다. 또한 가능한 모든 시간에 교육시설을 활용하여 낭비를 최대한 제거한다.',m:null},
{t:'과학적 관리론이 교육에 적용된 예로 [표준화]된 교육과정의 개발과 운영, [수업목표]의 명세적 설정과 측정, 교과 및 업무 조직의 [분업화], 학교회계의 발전을 통한 [낭비]의 제거 등이 있다.',m:null},
{t:'[관료제]는 특정한 조직 구조나 현대 정부 그 자체를 의미하며, 조직이나 정부의 병폐를 지적하는 용어로도 사용된다.',m:null},
{t:'관료제의 특징으로 [분업]과 [전문화], [몰인정성](비정성), [권위]의 [위계], 규정과 규칙, 경력 [지향성]이 있다.',m:null},
{t:'관료제의 특징 중 분업과 전문화는 조직의 [목적 달성]을 위한 과업이 구성원의 [책무]로서 공식적으로 배분된다는 뜻이다.',m:null},
{t:'분업과 전문화는 조직의 [전문성] 향상을 가져오지만, 구성원의 [권태감]이 누적되어 지루함을 일으킨다.',m:null},
{t:'관료제의 특징 중 몰인정성(비정성)은 조직의 분위기가 [감정]에 지배되지 않고 엄정한 [공적] 정신에 의해 규제된다는 뜻이다.',m:null},
{t:'몰인정성(비정성)은 조직의 [합리성]을 증진시키지만, 구성원의 [사기]가 저하되고, 인간존중 감소를 일으킨다.',m:null},
{t:'관료제의 특징 중 권위의 위계는 [수직적]인 부서배치와 하위 부서는 상위 부서의 통제와 감독을 받는 것을 뜻한다. [수평적]인 특징이 큰 학교조직과는 차이가 있다.',m:null},
{t:'권위의 위계는 구성원의 [순응]과 조직의 조정을 원활하게 하지만, 하위 부서와 상위 부서 간의 [의사소통]의 장애와 단절을 일으킬 수 있다.',m:null},
{t:'관료제의 특징 중 규정과 규칙은 의도적으로 확립된 규정과 규칙체계를 통해 활동이 [일관성] 있게 규제되는 것을 뜻한다.',m:null},
{t:'규정과 규칙은 조직의 [계속성]과 [통일성]을 확보하지만, 절차 준수에 얽매여 조직의 [경직]과 목표 [전도]를 일으킨다.',m:null},
{t:'관료제의 특징 중 경력 지향성은 연공(근무기간)이나 실적 등을 조합한 [승진제도]를 갖추고 있으며, 경력이 많은 자가 우대되는 특징을 말한다.',m:null},
{t:'경력 지향성은 구성원의 [동기]를 유발하기 위한 유인책으로 적절하나, 승진자 결정에서 연공과 실적의 갈등을 초래한다.',m:null},
{t:'홀의 학교의 관료적 구조에서 전문적 패턴이 [높]고, 관료직 패턴이 [낮]은 [전문형] 구조는 실질적인 의사결정이 전문직원들에게 위임되어 있는 구조로 학교에 해당되는 구조이다.',m:null},
{t:'교육행정학의 [인간관계론]은 과학적 관리론의 기계적 효율성 상조에 무시당한 인간의 사회적, 정서적, 심리적 측면에 대한 대우가 필요하다는 인식이 확산되면서 시작되었다.',m:null},
{t:'호손실험은 조직 내의 [인간적] 요인과 생산성의 상관관계를 보여준다.',m:null},
{t:'인간관계론은 교육행정에 [민주적]인 원리를 제시하여 교육행정의 [민주화]와 발전에 크게 공헌하였다.',m:null},
{t:'[민주적 경영]이란 장학, 예산 배정, 교육과정 등 행정의 모든 영역에 교사의 적극적인 참여가 보장되어야 한다는 것을 의미한다.',m:null},
{t:'교육행정학의 [행동과학론]은 인간의 행동과 조직의 관계를 정립하여 행정의 이론화를 일으켰다.',m:null},
{t:'교육행정학의 [체제이론]은 학교사회를 구성하는 요소들과 그것의 구조와 기능을 파악하여 체계적으로 이해하려는 접근을 뜻한다.',m:null},
{t:'교육행정학의 [사회과정이론]은 사회체제를 개인들의 집합으로 이루어진 사회적 단위로 보고 사회체제 속에서 인간이 어떠한 행동을 보이는가에 대한 연구를 뜻한다.',m:null},
{t:'교육행정학의 사회과정이론은 [사회체제]를 개인들의 집합으로 이루어진 사회적 단위로 보고 [사회체제] 속에서 인간이 어떠한 [행동]을 보이는가에 대한 연구를 뜻한다.',m:null},
{t:'겟젤스와 구바는 사회체제 속에서 인간의 행동은 [사회적 조건]과 개인의 [심리적 특성] 간의 상호작용의 결과로 나타난다고 보았다.',m:null},
{t:'겟젤스와 텔렌은 겟젤스와 구바의 모형에 [인류학]적, [조직풍토]적, [생물학]적 차원을 추가하여 보다 다양한 사회적 행동을 설명하였다.',m:null},
{t:'한 개인의 행위가 목표로 하는 사회적 행동을 나타나려면 [합리성], [일치성], [소속감]을 모두 만족해야 한다.',m:null},
{t:'[의사결정]은 어떤 문제해결과 관련한 여러 가지 대안 중에서 한 가지 대안을 판단하여 선택, 결정하는 행위이다.',m:null},
{t:'[합리적 관점]은 합리적 판단으로서의 의사결정이다.',m:null},
{t:'합리적 판단은 합리성을 구현하기에 가장 적합한 조직인 [관료제]와 [수직적] 조직 구조를 가져 위계적인 체체에 의해 운영되는 [중앙집권적] 조직에 적합한 의사결정모형이다.',m:null},
{t:'[참여적 관점]은 합의로서의 의사결정이다.',m:null},
{t:'참여적 관점은 관련 당사자 간의 논의를 통한 [합의]의 결과로 보고 있다는 점이 합리적 관점과 구별된다.',m:null},
{t:'참여적 관점은 관료제적 조직보다 관련자의 능력과 자율이 보장되는 [전문적] 조직에 적합한 의사결정 모형으로, 학교에 적합한 의사결정모형이다.',m:null},
{t:'[정치적 과점]은 타협으로서의 의사결정이다.',m:null},
{t:'정치적 관점은 의사결정을 이해집단 간의 [타협]의 결과라 인식하고, [개방체제]를 전제한다는 점이 합리적 관점이나 참여적 관점과 다르다.',m:null},
{t:'정치적 관점은 [갈등]이 항상 존재하고 [타협]이 기본적 규칙으로 되어 있는 조직에 적합한 의사결정 모형이다.',m:null},
{t:'[우연적 관점]은 우연적 선택으로서 의사결정이다.',m:null},
{t:'우연적 관점은 목표가 불분명하고 목표 달성을 위한 방법적 체제나 관련 당사자의 참여체제가 제대로 정비되어 있지 않은 [무질서 속의 질서]에 적합한 의사결정모형이다.',m:null},
{t:'[합리모형]은 인간과 조직의 합리성과 지식 및 정보의 가용성을 전제로 한 이론모형이다.',m:null},
{t:'합리모형은 인간과 조직의 [합리성]과 지식 및 정보의 [가용성]을 전제로 한 이론모형이다.',m:null},
{t:'합리모형은 정책결정자의 전지전응함을 전제로 하나 그러한 전제가 [비현실적]이고, 현실적 측면보다는 [논리적 당위성]만 강조하여 구성원이 수용하기 어려운 대안을 선택하는 경우가 발생한다.',m:null},
{t:'[만족모형]은 마치와 사이먼이 제안한 의사결정 이론모형으로 최선의 결정은 절대적 의미에서 최고가 아닌 만족상태의 것이라는 생각을 반영하는 이론 모형이다.',m:null},
{t:'만족모형은 최적 대안보다 만족스러운 대안을 선택할 수밖에 없다는 점을 밝힘으로써 [합리모형]이 지닌 현실적 한계를 극복하였다.',m:null},
{t:'만족의 정도가 주관적이기 때문에 만족모형은 [보편타당성]이 부족하고, 조직 차원의 [거시적] 정책결정의 문제를 설명하는 데 무리가 있다.',m:null},
{t:'[점증모형]은 린드블럼이 제안한 의사결정 이론모형으로 점진적인 개선을 도모할 수 있는 대안만을 검토하는 현실성있는 정책을 선택하려는 방안을 가진 모형이다.',m:null},
{t:'점증모형을 통해 첨예한 [갈등]을 야기하지 않고 정채게 대한 폭넓은 지지와 [실현가능성]이 높은 대안을 선택할 수 있다.',m:null},
{t:'점증모형은 드러난 문제나 불만의 해소에만 주력하는 보수적이고 대중적인 정책결정 모형으로 [혁신]적인 의사결정에는 부적합하다.',m:null},
{t:'점증모형은 [적극적]인 [선]의 추구보다는 [소극적]인 [악]의 제거에 관심을 둔다.',m:null},
{t:'혼합모형은 에치오니가 제안한 의사결정 이론모형으로 합리모형의 [이상주의]와 점증모형의 [보수주의]를 비판하고, 두 모형의 장점을 결합시킨 이론 모형이다.',m:null},
{t:'[혼합모형]은 에치오니가 제안한 의사결정 이론모형으로 합리모형의 이상주의와 점증모형의 보수주의를 비판하고, 두 모형의 장점을 결합시킨 이론 모형이다.',m:null},
{t:'혼합모형은 합리모형과 점증모형을 절충하여 기본방향의 설정 같은 것은 [합리모형]을, 기본방향 설정 후 특정 문제해결은 [점증모형]을 적용하였다.',m:null},
{t:'혼합모형은 [현실적]이고 바람직한 방향을 제시한다.',m:null},
{t:'혼합모형은 의사결정자의 기본 방향에 대한 통제의식을 제외하면 [점증모형]과 크게 다를 것이 없다.',m:null},
{t:'[최적모형]은 드로어가 제안한 의사결정 이론모형으로 합리모형과 점증모형을 절충하여 합리성과 초합리성을 동시에 고려하는 규범적인 모형이다.',m:null},
{t:'최적모형은 드로어가 제안한 의사결정 이론모형으로 합리모형과 점증모형을 절충하여 [합리성]과 [초합리성]을 동시에 고려하는 규범적인 모형이다.',m:null},
{t:'최적모형은 [초합리성]이 정책결정의 불가결한 요인임을 강조한다.',m:null},
{t:'[쓰레기통모형]은 코헨과 마치가 주장한 의사결정 모형으로 우연적 선택으로 의사결정이 이루어진다고 보는 모형이다.',m:null},
{t:'쓰레기통 모형의 의사결정은 문제, 해결책, 참여자, 선택의 기회가 서로 [다른] 시간에 [우연적 요인]에 의해 통 안에 모일 때 의사결정이 이루어진다.',m:null},
{t:'일반적인 의사결정 과정은 문제의 인식 및 정의 - 자료 수집 및 분석 - 문제해결을 위한 [준거설정] - 행동계획과 전략 개발 - 행동계획의 실행과 평가 이다.',m:null},
{t:'브리지스의 참여적 의사결정모형에서 구성원의 참여 여부 결정 기준은 [수용영역]으로, 구성원이 상급자의 어떤 의사결정에 대해 [의심]할 여지 없이 기꺼이 받아들이는 영역이다.',m:null},
{t:'브리지스의 참여적 의사결정 모형에서 수용영역의 판단기준은 [적절성]과 [전문성]으로, 두 기준의 유무로 참여적 의사결정 유형을 분류한다.',m:null},
{t:'구성원이 적절성과 전문성을 모두 가지고 있는 경우, 구성원은 [수용영역 밖]에 존재한다.',m:null},
{t:'구성원이 적절성과 전문성 둘 중 하나를 가지고 있는 경우, 구성원은 [한계영역]에 존재한다.',m:null},
{t:'구성원이 적절성과 전문성 모두 없는 경우, 구성원은 [수용영역 안]에 존재한다.',m:null},
{t:'구성원이 [수용영역 밖]에 존재하는 경우 리더는 구성원을 의사결정 과정에 적극적으로 참여시키고, 소수의 의견까지 보장하여 의사결정이 이루어지도록 한다.',m:null},
{t:'구성원이 [수용영역 안]에 존재하는 경우 리더는 구성원을 의사결정 과정에 참여시킬 필요가 없다.',m:null},
{t:'구성원이 한계영역에 존재할 때, 리더는 구성원을 부분적으로 참여시켜 의사결정에 감정적 [반항]을 감소시킨다.',m:null},
{t:'호이와 타터의 참여적 의사결정 규범모형에서 수용영역 판단의 기준은 기존의 [적절성]과 [전문성]과 추가된 [신뢰도]이다.',m:null},
{t:'[민주적] 상황은 의사결정 사항이 수용영역 외부에 있으며 구성원들이 조직의 이익을 극대화할 수 있는 결정을 내릴 것이라고 신뢰할 수 있는 경우이다.',m:null},
{t:'[갈등적] 상황은 의사결정 사항이 수용영역 외부에 있으며 구성원들을 거의 신뢰할 수 없는 경우이다.',m:null},
{t:'[이해관계자적] 상황은 의사결정 사항에 대해 구성원들이 적절성을 충족하지만 전문성이 부족한 경우이다.',m:null},
{t:'[전문가적] 상황은 의사결정 사항에 대해 구성원들이 전문성을 충족하지만 적절성이 부족한 경우이다.',m:null},
{t:'[비협력적] 상황은 의사결정 사항이 수용영역 안에 있는 경우이다.',m:null},
{t:'민주적 상황에서 상급자는 합의를 얻기 위해 [통합자]의 역할을 하거나, 집단의 의견을 조율하기 위해 [정치가]의 역할을 해야한다.',m:null},
{t:'갈등적 상황과 이해관계자적 상황에서 상급자는 결정안이 수용되도록 사항을 설명하는 [교육자]의 역할을 해야한다.',m:null},
{t:'전문가적 상황에서 상급자는 구성원에게 의사결정의 질을 높이기 위해 조언을 구하는 [의뢰인]의 역할을 해야한다.',m:null},
{t:'비협력적인 상황에서 상급자는 효율성을 달성하기 위해 [지시자]의 역할을 해야한다.',m:null},
{t:'[공식적 의사소통]은 공식조직 내에서 공식적인 통로와 수단을 통해 이루어지는 의사소통방식이다.',m:null},
{t:'공식적 의사소통은 전달자와 피전달자가 명확하여 [책임소재]가 명확하지만, 융통성이 없고 소통이 느리며, [기밀유지]가 곤란하다.',m:null},
{t:'[비공식적 의사소통]은 조직구성원 간의 친분, 상호. 신뢰와 현실적인 인간관계 등을 통하여 이루어지는 의사소통방식이다.',m:null},
{t:'비공식적 의사소통은 [신속]한 의사소통이 가능하나, [책임소재]가 불분명하고, 공식적 의사소통 기능을 [마비]시킬 수 있다.',m:null},
{t:'조하리의 창에서 자신에 관한 정보가 자신과 타인에게 잘 알려져 있는 부분은 [개방적 영역]이다.',m:null},
{t:'[리더십]은 조직 목적의 달성을 위해 영향력을 행사하는 집단과정이다.',m:null},
{t:'[리더십 특성론]은 지도자는 선천적인 지도자적 특성을 지니고 있다고 보고, 지도자가 공통적으로 구비하고 있는 특성과 자질을 연구대상으로 삼는다.',m:null},
{t:'[리더십 행위론]은 성공적인 지도자가 어떻게 행동하는가를 알기 위하여 효과적인 지도자와 비효과적인 지도자의 행위를 비교하는 것이다.',m:null},
{t:'[상황적 리더십] 이론은 효과적인 리더십은 지도자의 개인적 특성, 지도자의 행위, 리더십 상황의 요인 간의 상호작용에 의하여 결정된다는 이론이다.',m:null},
{t:'피들러의 상황이론에서 상황의 호의성(3차원)에 해당되는 요소는 [지도자와 구성원의 관계], [과업구조], 지도자의 [지위권력]이다.',m:null},
{t:'피들러의 상황이론에서 상황이 호의적이지 않은 경우 적합한 리더십 유형은 [과업지향적] 리더십이다.',m:null},
{t:'피들러의 상황이론에서 상황이 호의적인 경우 적합한 리더십 유형은 [과업지향적] 리더십이다.',m:null},
{t:'피들러의 상황이론에서 상황의 호의성이 중간인 경우 적합한 리더십 유형은 [관계지향적] 리더십이다.',m:null},
{t:'피들러의 상황이론에서 지도자의 가장 싫어하는 동료 척도인 LPC 점수가 높은 지도자는 [관계지향적]이고, 점수가 낮은 지도자는 [과업지향적]이다.',m:null},
{t:'허시와 블랜차드의 상황적 리더십에서 리더의 행동을 결정짓는 요소는 [과업지향] 행동과 [관계지향] 행동이다.',m:null},
{t:'허시와 블랜차드의 상황적 리더십에서 구성원의 성숙도를 결정짓는 요소는 개인적 직무수행 능력인 [직무 성숙도]와 개인적 동기 수준인 [심리적 성숙도]이다.',m:null},
{t:'허시와 블랜차드의 상황적 리더십에서 구성원의 성숙도를 결정짓는 요소는 개인적 [직무수행] 능력인 직무 성숙도와 개인적 [동기] 수준인 심리적 성숙도이다.',m:null},
{t:'허시와 블랜차드의 상황적 리더십 모델에서 X축은 리더의 [과업 행동], Y축은 리더의 [관계 행동]이고, 상황변인으로 [구성원의 성숙도]이다.',m:null},
{t:'허시와 블랜차드의 상황적 리더십에서 [지시형]은 높은 과업 중심 행동, 낮은 관계 중심 행동을 보여주는 유형으로, 구성원의 동기와 능력이 [낮]을 때 효과적이다.',m:null},
{t:'허시와 블랜차드의 상황적 리더십에서 [지도형]은 높은 과업 중심 행동, 높은 관계 중심 행동을 보이는 유형으로, 구성원이 적절한 [동기]을/를 갖되 낮은 [능력]을/를 가지고 있는 경우에 효과적이다.',m:null},
{t:'허시와 블랜차드의 상황적 리더십에서 [지원형]은 낮은 과업 중심 행동, 높은 관계 중심 행동을 보이는 유형으로, 구성원이 적절한 [능력]을/를 갖되 낮은 [동기]을/를 가지고 있는 경우에 효과적이다.',m:null},
{t:'허시와 블랜차드의 상황적 리더십에서 [위임형]은 낮은 과업 중심 행동, 낮은 관계 중심 행동을 보여주는 유형으로, 구성원의 동기와 능력이 [높]을 때 효과적이다.',m:null},
{t:'[리더십 대용 상황모형]은 지도자의 행동이 어떤 상황에서는 중요한 영향을 주는 데 반해, 다른 상황에서는 왜 아무런 영향을 주지 못하는지를 이해하는 데 많은 도움을 준다.',m:null},
{t:'리더십 대용 상황으로 작용할 수 있는 상황 변인으로 [구성원], [과업], [특성]이 있다.',m:null},
{t:'[변혁적 리더십]은 번즈와 배스가 제안한 리더십으로 교환적 지도성과 반대되는 리더십으로 추종자들의 욕구와 능력을 인정하고 그들의 [잠재력]을 일깨워 사람들로 하여금 보다 더 훌륭한 사람으로 향상시키는 리더십이다.',m:null},
{t:'변혁적 리더십의 특징은 [이상적 영향], [영감적 동기 유발], [지적 자극], [개별적 배려]가 있다.',m:null},
{t:'변헉적 리더십 중 [이상적 영향]은 지도자가 자신보다 타인의 욕구를 배려하고 조직의 이익을 위해 행동하는 것을 토대로 구성원의 존경과 신뢰를 받고 칭송을 얻는 경우이다.',m:null},
{t:'변혁적 리더십 중 [영감적 동기 유발]은 지도자가 조직의 미래와 비전을 창출하는 데 사람들을 참여시키고, 조직이 발전할 수 있다고 믿도록 구성원의 동기를 변화시켜 단체정신 등을 이끌어 내는 경우이다.',m:null},
{t:'변혁적 리더십 중 [지적 자극]은 지도자가 일상적인 생각에 대해 의문을 제기하고, 문제를 재구조화하며, 조앨의 상황을 새로운 방식으로 접근함으로써 구성원들이 혁신적이고 창의적이 되도록 유도하는 경우이다.',m:null},
{t:'변혁적 리더십 중 [개별적 배려]는 성취하고 성장하려는 개개인의 욕구에 특별한 관심을 보여 새로운 학습 기회를 만들어 구성원의 잠재력 계발과 개인적 발전을 모색하는 경우이다.',m:null},
{t:'[카리스마적 리더십]은 베버가 제안한 리더십으로 탁월한 비전, 압도하는 인간적 매력을 소유한 지도자가 구성원의 헌신적인 복종과 충성을 바탕으로 나타내는 강력한 영향력이다.',m:null},
{t:'[슈퍼리더십]은 만즈와 심즈가 제안한 리더십으로 지도자가 조직의 모든 구성원이 스스로 자율적 리더십을 개발하고 이를 통해 조직의 과업수행을 효율화하고 조직의 생산성을 향상시키는 방향으로 일할 수 있도록 역량을 발휘하는 리더십이다.',m:null},
{t:'슈퍼리더십은 만즈와 심즈가 제안한 리더십으로 지도자가 조직의 모든 구성원이 스스로 [자율적 리더십]을 개발하고 이를 통해 조직의 과업수행을 효율화하고 조직의 생산성을 향상시키는 방향으로 일할 수 있도록 역량을 발휘하는 리더십이다.',m:null},
{t:'[자율적 리더십]은 구성원 각자가 스스로를 지도할 수 있는 능력을 발휘하는 것이다.',m:null},
{t:'[문화적 리더십]은 서지오바니가 제안한 리더십으로 인간의 의미추구욕구를 만족시켜 조직의 제도적 통합을 가능하게 하는 리더십이다.',m:null},
{t:'[버티컬 슬라이스]는 조직에서 각 계층을 대표하는 사람들이 직위에 관계없이 허심탄회하게 조직의 가치와 비전을 토론하고 조정할 수 있는 의사소통 방법으로, 학교조직에서 효과적인 문화(문화적 리더십)를 형성할 수 있게 한다.',m:null},
{t:'[도덕적 리더십]은 서지오바니가 제안한 리더십으로 지도자의 도덕성과 추종자들의 자율성 확보를 통해 추종자를 셀프리더, 지도자 자신이 슈퍼리더가 되어 궁극적으로 도덕적인 조직이 될 수 있도록 하는 리더십이다.',m:null},
{t:'[분산적 리더십]은 스필랜스와 쉐어러가 제안한 리더십으로 지도자 개인의 역량이나 시스템 안에 머물러 있는 것이 아닌 교장,교사 그리고 학교 상황, 교사의 상호작용에 의해 지도성이 분산되어 발휘되는 것이다.',m:null},
{t:'분산적 리더십은 학교조직이 너무 [복잡]하고 과제도 너무 광범위하기 때문에 개인이 모든 문제를 처리하기 어렵기에 필요하다.',m:null},
{t:'분산적 리더십을 통해 학교 일 의사결정이 [분산]되고, 교사는 교장의 학교경영에 대해 의사결정 개입이 가능하다.',m:null},
]},
{id:'u16',name:'직무동기·장학',items:[
{t:'[직무동기]는 직무환경에서 직무와 관련이 있는 행동을 개시하고 목표를 지향하는 한편, 이를 지속적으로 유지시키는 내적인 힘이다.',m:null},
{t:'동기이론은 사람에게 동기를 부여하는 특별한 요인을 식별하는 데 관심을 두는 [내용이론]과 동기를 유발하기 위하여 동기요인들이 상호작용하는 과정에 관심을 두는 [과정이론]으로 나뉜다.',m:null},
{t:'내용이론에는 [욕구위계이론], [동기]-[위생]이론, [생존]-[관계]-[성장](ERG)이론이 있다.',m:null},
{t:'과정이론에는 [기대이론], [공정성이론], [목표설정이론]이 있다.',m:null},
{t:'매슬로우의 욕구위계이론은 인간의 욕구는 [생리적] 욕구 - [안정]의 욕구 - [소속감]과 [애정]의 욕구 - [존경](존중)의 욕구 - [자아실현]의 욕구으로 3가지가 계층을 이루는 것을 주장하는 이론이다.',m:null},
{t:'매슬로우의 욕구위계이론은 동기 유발을 위한 [복합적] 접근의 필요성을 강조하였지만, 욕구 위계가 항상 [고정적]인 것은 아니어서 인간 행동의 여러 욕구요인이 상호복합적으로 작용하기도 한다.',m:null},
{t:'허즈버그의 [동기-위생이론]은 직무에 대하여 긍정적 혹은 부정적 태도를 유발시키는 요인을 탐색하기 위해 작업 환경에 관심을 둔 동기이론이다.',m:null},
{t:'[동기요인]은 직무만족을 가져다주는 것으로 밝혀진 요인으로 성취, 자기존중, 책임감 등이 있다.',m:null},
{t:'동기요인은 [직무만족]을 가져다주는 것으로 밝혀진 요인으로 성취, 자기존중, 책임감 등이 있다.',m:null},
{t:'동기요인은 미충족되어도 불만은 없지만, 충족하게 되면 [직무태도]와 [직무만족]에 긍정적인 영향을 줄 수 있다.',m:null},
{t:'[위생요인]은 직무불만족을 가져다주는 것으로 밝혀진 요인으로 보수, 근무조건, 대인관계, 통근시간 등이 있다.',m:null},
{t:'위생요인은 [직무불만족]을 가져다주는 것으로 밝혀진 요인으로 보수, 근무조건, 대인관계, 통근시간 등이 있다.',m:null},
{t:'위생요인은 충족이 단지 직무에 대한 불만족의 감소만을 가져올 뿐, 적극적으로 [직무만족]에 작용하지는 못한다.',m:null},
{t:'동기이론 충족을 위한 업무변화 활용방안으로 [직무풍요화], [직무특성이론], [경력단계프로그램]이 있다.',m:null},
{t:'[직무풍요화]는 작업자에게 자율성과 책임을 많이 부여하고, 개인적 성장과 의미 있는 작업 경험에 대한 기회가 제공될 수 있게끔 직무의 내용을 재편성하는 것이다.',m:null},
{t:'직무풍요화는 작업자에게 [자율성]과 [책임]을 많이 부여하고, 개인적 성장과 의미 있는 작업 경험에 대한 기회가 제공될 수 있게끔 직무의 내용을 [재편성]하는 것이다.',m:null},
{t:'[직무특성이론]은 직무에 내재된 특성이 심리상태를 변화시키고, 이러한 심리상태가 개인의 직무동기와 직무만족, 직무효과까지 높여주는 과정을 설명하는 이론이다.',m:null},
{t:'직무특성이론은 직무에 내재된 특성이 [심리상태]를 변화시키고, 이러한 심리상태가 개인의 직무동기와 직무만족, 직무효과까지 높여주는 과정을 설명하는 이론이다.',m:null},
{t:'[경력단계프로그램]은 교사들의 자격과 단계를 보다 세분화하여 직무의 다양성과 책임을 증가시켜 교직의 보람과 만족을 경험하게 하는 것으로, 예시로 [수석교사제]가 있다.',m:null},
{t:'엘더퍼의 [생존-관계-성장이론](ERG)는 조직에서 비고용자의 동기를 결정하는 중요한 요인이다.',m:null},
{t:'ERG에서 [생존욕구]는 인간이 생존을 위하여 필요로 하는 욕구로 대체로 매슬로우의 [생리적] 욕구와 [안정]의 욕구에 해당된다.',m:null},
{t:'ERG에서 [관계욕구]는 인간이 사회적 존재로서 타인과 인간관계를 맺고자 하는 욕구로, 대체로 매슬로우의 [소속감과 애정]의 욕구와 타인의 존경을 받고 싶어하는 욕구에 해당된다.',m:null},
{t:'ERG에서 [성장욕구]는 인간이 성장, 발전하고 잠재력을 최대한으로 발휘하고자 하는 내적 욕구로, 대체로 매슬로우의 [존경]의 욕구와 [자아실현]의 욕구에 해당된다.',m:null},
{t:'ERG이론은 매슬로우의 욕구위계이론과 달리 상위욕구가 충족되지 않거나 좌절될 때 그보다 낮은 하위욕구의 중요성이 커지는 현상인 [좌절-퇴행 접근]이 나타나고, 위계성이 약하다.',m:null},
{t:'브룸의 [기대이론]에서 개인의 동기는 노력한 결과 얻게 될 성취 수준에 대한 ‘성과기대’와 성과로 얻게 될 ‘보상기대’ 간의 함수이며, 이 두 가지는 개인이 느끼는 유인가에 의해 조정된다고 한다.',m:null},
{t:'브룸의 기대이론에서 개인의 동기는 노력한 결과 얻게 될 성취 수준에 대한 ‘[성과기대]’와 성과로 얻게 될 ‘[보상기대]’ 간의 함수이며, 이 두 가지는 개인이 느끼는 [유인가]에 의해 조정된다고 한다.',m:null},
{t:'유인가는 [보상]에 대해 개인이 느끼는 가치와 매력으로 [성과기대]와 [보상기대]는 개인이 느끼는 유인가에 의해 조정된다.',m:null},
{t:'[성과기대]는 노력을 하면 성과가 나올 것이라는 주관적인 믿음이다.',m:null},
{t:'[보상기대]는 성과가 보상으로 이어지게 될 것이라는 주관적인 믿음이다.',m:null},
{t:'기대이론은 학교경영자는 교사들이 [성과기대]를 형성하게 이끌고, [보상기대]를 분명히 해야 한다를 내포하고 있다.',m:null},
{t:'아담스의 [공정성이론]은 개인(자신)이 타인에 비해 얼마나 공정하게 대우받느냐에 초점을 둔 이론이다.',m:null},
{t:'공정성이론에서 개인이 과대보상이나 과소보상에 의해 [불공정성]을 지각하면 긴장감을 느끼게 되고 이러한 긴장을 해소하기 위해 [불공정성]을 감소시키는 방향으로 동기화가 진행된다.',m:null},
{t:'공정성이론은 학교경영자는 교사들을 공정하게 대우하도록 노력해야하고, 공정성에 대한 판단이 주관적이기 때문에 교사의 동기에 미치는 지각의 중요성을 고려하여 건설적인 [조직풍토]나 [조직문화]를 구축해야 한다를 내포하고 있다.',m:null},
{t:'로그와 라탐의 [목표설정이론]에서 인간의 동기는 가치와 목표에 의해 결정되는 것으로 파악하여 인간에게는 자신이 설정한 목표를 성취하려는 의도가 가장 중요한 동기가 될 수 있다고 한다.',m:null},
{t:'목표설정이론에서 좋은 목표의 속성으로 목표의 [구체성], 목표설정에의 [참여], 목표의 [수용성]등이 있다.',m:null},
{t:'구체적인 목표는 [모호성]을 감소시키고 행동 방향을 명확하게 제시하여 성과를 높일 수 있고, 구성원들이 목표 설정 과정에 참여하면 [직무만족]과 [성과]를 높여 줄 수 있다.',m:null},
{t:'[목표관리기법](MBO)는 목표설정을 활용한 기법으로 구성원이 상급자와 협의하여 측정가능하고 구체적인 목표를 설정하고 그 달성 정도를 스스로 평가하여 그 결과를 보고하는 관리기법이다.',m:null},
{t:'목표관리기법(MBO)는 모든 학교활동을 학교교육목표에 집중시킴으로써 교육의 [효율성]을 제고할 수 있고, 교직원의 [참여의식]을 높여 교직원의 [책무성]을 명료하게 한다.',m:null},
{t:'비공식조직의 순기능으로 개인의 정체감과 자존심을 높여주고 공식조직과 비공식조직이 조화를 이룰 때 집단의 단결력이 생겨 [의사소통]이 원활해진다.',m:null},
{t:'비공식조직의 역기능으로 공식조직의 의사소통을 [차단]하거나 왜곡하여 조직의 [혼란]을 야기할 수 있거나, 파벌 발생의 원인이 된다.',m:null},
{t:'[계선조직]은 행정의 수직적인 지휘명령계통이 명확히 정립되어 업무를 직접 수행하는 1차적 조직이다.',m:null},
{t:'[참모조직]은 계선조직의 기능을 원활하게 추진하도록 보조기능을 수행하는 조직이다.',m:null},
{t:'학교는 파슨즈의 사회적 기능 유형에서 체제의 문화유형을 유지하고 새롭게 하는 잠재기능을 수행하는 [유형유지조직]에 해당된다.',m:null},
{t:'학교는 블라우와 스콧의 1차적 수혜자 유형에서 고객에게 서비스를 제공하는 기능을 수행하는 [봉사조직]에 해당된다.',m:null},
{t:'학교는 칼슨의 봉사조직 유형에서 조직이나 고객 모두 독자적인 선택권을 갖지 못하는 [사육조직]에 해당된다.',m:null},
{t:'학교는 에치오니의 순응 유형에서 규범적 권력을 사용하여 구성원의 높은 헌신적 참여를 유도하는 [규범조직]에 해당된다.',m:null},
{t:'학교조직은 전문가로 구성된 관료제인 [전문적 관료제]의 특성과 불분명한 목표, 불확실한 기술, 유동적인 참여의 특징을 갖는 [조직화된 무질서 조직]의 특성을 갖는다.',m:null},
{t:'학교조직은 서로 연결은 되어 있으나 각자가 독자성을 유지하면서 어느 정도 분리되어 있는 모습인 [이완조직]의 특징을 갖는다.',m:null},
{t:'이완조직은 체제 내 참여자에게 보다 많은 [자유재량권]과 [자기결정권]을 제공하여 기발한 해결책의 개발을 장려한다.',m:null},
{t:'학교조직은 수업 등 특정 측면으로 보면 느슨한 결합 구조지만, 행정관리 등 보편적인 조직관리 측면에서는 엄격한 결합 구조를 보여주는 [이중조직]에 해당된다.',m:null},
{t:'[학교풍토]란 학교 구성원인 학생, 교사, 행정가들이 공유하는 가치관, 신념, 행동 표준 등 내적 특성을 뜻한다. 구성원 간의 공식적, 비공식적 인간관계에 의해 조성된다.',m:null},
{t:'핼핀과 크로프트의 학교풍토론은 [교사]집단의 행동특성과 [교장]의 행동특성을 변인으로 연구한 학교풍토로 [개방]-자율-통제-친교-간섭-폐쇄로 나뉜다.',m:null},
{t:'핼핀과 크로프트의 학교풍토 중 [개방적 풍토]는 목표를 향해 움직이고 학교 구성원의 사회적 욕구를 충족시켜주는 활기차고 생기있는 학교풍토로, 가장 바람직한 풍토이다.',m:null},
{t:'핼핀과 크로프트의 학교풍토 중 [폐쇄적 풍토]는 교장이 일상적인 일과 불필요한 일을 강조하고 교사들은 거의 만족감을 느끼지 못하는 비효율적인 학교풍토이다.',m:null},
{t:'호이 외 2인의 학교풍토 중 학교장의 행동과 교사의 행동 모두 개방적이어서 가장 바람직한 풍토는 [개방풍토]이다.',m:null},
{t:'호이 외 2인의 학교풍토 중 학교장의 행동은 폐쇄적이고, 교사의 행동은 개방적인 풍토는 [몰입풍토]이다.',m:null},
{t:'호이 외 2인의 학교풍토 중 학교장의 행동은 개방적이고, 교사의 행동은 폐쇄적인 풍토는 [일탈풍토]이다.',m:null},
{t:'호이 외 2인의 학교풍토 중 학교장의 행동과 교사의 행동 모두 폐쇄적인 풍토는 [폐쇄풍토]이다.',m:null},
{t:'리커트의 관리체제이론은 상급자와 하급자의 [관계]가 어떤떤가에 따라 조직의 특성을 4가지로 유형화한 것이다.',m:null},
{t:'리커트의 관리체제이론 중 제[1]이론은 처벌적 권위주의 체제이다.',m:null},
{t:'리커트의 관리체제이론 중 제[2]이론은 가부장적 권위주의 체제이다.',m:null},
{t:'리커트의 관리체제이론 중 제[3]이론은 상담적 권위주의 체제이다.',m:null},
{t:'리커트의 관리체제이론 중 제[4]이론은 참가적 체제로 가장 긍정적인 조직풍토이다.',m:null},
{t:'[조직문화]는 조직구성원들이 공유하고 있는 철학, 신념, 이데올로기, 감정, 가치관 등이다..',m:null},
{t:'학교조직문화의 3요소는 [이야기], 학교의 특성과 정체성의 징표인 [삽화]와 상징, 학교의 상징을 표현하는 조직 내 행사인 [의례]와 [의식]이다.',m:null},
{t:'맥그리거의 [X]이론은 적극적인 개입이 없으면 사람들은 조직의 필요에 저항하거나 수동적인 존재가 된다고 믿는 이론이다.',m:null},
{t:'맥그리거의 [Y]이론은 인간은 본질적으로 수동적이거나 게으르지 않고, 무책임하지 않고 조직의 필요에 저항하지도 않는다고 믿는 이론이다.',m:null},
{t:'아지리스의 미성숙-성숙이론은 조직관리자는 구성원을 [성숙]한 인간으로 취급하는 문화를 만들어야 한다 주장하고 있다.',m:null},
{t:'아지리스의 미성숙-성숙이론에서 미성숙은 [관료적] 가치를 따르는 조직으로 조직 효과성이 [감소]하고, 성숙은 [민주적] 가치를 따르는 조직으로 조직 효과성이 [증가]한다.',m:null},
{t:'세티아와 글리나우의 문화유형론은 조직의 관심이 [인간]에게 있느가와 [성과]에게 있는가에 따라 조직문화를 구분한 것으로, [통합문화]가 이상적인 조직문화이다.',m:null},
{t:'스타인호프와 오웬스의 학교문화 유형론은 공립학교의 문화형질을 비유를 통해 설명한 것으로 가족, 기계, [공연], 공포문화가 있다.',m:null},
{t:'스타인호프와 오웬스의 학교문화 유형 중 추구하는 문화는 [공연문화]이고, 학교를 공연장으로 비유하며 [청중]의 반응을 중시하고 훌륭한 교장 지도 아래 탁월하고 멋진 가르침을 추구하는 문화이다.',m:null},
{t:'[갈등]은 행동주체 간 나타나는 대립적 또는 적대적인 상호작용이다.',m:null},
{t:'갈등은 다양한 견해들로 인한 높은 질의 [아이디어]와 조직의 혁신과 변화를 유도하지만, 심한 경우 조직 와해와 [스트레스]를 야기할 수 있다.',m:null},
{t:'토머스의 갈등관리는 X축으로 [협동성]을, Y축으로 [독단성]을 설정하여 갈등을 감소시키기 위한 다섯 가지 유형의 갈등해결 방안을 제시한 것이다.',m:null},
{t:'토머스의 갈등관리에서 [협동성]은 한편이 상대편의 관심과 이익을 어느 정도 만족시켜주느냐와 관련된 것으로, [X]축으로 설정되었다.',m:null},
{t:'토머스의 갈등관리에서 [독단성]은 한편이 자기 자신의 이익과 관심을 어느 정도 만족시키려고 하느냐와 관련된 것으로, [Y]축으로 설정되었다.',m:null},
{t:'토머스의 갈등관리유형은 [경쟁형], [순응형], [타협형], [협력형], [회피형]이 있다.',m:null},
{t:'[경쟁형] 갈등관리는 상대방을 희생시키고 자신의 갈등을 해소하는 방식이다.',m:null},
{t:'[순응형] 갈등관리는 좋은 인간 관계를 유지하기 위해 자신의 욕구를 포기하고 상대방의 갈등이 해소되도록 노력하는 방식이다.',m:null},
{t:'[타협형] 갈등관리는 다수의 이익을 우선시하기 위해 양측이 상호교환과 희생을 통해 부분적 만족을 취하여 갈등을 해소하는 방식이다.',m:null},
{t:'[협력형] 갈등관리는 양쪽이 모두 만족하는 갈등해소책을 적극적으로 찾는 방식이다.',m:null},
{t:'[회피형] 갈등관리는 갈등이 없었던 것처럼 행동하여 의도적으로 피해 자기뿐만 아니라 상대의 관심마저 무시하는 방식이다.',m:null},
{t:'[학습조직]은 학교 내외적으로 교사들이 정보를 공유하고 협력적인 학습활동을 전개하여 지속적으로 새로운 지식을 창출하여 학교의 환경 변화에 적응해 나가는 조직이다.',m:null},
{t:'센게가 제안한 학습조직의 원리 3요소로 [개인적 숙련], [공유 비전], [팀 학습]이 있다.',m:null},
{t:'[전문적 학습공동체]는 교사의 학습과 전문성 개발을 위한 교사들의 자발적 모임이다.',m:null},
{t:'[교육기획]은 미래의 교육활동에 대비하여 교육목표 달성을 위한 효과적인 수단과 방법을 제시함으로써 교육정책 결정의 효율성과 안정성을 보장해주는 지적, 합리적인 과정으로 미래의 교육활동에 대한 사전준비과정이다.',m:null},
{t:'교육기획의 [사회수요적 접근법]은 교육에 대한 개인적, 사회적 수요를 기초로 교육계획을 수립하는 방법이다.',m:null},
{t:'[사회수요적 접근법]은 사회의 교육적 수요에 부응하여 단기적으로는 사회적, 정서적 안정에 기여할 수 있으나, 사회수요라는 개개인의 심리욕구 충족에 주안점을 두어 교육에 대한 사회적 필요와 동떨어진 교육계획을 수립할 가능성이 있다.',m:null},
{t:'교육기획의 [인력수요 접근법]은 경제성장을 뒷받침하는 인력수요를 예측하고 그에 기초하여 인력수요를 충족시킬수 있도록 교육적 측면의 공급을 조절해나가는 방법이다.',m:null},
{t:'[인력수요 접근접]은 교육운영에서 낭비를 줄여 효율성을 높일 수 있으나, 경제성장을 위한 인력공급이라는 외적 목적에 초점을 맞춰 교육의 본질을 훼손하는 교육의 수단화를 일으킬 수 있다.',m:null},
{t:'[교육인사행정]은 교육조직의 목적을 효과적으로 달성하는 데 필요한 교육직원의 채용과 그들의 계속적인 능력 개발 및 사기 양양을 도모하는 과정이다.',m:null},
{t:'교원의 능력계발법인 [현직교육]은 새로운 지식과 기능, 태도를 습득하여 교사의 [전문성]을 향상시킬 수 있다. 종류로 직무연수, 자격연수, 특별연수, 자율연수 등이 있다.',m:null},
{t:'[교육재정]은 국가 및 공공단체가 교육욕구를 충족하기 위해 필요한 수단을 조달하고 관리, 사용하는 경제활동이다.',m:null},
{t:'교육재정의 원리 중 재정확보 측면으로 [충족성]의 원리와 [자구성]의 원리가 있다.',m:null},
{t:'교육재정의 원리 중 [재정확보] 측면으로 충족성의 원리와 자구성의 원리가 있다.',m:null},
{t:'교육재정의 원리 중 [충족성]의 원리는 필요한 재원의 충분한 확보이다.',m:null},
{t:'교육재정의 원리 중 [자구성]의 원리는 중앙정부의 지원금 외에 필요한 추가 경비를 확보하기 위해 지방자치단체 스스로의 노력이 필요하다는 것이다.',m:null},
{t:'교육재정의 원리 중 재정배분 측면에서 [효율성]의 원리와 [공정성]의 원리가 있다.',m:null},
{t:'교육재정의 원리 중 [재정배분] 측면에서 효율성의 원리와 공정성의 원리가 있다.',m:null},
{t:'교육재정의 원리 중 [효율성]의 원리는 최소의 노력과 재정으로 최대의 교육효과를 얻어야한다는 것이다.',m:null},
{t:'교육재정의 원리 중 [공정성]의 원리는 특정 기준에 의해 재정 규모, 재정 배분 등에 있어서 차이가 나는 것을 정당하다고 보는 것이다.',m:null},
{t:'교육재정의 원리 중 재정지출 측면으로 [자율성]의 원리와 [적정성]의 원리가 있다.',m:null},
{t:'교육재정의 원리 중 [재정지출] 측면으로 자율성의 원리와 적정성의 원리가 있다.',m:null},
{t:'교육재정의 원리 중 [자율성]의 원리는 자신의 행위를 지배하는 규범이나 규칙을 스스로 선택하고 결정하며 실천하는 것이다.',m:null},
{t:'교육재정의 원리 중 [적정성]의 원리는 표준화된 성과를 산출할 수 있는 자원의 배분 그리고 교육 대상자의 필요를 충족시킬 수 있는 교육 프로그램의 양과 질 보장 측면을 강조하는 것이다.',m:null},
{t:'교육재정의 원리 중 재정평가 측면으로 [효과성]의 원리와 [책무성]의 원리가 있다.',m:null},
{t:'교육재정의 원리 중 [재정평가] 측면으로 효과성의 원리와 책무성의 원리가 있다.',m:null},
{t:'교육재정의 원리 중 [효과성]의 원리는 투입된 재원이 교육의 질적 향상을 가져오도록 해야하는 것이다.',m:null},
{t:'교육재정의 원리 중 [책무성]의 원리는 추가적인 재정이 투입되면 당연히 그에 상응하는 산출이 있어야 한다는 것이다.',m:null},
{t:'[품목별 예산제도]는 지출의 구체적 항목을 품목별로 세분화하여 지출대상과 그 한계를 명확히 규정하는 예산제도이다.',m:null},
{t:'품목별 예산제도는 예산의 [낭비]와 [부정] 방지에 유용하고, 각 항목에 대한 이해가 쉽고 [책임소재]가 분명하나 자유재량을 제한하여 갑작스러운 상황에 유연하게 대응하기 어렵다.',m:null},
{t:'[영기준 예산제도]는 전년도 사업을 인정하지 않고, 매 회계연도마다 모든 사업을 처음 시작한다고 생각하고, 설정하고자 하는 사업을 평가 및 조정하여 예산을 편성하는 예산제도이다.',m:null},
{t:'영기준 예산제도는 [교직원]들이 공동으로 참여하여 전문성을 향상시킬 수 있지만, [교직원]들의 시행착오 및 업무부담이 발생한다.',m:null},
{t:'[교육자치제]는 교육행정상 중앙행정의 통제를 지양하고 지방의 실정에 맞는 교육정책을 수립하여 이에 따른 교육행정 사무를 자주적으로 처리하는 것을 의미한다.',m:null},
{t:'[학교운영위원회]는 학생과 학부모 및 지역사회의 요구를 학교교육에 적극 반영함으로써 학교운영에 대한 정책결정의 민주성과 합리성, 투명성을 제고하여 학교의 자율성과 책무성을 강화하는 제도이다.',m:null},
{t:'학교운영위원회를 구성하는 위원은 [학부모]위원, [교원]위원, [지역]위원이다.',m:null},
{t:'[단위학교 자율경영](SBM)은 교육과정과 재정에 관한 결정이 단위학교에서 이루어지며, 단위학교에 의해서 집행되도록 학교를 자율경영하고 그 결과에 대해 책임을 지는 제도이다.',m:null},
{t:'[장학]은 교수행위를 개선을 위해 교사에게 제공되는 장학담당자의 모든 노력이다.',m:null},
{t:'장학의 본질은 교사의 [교수행위]에 변화를 통한 학생의 [학습] 향상, 교육과정과 내용의 개발&수정&보완을 통한 학생의 [성취] 고취, 교육자료와 학습환경 개선을 통한 학생의 학습 촉진 등으로 궁극적으로 [수업 개선]이다.',m:null},
{t:'[임상장학]은 교사의 전문적 성장과 교실수업 기술향상을 목적으로 한 교사와 학생의 상호 작용에 초점을 둔 상호작용적, 민주적, 교사 중심적 장학이다.',m:null},
{t:'임상장학에서 장학담당자와 교사는 서로 쌍방적 동료관계이고, 수업과 장학 전에 [협의회]를 실시한다.',m:null},
{t:'[동료장학]은 둘 이상의 교사가 서로 수업을 관찰하고 그에 대한 피드백을 통해 자신들의 전문적 성장을 위해 함께 하는 반형식적인 과정의 장학이다.',m:null},
{t:'[약식장학]은 단위학교의 교장이나 교감이 비공식적으로 순시를 통해 교사들의 수업 및 학급경영활동을 관찰하고, 이에 대해 교사들에게 피드백하는 과정이다.',m:null},
{t:'[자기장학]은 교사 스스로 자신의 전문성 신장을 위해 스스로 계획을 수립하고 실천하는 장학이다.',m:null},
{t:'[마이크로티칭]은 실제 상황의 수업이 아닌 시간과 대상을 축소하고, 학습주제나 활동을 제한하여 실시하는 연습수업이다.',m:null},
{t:'[인간관계론]적 장학에서 장학의 중요관점 및 결론은 학교 효과성 완성이다.',m:null},
{t:'[인간자원론]적 장학에서 장학의 중요관점 및 결론은 교사 직무만족도 증진이다.',m:null},
{t:'[컨설팅장학]은 교원의 자발적 의뢰를 바탕으로 교사의 전문성을 계발하기 위해 교내외의 전문성을 갖춘 사람들이 제공하는 조언 활동이다.',m:null},
{t:'컨설팅장학의 기본원리로 [자발성]의 원리, [전문성]의 원리, 자문성의 원리, [한시성]의 원리, 독립성의 원리, 학습성의 원리 등이 있다.',m:null},
]},
]},
];